INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (3, '2025-12-26 16:56:10.000', '2025-12-26 16:56:10.000', NULL, '香煎柠檬鸡胸肉配藜麦西兰花', '', '午餐', '简单', 20, 417.00, 39.30, 42.50, 10.00, '[\"鸡胸肉 120g\", \"藜麦 50g(干重)\", \"西兰花 150g\", \"圣女果 5颗\", \"橄榄油 5g\", \"柠檬 1/4个\", \"黑胡椒 适量\", \"盐 1g\", \"蒜末 5g\"]', '[\"藜麦洗净，加入适量水煮15分钟至熟透，沥干水分备用。\", \"西兰花洗净切小朵，放入开水中焯水2分钟，捞出过凉水沥干。\", \"鸡胸肉洗净，用厨房纸吸干水分，切成厚片，加入盐、黑胡椒、蒜末腌制10分钟。\", \"平底锅烧热，倒入橄榄油，放入腌制好的鸡胸肉，中小火煎至两面金黄熟透（约每面3-4分钟）。\", \"出锅前挤入少许柠檬汁提味。\", \"将煮好的藜麦铺在盘底，放上切好的鸡胸肉、西兰花和圣女果即可。\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (4, '2025-12-26 16:56:45.000', '2025-12-26 16:56:45.000', NULL, '蒜香西兰花烤鸡胸配红薯', '', '晚餐', '简单', 25, 365.00, 38.20, 35.00, 9.50, '[\"鸡胸肉 150g\", \"西兰花 200g\", \"红薯 100g\", \"大蒜 3瓣\", \"橄榄油 5g\", \"生抽 5g\", \"黑胡椒 少许\"]', '[\"红薯洗净去皮切块，放入蒸锅蒸15-20分钟至熟透。\", \"鸡胸肉洗净切块，加入蒜末、生抽、黑胡椒和2g橄榄油抓匀腌制10分钟。\", \"西兰花洗净切小朵，沸水中焯水2分钟捞出沥干。\", \"平底锅刷剩余3g橄榄油，放入腌好的鸡胸肉，中小火煎至两面金黄熟透。\", \"将蒸好的红薯、焯水的西兰花和煎好的鸡胸肉组合装盘即可。\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (5, '2025-12-26 16:58:09.000', '2025-12-26 16:58:09.000', NULL, '增肌特供：牛肉彩椒滑蛋全麦三明治配牛奶', '', '早餐', '简单', 15, 520.00, 42.50, 45.00, 18.50, '[\"瘦牛肉末 80g\", \"鸡蛋 2个\", \"全麦面包 2片\", \"红彩椒 30g\", \"纯牛奶 250ml\", \"橄榄油 5g\", \"黑胡椒 少许\", \"盐 少许\"]', '[\"将红彩椒洗净切成小丁备用。\", \"热锅倒入橄榄油，放入瘦牛肉末快速翻炒至变色，加入彩椒丁炒熟，撒少许黑胡椒和盐调味后盛出。\", \"利用锅中余油（或补少许油），打入鸡蛋煎成滑蛋或荷包蛋。\", \"将全麦面包放入烤面包机或平底锅烘烤至表面酥脆。\", \"组装三明治：在一片面包上铺满炒好的牛肉彩椒，放上鸡蛋，盖上另一片面包。\", \"搭配一杯温热的纯牛奶食用，补充优质蛋白。\"]', '[\"增肌\"]', '[\"牛肉\", \"蛋类\", \"麸质\", \"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (6, '2025-12-26 16:58:34.000', '2025-12-26 16:58:34.000', NULL, '黑椒藜麦牛排碗', '', '午餐', '简单', 20, 480.00, 36.00, 38.00, 16.00, '[\"牛里脊 150g\", \"三色藜麦 50g\", \"西兰花 100g\", \"橄榄油 10g\", \"蒜末 5g\", \"黑胡椒 适量\", \"盐 适量\"]', '[\"藜麦洗净，加入适量水煮15分钟至熟透沥干备用。\", \"西兰花切小朵，放入开水中焯水2分钟捞出备用。\", \"牛里脊切成厚片或小块，用少许盐和黑胡椒腌制5分钟。\", \"平底锅倒入橄榄油，中火烧热后放入蒜末爆香。\", \"放入腌制好的牛肉，煎至两面金黄熟透（约3-5分钟）。\", \"将煮好的藜麦铺底，放上西兰花和煎好的牛肉，撒上黑胡椒即可食用。\"]', '[\"增肌\"]', '[\"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (7, '2025-12-26 17:03:18.000', '2025-12-26 17:03:18.000', NULL, '清爽鸡丝荞麦凉面', '', '午餐', '简单', 15, 420.00, 32.00, 45.00, 8.00, '[\"荞麦面(干重) 50g\", \"鸡胸肉 120g\", \"黄瓜 100g\", \"胡萝卜 50g\", \"橄榄油 5g\", \"生抽 5g\", \"蒜末 3g\"]', '[\"1. 鸡胸肉冷水下锅煮熟，捞出放凉撕成细丝\", \"2. 荞麦面煮熟后过凉水，沥干备用\", \"3. 黄瓜和胡萝卜切成细丝\", \"4. 将所有食材混合，加入橄榄油、生抽和蒜末拌匀即可\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (8, '2025-12-26 17:03:18.000', '2025-12-26 17:03:18.000', NULL, '清蒸鳕鱼配红薯', '', '午餐', '简单', 20, 380.00, 35.00, 35.00, 6.00, '[\"鳕鱼 150g\", \"红薯 150g\", \"菠菜 150g\", \"姜丝 5g\", \"葱花 5g\", \"蒸鱼豉油 5g\"]', '[\"1. 红薯切片蒸熟，菠菜焯水断生\", \"2. 鳕鱼洗净铺上姜丝，大火蒸8-10分钟\", \"3. 倒掉蒸出的汤汁，淋上蒸鱼豉油\", \"4. 撒上葱花，搭配红薯和菠菜食用\"]', '[\"减脂\"]', '[\"海鲜\", \"高嘌呤\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (9, '2025-12-26 17:03:18.000', '2025-12-26 17:03:18.000', NULL, '黑椒芦笋炒牛肉', '', '午餐', '中等', 20, 460.00, 30.00, 40.00, 12.00, '[\"瘦牛肉 120g\", \"芦笋 150g\", \"水果玉米 100g\", \"黑胡椒碎 2g\", \"橄榄油 8g\", \"生抽 5g\", \"淀粉 2g\"]', '[\"1. 牛肉切薄片，用少许淀粉和生抽腌制10分钟\", \"2. 玉米煮熟剥粒，芦笋洗净切段焯水\", \"3. 热锅凉油，放入牛肉片滑炒至变色盛出\", \"4. 锅中留底油，放入芦笋和玉米翻炒，加入牛肉和黑胡椒碎炒匀即可\"]', '[\"减脂\"]', '[\"牛肉\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (10, '2025-12-26 17:03:18.000', '2025-12-26 17:03:18.000', NULL, '虾仁滑蛋杂粮碗', '', '午餐', '简单', 15, 450.00, 28.00, 45.00, 10.00, '[\"鲜虾仁 100g\", \"鸡蛋 1个\", \"杂粮饭(熟重) 150g\", \"西蓝花 100g\", \"橄榄油 5g\", \"盐 1g\"]', '[\"1. 西蓝花切小朵焯水煮熟\", \"2. 鸡蛋打散，虾仁洗净去线\", \"3. 锅中喷少许橄榄油，倒入蛋液炒至半凝固，加入虾仁滑熟\", \"4. 杂粮饭微波加热或蒸热，铺上西蓝花和虾仁滑蛋即可\"]', '[\"减脂\"]', '[\"海鲜\", \"高嘌呤\", \"蛋类\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (11, '2025-12-26 17:03:18.000', '2025-12-26 17:03:18.000', NULL, '蒜苔炒瘦肉配蒸玉米', '', '午餐', '简单', 20, 410.00, 25.00, 50.00, 9.00, '[\"瘦猪里脊 100g\", \"蒜苔 150g\", \"甜玉米 1根(约200g)\", \"大蒜 5g\", \"橄榄油 6g\", \"生抽 5g\"]', '[\"1. 玉米洗净蒸熟切段\", \"2. 猪里脊切丝，用少许生抽腌制\", \"3. 蒜苔洗净切段，大蒜切末\", \"4. 热锅凉油，炒香肉丝，加入蒜苔和大蒜末翻炒至熟，搭配玉米食用\"]', '[\"减脂\"]', '[\"猪肉\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (12, '2025-12-26 17:04:18.000', '2025-12-26 17:04:18.000', NULL, '玉米鸡蛋牛奶杯', '', '早餐', '简单', 10, 320.00, 18.00, 42.00, 10.00, '[\"甜玉米 1根(约200g)\", \"水煮蛋 1个\", \"脱脂牛奶 200ml\", \"小番茄 5个\"]', '[\"1. 玉米洗净切段，蒸熟或煮熟\", \"2. 鸡蛋煮熟剥壳\", \"3. 牛奶加热至温热\", \"4. 将所有食材装盘搭配食用\"]', '[\"减脂\"]', '[\"蛋类\", \"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (13, '2025-12-26 17:04:18.000', '2025-12-26 17:04:18.000', NULL, '鲜虾菠菜蒸红薯', '', '早餐', '简单', 15, 310.00, 22.00, 35.00, 6.00, '[\"红薯 150g\", \"鲜虾仁 100g\", \"菠菜 150g\", \"橄榄油 5g\", \"生抽 3g\"]', '[\"1. 红薯去皮切块，蒸熟备用\", \"2. 虾仁去线焯水煮熟\", \"3. 菠菜洗净焯水，挤干水分切段\", \"4. 将所有食材混合，淋入橄榄油和生抽拌匀即可\"]', '[\"减脂\"]', '[\"海鲜\"]', 10, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (14, '2025-12-26 17:04:18.000', '2025-12-26 17:04:18.000', NULL, '鸡丝荞麦粥', '', '早餐', '中等', 30, 300.00, 25.00, 38.00, 5.00, '[\"荞麦米 50g\", \"鸡胸肉 80g\", \"胡萝卜 30g\", \"香菇 2朵\", \"姜丝 少许\"]', '[\"1. 荞麦米提前浸泡半小时，煮成粥\", \"2. 鸡胸肉放入姜片煮熟，晾凉后撕成丝\", \"3. 胡萝卜切丁，香菇切片\", \"4. 将胡萝卜丁和香菇片放入粥中煮熟，最后加入鸡丝煮2分钟即可\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (15, '2025-12-26 17:04:18.000', '2025-12-26 17:04:18.000', NULL, '希腊酸奶坚果紫薯碗', '', '早餐', '简单', 10, 280.00, 15.00, 38.00, 8.00, '[\"紫薯 150g\", \"无糖希腊酸奶 100g\", \"核桃仁 10g\", \"蓝莓 20g\"]', '[\"1. 紫薯洗净蒸熟，去皮压成泥\", \"2. 将紫薯泥铺在碗底\", \"3. 淋上无糖希腊酸奶\", \"4. 撒上敲碎的核桃仁和蓝莓即可\"]', '[\"减脂\"]', '[\"乳制品\", \"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (16, '2025-12-26 17:04:18.000', '2025-12-26 17:04:18.000', NULL, '清蒸牛肉荞麦面', '', '早餐', '中等', 20, 350.00, 28.00, 45.00, 7.00, '[\"干荞麦面条 50g\", \"瘦牛肉 80g\", \"西蓝花 100g\", \"生抽 5g\", \"葱花 少许\"]', '[\"1. 荞麦面煮熟捞出过凉水，沥干\", \"2. 牛肉切薄片，铺在面条上蒸熟\", \"3. 西蓝花焯水煮熟\", \"4. 将西蓝花摆盘，淋上生抽，撒上葱花即可\"]', '[\"减脂\"]', '[\"牛肉\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (17, '2025-12-26 17:04:28.000', '2025-12-26 17:04:28.000', NULL, '甜玉米鸡胸肉沙拉', '', '加餐', '简单', 15, 320.00, 28.00, 25.00, 8.00, '[\"甜玉米粒 100g\", \"鸡胸肉 120g\", \"黄瓜 100g\", \"圣女果 50g\", \"油醋汁 10g\"]', '[\"1. 鸡胸肉冷水下锅煮熟，捞出撕成丝\", \"2. 黄瓜切丁，圣女果对半切开\", \"3. 玉米粒焯水煮熟沥干\", \"4. 所有食材混合，淋上油醋汁拌匀即可\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (18, '2025-12-26 17:04:28.000', '2025-12-26 17:04:28.000', NULL, '清爽荞麦虾仁凉面', '', '加餐', '简单', 20, 350.00, 22.00, 45.00, 6.00, '[\"干荞麦面 50g\", \"鲜虾仁 100g\", \"西芹 100g\", \"胡萝卜 50g\", \"橄榄油 5g\", \"生抽 5g\"]', '[\"1. 荞麦面煮熟后过凉水，沥干备用\", \"2. 虾仁去线焯水变色捞出，西芹和胡萝卜切丝焯水\", \"3. 将面条、虾仁和蔬菜丝放入碗中\", \"4. 加入橄榄油和生抽搅拌均匀即可\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (19, '2025-12-26 17:04:28.000', '2025-12-26 17:04:28.000', NULL, '紫薯希腊酸奶杯', '', '加餐', '简单', 10, 260.00, 15.00, 35.00, 4.00, '[\"蒸紫薯 150g\", \"无糖希腊酸奶 100g\", \"奇亚籽 5g\"]', '[\"1. 将蒸熟的紫薯去皮压成泥\", \"2. 在杯底铺一层紫薯泥\", \"3. 倒入一层希腊酸奶\", \"4. 重复铺层，顶部撒上奇亚籽即可食用\"]', '[\"减脂\"]', '[\"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (20, '2025-12-26 17:04:28.000', '2025-12-26 17:04:28.000', NULL, '荞麦蔬菜烘蛋', '', '加餐', '中等', 15, 280.00, 18.00, 20.00, 14.00, '[\"熟荞麦面 50g\", \"鸡蛋 2个\", \"菠菜 100g\", \"盐 1g\"]', '[\"1. 菠菜焯水切碎，挤干水分\", \"2. 鸡蛋打散，加入菠菜、熟荞麦面和盐搅拌均匀\", \"3. 平底锅刷少许油，倒入混合蛋液\", \"4. 小火烘至两面金黄熟透即可出锅\"]', '[\"减脂\"]', '[\"蛋类\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (21, '2025-12-26 17:04:28.000', '2025-12-26 17:04:28.000', NULL, '玉米番茄牛肉汤', '', '加餐', '简单', 25, 290.00, 25.00, 20.00, 10.00, '[\"甜玉米 100g\", \"瘦牛肉 100g\", \"番茄 100g\", \"姜片 2g\"]', '[\"1. 牛肉切丁，冷水下锅加姜片焯水去腥\", \"2. 番茄去皮切块，玉米切段\", \"3. 锅中加入适量水，放入玉米和牛肉炖煮20分钟\", \"4. 加入番茄块继续煮至软烂，加盐调味即可\"]', '[\"减脂\"]', '[\"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (22, '2025-12-26 17:07:52.000', '2025-12-26 17:07:52.000', NULL, '香煎三文鱼配藜麦牛油果碗', '', '晚餐', '简单', 25, 520.00, 32.00, 42.00, 22.00, '[\"三文鱼 150g\", \"三色藜麦 150g\", \"牛油果 1/4个\", \"芦笋 100g\", \"橄榄油 10g\", \"柠檬汁 少许\", \"黑胡椒 适量\"]', '[\"1. 藜麦洗净煮熟，沥干水分备用\", \"2. 三文鱼用盐、黑胡椒腌制，平底锅放橄榄油煎至两面金黄\", \"3. 芦笋焯水断生\", \"4. 牛油果切片，将所有食材摆盘，淋上柠檬汁即可\"]', '[\"增肌\"]', '[\"海鲜\", \"高嘌呤\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (23, '2025-12-26 17:07:52.000', '2025-12-26 17:07:52.000', NULL, '黑胡椒西冷牛排配红薯', '', '晚餐', '中等', 20, 480.00, 35.00, 38.00, 18.00, '[\"西冷牛排 150g\", \"红薯 150g\", \"西蓝花 100g\", \"橄榄油 8g\", \"大蒜 2瓣\", \"海盐 适量\"]', '[\"1. 牛排提前室温回温，两面撒上海盐和黑胡椒腌制\", \"2. 平底锅烧热橄榄油，放入大蒜和牛排，每面煎3-4分钟\", \"3. 红薯蒸熟切块，西蓝花焯水\", \"4. 牛排静置切片，搭配红薯和西蓝花食用\"]', '[\"增肌\"]', '[\"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (24, '2025-12-26 17:07:52.000', '2025-12-26 17:07:52.000', NULL, '坚果碎烤鸡胸配杂粮饭', '', '晚餐', '简单', 30, 490.00, 38.00, 45.00, 15.00, '[\"鸡胸肉 160g\", \"熟杂粮饭 150g\", \"核桃仁 15g\", \"圣女果 80g\", \"橄榄油 5g\", \"迷迭香 少许\"]', '[\"1. 鸡胸肉表面划刀，抹上橄榄油、盐和迷迭香\", \"2. 核桃仁压碎，粘在鸡胸肉表面\", \"3. 烤箱预热200度，烤20分钟至熟透\", \"4. 取出切块，搭配杂粮饭和圣女果\"]', '[\"增肌\"]', '[\"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (25, '2025-12-26 17:07:52.000', '2025-12-26 17:07:52.000', NULL, '蒜香虾仁全麦意面', '', '晚餐', '简单', 20, 460.00, 34.00, 48.00, 12.00, '[\"鲜虾仁 180g\", \"全麦意面 60g(干重)\", \"西兰花 80g\", \"大蒜 10g\", \"橄榄油 10g\", \"辣椒粉 少许\"]', '[\"1. 锅中烧水，放入全麦意面煮熟捞出\", \"2. 虾仁去线焯水变色后捞出\", \"3. 平底锅热橄榄油，爆香蒜末，放入虾仁和意面翻炒\", \"4. 加入焯熟的西兰花，撒少许盐和辣椒粉拌匀\"]', '[\"增肌\"]', '[\"海鲜\", \"麸质\", \"辛辣\", \"高嘌呤\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (26, '2025-12-26 17:07:52.000', '2025-12-26 17:07:52.000', NULL, '黑椒牛肉豆腐糙米饭', '', '晚餐', '简单', 20, 470.00, 33.00, 40.00, 16.00, '[\"瘦牛肉 120g\", \"老豆腐 100g\", \"糙米饭 150g\", \"青椒 50g\", \"洋葱 30g\", \"橄榄油 10g\"]', '[\"1. 牛肉切丁，豆腐切块，青椒洋葱切小块\", \"2. 锅中放橄榄油，煎香牛肉丁至变色盛出\", \"3. 同锅放入豆腐块煎至金黄\", \"4. 加入青椒洋葱翻炒，倒回牛肉，加黑胡椒调味，铺在糙米饭上\"]', '[\"增肌\"]', '[\"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (27, '2025-12-26 17:09:02.000', '2025-12-26 17:09:02.000', NULL, '深海三文鱼牛油果藜麦碗', '', '加餐', '简单', 15, 480.00, 32.00, 38.00, 20.00, '[\"三文鱼 150g\", \"牛油果 半个(约50g)\", \"藜麦(熟) 100g\", \"小番茄 50g\", \"柠檬汁 5g\", \"橄榄油 5g\"]', '[\"1. 三文鱼切块，平底锅小火煎至两面金黄（约3分钟）\", \"2. 牛油果去皮切块，小番茄对半切开\", \"3. 将煮熟的藜麦铺底，放上三文鱼、牛油果和小番茄\", \"4. 淋上橄榄油和柠檬汁拌匀即可\"]', '[\"增肌\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (28, '2025-12-26 17:09:02.000', '2025-12-26 17:09:02.000', NULL, '希腊酸奶坚果浆果杯', '', '加餐', '简单', 5, 420.00, 35.00, 45.00, 12.00, '[\"无糖希腊酸奶 300g\", \"混合坚果(杏仁/核桃) 30g\", \"蓝莓 80g\", \"香蕉 半根(约50g)\", \"奇亚籽 5g\"]', '[\"1. 将希腊酸奶倒入碗中打底\", \"2. 香蕉切片，蓝莓洗净\", \"3. 撒上混合坚果和奇亚籽\", \"4. 放入水果片，搅拌均匀即可食用\"]', '[\"增肌\"]', '[\"乳制品\", \"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (29, '2025-12-26 17:09:02.000', '2025-12-26 17:09:02.000', NULL, '黑椒牛肉全麦卷饼', '', '加餐', '中等', 20, 450.00, 33.00, 40.00, 14.00, '[\"瘦牛肉 120g\", \"全麦卷饼 1张(约50g)\", \"生菜 50g\", \"黑胡椒 2g\", \"橄榄油 5g\", \"低脂沙拉酱 10g\"]', '[\"1. 牛肉切条，用黑胡椒和少许盐腌制5分钟\", \"2. 平底锅加橄榄油，大火快炒牛肉至变色\", \"3. 全麦卷饼加热铺平，放上洗净的生菜和炒好的牛肉\", \"4. 挤上少许沙拉酱，卷起切段即可\"]', '[\"增肌\"]', '[\"牛肉\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (30, '2025-12-26 17:09:02.000', '2025-12-26 17:09:02.000', NULL, '水浸金枪鱼玉米沙拉', '', '加餐', '简单', 10, 400.00, 35.00, 35.00, 10.00, '[\"水浸金枪鱼罐头 150g\", \"甜玉米粒 80g\", \"黄瓜 80g\", \"紫甘蓝 50g\", \"煮熟鸡蛋 1个\", \"橄榄油 8g\"]', '[\"1. 金枪鱼沥干水分，黄瓜切丁，紫甘蓝切丝\", \"2. 玉米粒焯水煮熟沥干\", \"3. 煮熟鸡蛋切块\", \"4. 将所有食材放入大碗，加入橄榄油拌匀即可\"]', '[\"增肌\"]', '[\"海鲜\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (31, '2025-12-26 17:09:02.000', '2025-12-26 17:09:02.000', NULL, '燕麦鸡肉蔬菜饼', '', '加餐', '中等', 25, 380.00, 32.00, 30.00, 11.00, '[\"鸡胸肉 150g\", \"即食燕麦片 30g\", \"胡萝卜 30g\", \"鸡蛋 1个\", \"西兰花 50g\", \"橄榄油 5g\"]', '[\"1. 鸡胸肉剁成泥，胡萝卜和西兰花焯水后切碎\", \"2. 将鸡肉泥、蔬菜碎、燕麦片、鸡蛋混合，加少许盐调味\", \"3. 平底锅刷橄榄油，取适量肉泥压成小饼\", \"4. 小火煎至两面金黄熟透即可\"]', '[\"增肌\"]', '[\"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (32, '2025-12-26 17:09:39.000', '2025-12-26 17:09:39.000', NULL, '藜麦鸡胸肉配西蓝花', '', '午餐', '简单', 25, 420.00, 32.00, 38.00, 12.00, '[\"鸡胸肉 150g\", \"三色藜麦 50g\", \"西蓝花 200g\", \"橄榄油 10g\", \"大蒜 5g\", \"盐 1g\", \"黑胡椒 少许\"]', '[\"1. 藜麦洗净，加水煮15分钟至透明，沥干备用\", \"2. 鸡胸肉切丁，用少许盐和黑胡椒腌制\", \"3. 热锅凉油，放入蒜末爆香，加入鸡胸肉炒至变色\", \"4. 西蓝花焯水断生，捞出沥干\", \"5. 将藜麦、鸡胸肉和西蓝花混合拌匀即可\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (33, '2025-12-26 17:09:39.000', '2025-12-26 17:09:39.000', NULL, '芹菜炒牛肉配糙米饭', '', '午餐', '中等', 30, 480.00, 35.00, 42.00, 14.00, '[\"瘦牛肉 150g\", \"西芹 200g\", \"糙米 60g\", \"生姜 5g\", \"生抽 10ml\", \"植物油 10g\"]', '[\"1. 糙米提前浸泡，蒸熟备用\", \"2. 牛肉切丝，用生抽、姜丝腌制10分钟\", \"3. 芹菜洗净切段，焯水1分钟捞出\", \"4. 锅中倒油，大火快炒牛肉丝至变色盛出\", \"5. 锅留底油，放入芹菜翻炒，再加入牛肉丝混合均匀，搭配糙米饭食用\"]', '[\"控糖\"]', '[\"牛肉\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (34, '2025-12-26 17:09:39.000', '2025-12-26 17:09:39.000', NULL, '清蒸鲈鱼配菠菜红豆饭', '', '午餐', '简单', 35, 450.00, 30.00, 40.00, 15.00, '[\"鲈鱼 200g\", \"菠菜 250g\", \"红小豆 30g\", \"糙米 40g\", \"姜丝 10g\", \"葱丝 10g\", \"蒸鱼豉油 10ml\"]', '[\"1. 红豆和糙米混合，加水蒸熟\", \"2. 鲈鱼处理干净，放上姜丝，大火蒸8-10分钟\", \"3. 菠菜洗净焯水，挤干水分切段\", \"4. 蒸好的鱼淋上蒸鱼豉油，撒上葱丝\", \"5. 组合菠菜、红豆糙米饭和清蒸鲈鱼即可\"]', '[\"控糖\"]', '[\"海鲜\", \"高嘌呤\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (35, '2025-12-26 17:09:39.000', '2025-12-26 17:09:39.000', NULL, '豆腐油菜荞麦面', '', '午餐', '简单', 20, 380.00, 22.00, 45.00, 10.00, '[\"老豆腐 150g\", \"油菜 200g\", \"干荞麦面 60g\", \"芝麻油 5g\", \"盐 1g\", \"生抽 5ml\"]', '[\"1. 荞麦面煮熟，过凉水后沥干\", \"2. 豆腐切块，用开水焯一下去除豆腥味\", \"3. 油菜洗净，在沸水中烫熟\", \"4. 锅中加少许水，放入豆腐、生抽、盐小火炖煮3分钟\", \"5. 将豆腐汤汁淋在荞麦面上，旁边码上油菜，滴几滴芝麻油即可\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (36, '2025-12-26 17:09:39.000', '2025-12-26 17:09:39.000', NULL, '虾仁芦笋配杂粮饭', '', '午餐', '中等', 25, 410.00, 28.00, 35.00, 11.00, '[\"鲜虾仁 150g\", \"绿芦笋 200g\", \"杂粮米(含黑米/糙米) 60g\", \"橄榄油 8g\", \"柠檬汁 5ml\", \"大蒜 5g\"]', '[\"1. 杂粮米洗净，用电饭煲蒸熟\", \"2. 芦笋去老根，切段，焯水2分钟\", \"3. 虾仁去虾线，洗净沥干\", \"4. 平底锅倒入橄榄油，爆香蒜末，放入虾仁煎至变色\", \"5. 加入芦笋段快速翻炒，挤入柠檬汁提味，搭配杂粮饭食用\"]', '[\"控糖\"]', '[\"海鲜\", \"高嘌呤\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (37, '2025-12-26 17:10:22.000', '2025-12-26 17:10:22.000', NULL, '清蒸豆腐配菠菜糙米饭', '', '晚餐', '简单', 25, 380.00, 18.00, 42.00, 12.00, '[\"老豆腐 100g\", \"菠菜 200g\", \"糙米饭 150g\", \"橄榄油 8g\", \"大蒜 5g\", \"生抽 5g\"]', '[\"1. 糙米饭提前蒸熟备用\", \"2. 菠菜洗净焯水1分钟，去除草酸，沥干水分\", \"3. 老豆腐切块，放入蒸锅蒸10分钟至热透\", \"4. 热锅凉油，爆香蒜末，加入菠菜快速翻炒\", \"5. 菠菜淋上少许生抽，搭配豆腐和糙米食用\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (38, '2025-12-26 17:10:22.000', '2025-12-26 17:10:22.000', NULL, '藜麦鸡胸肉炒西蓝花', '', '晚餐', '中等', 20, 420.00, 32.00, 38.00, 10.00, '[\"鸡胸肉 120g\", \"西蓝花 200g\", \"三色藜麦 50g\", \"橄榄油 10g\", \"黑胡椒 2g\", \"姜片 3g\"]', '[\"1. 藜麦洗净，放入锅中煮15分钟左右至透明，捞出沥干\", \"2. 鸡胸肉切丁，用少许黑胡椒和姜片腌制5分钟\", \"3. 西蓝花切小朵，放入开水中焯水2分钟至断生\", \"4. 锅中倒入橄榄油，中火将鸡丁滑炒至变色变熟\", \"5. 加入西蓝花和煮熟的藜麦，翻炒均匀调味即可出锅\"]', '[\"控糖\"]', '[]', 10, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (39, '2025-12-26 17:10:22.000', '2025-12-26 17:10:22.000', NULL, '芹菜炒牛肉配荞麦面', '', '晚餐', '中等', 20, 400.00, 28.00, 35.00, 11.00, '[\"瘦牛肉 100g\", \"西芹 200g\", \"干荞麦面 50g\", \"橄榄油 8g\", \"生抽 5g\", \"生姜 3g\"]', '[\"1. 荞麦面煮熟捞出，过凉水后沥干\", \"2. 牛肉切丝，用少许生抽腌制；芹菜切段焯水\", \"3. 热锅倒油，爆香姜丝，放入牛肉丝快炒至变色\", \"4. 加入芹菜段大火翻炒至熟\", \"5. 将炒好的芹菜牛肉盖在荞麦面上拌匀食用\"]', '[\"控糖\"]', '[\"牛肉\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (40, '2025-12-26 17:10:22.000', '2025-12-26 17:10:22.000', NULL, '白灼芦笋鲜虾配杂粮饭', '', '晚餐', '简单', 15, 390.00, 26.00, 40.00, 9.00, '[\"鲜虾仁 100g\", \"芦笋 200g\", \"黑豆糙米饭 150g\", \"橄榄油 5g\", \"柠檬汁 3g\", \"盐 1g\"]', '[\"1. 黑豆糙米饭蒸熟备用\", \"2. 虾仁去虾线洗净，芦笋去老根切段\", \"3. 锅中水烧开，分别放入虾仁和芦笋焯水3分钟\", \"4. 捞出沥干，淋上橄榄油和柠檬汁，撒少许盐\", \"5. 搭配杂粮饭食用\"]', '[\"控糖\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (41, '2025-12-26 17:10:22.000', '2025-12-26 17:10:22.000', NULL, '青椒炒蛋配小米粥', '', '晚餐', '简单', 20, 360.00, 15.00, 45.00, 10.00, '[\"鸡蛋 1个\", \"青椒 150g\", \"小米 30g\", \"橄榄油 8g\", \"盐 1g\"]', '[\"1. 小米加水煮成稠粥\", \"2. 鸡蛋打散，青椒切丝\", \"3. 锅中倒油，倒入蛋液炒熟盛出\", \"4. 利用底油炒香青椒丝，断生后倒入鸡蛋混合\", \"5. 搭配温热的小米粥食用\"]', '[\"控糖\"]', '[\"蛋类\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (42, '2025-12-26 17:15:07.000', '2025-12-26 17:15:07.000', NULL, '全麦鸡蛋三明治配鲜奶', '', '早餐', '简单', 15, 420.00, 25.00, 50.00, 12.00, '[\"全麦吐司 2片\", \"鸡蛋 1个\", \"低脂牛奶 200ml\", \"生菜 30g\", \"番茄 50g\", \"黄瓜 30g\", \"橄榄油 5g\", \"黑胡椒 少许\"]', '[\"1. 鸡蛋煮熟切块，生菜洗净沥干，番茄切片。\", \"2. 全麦吐司烘烤至微脆。\", \"3. 按顺序铺上生菜、番茄、鸡蛋，撒上黑胡椒，盖上另一片吐司。\", \"4. 搭配热牛奶食用。\"]', '[\"维持健康\"]', '[\"麸质\", \"蛋类\", \"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (43, '2025-12-26 17:15:07.000', '2025-12-26 17:15:07.000', NULL, '鲜虾藜麦能量沙拉', '', '早餐', '中等', 25, 400.00, 28.00, 45.00, 10.00, '[\"鲜虾 100g\", \"三色藜麦 50g\", \"毛豆 30g\", \"甜玉米粒 30g\", \"胡萝卜 30g\", \"牛油果 30g\", \"橄榄油 6g\", \"柠檬汁 少许\"]', '[\"1. 藜麦煮熟沥干，虾仁焯水煮熟。\", \"2. 胡萝卜切丁焯水，毛豆和玉米粒煮熟。\", \"3. 将所有食材放入碗中，加入橄榄油和柠檬汁拌匀。\", \"4. 切入牛油果块即可食用。\"]', '[\"维持健康\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (44, '2025-12-26 17:15:07.000', '2025-12-26 17:15:07.000', NULL, '清炖牛肉荞麦面', '', '早餐', '中等', 30, 450.00, 30.00, 55.00, 9.00, '[\"瘦牛肉 80g\", \"干荞麦面 60g\", \"菠菜 50g\", \"香菇 20g\", \"西兰花 50g\", \"姜丝 少许\", \"亚麻籽油 5g\", \"盐 1g\"]', '[\"1. 牛肉切片焯水，香菇切片。\", \"2. 锅中加水烧开，放入姜丝、牛肉和香菇炖煮15分钟。\", \"3. 加入荞麦面煮熟，放入菠菜和西兰花烫熟。\", \"4. 滴入亚麻籽油，加少许盐调味即可。\"]', '[\"维持健康\"]', '[\"牛肉\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (45, '2025-12-26 17:15:07.000', '2025-12-26 17:15:07.000', NULL, '希腊酸奶坚果果碗', '', '早餐', '简单', 10, 380.00, 26.00, 48.00, 11.00, '[\"无糖希腊酸奶 200g\", \"蓝莓 30g\", \"草莓 40g\", \"香蕉 50g\", \"核桃仁 10g\", \"奇亚籽 5g\", \"燕麦片 20g\", \"肉桂粉 少许\"]', '[\"1. 香蕉切片，草莓洗净切块。\", \"2. 将希腊酸奶倒入碗中。\", \"3. 依次铺上燕麦片、蓝莓、草莓、香蕉。\", \"4. 撒上核桃仁、奇亚籽和肉桂粉即可。\"]', '[\"维持健康\"]', '[\"乳制品\", \"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (46, '2025-12-26 17:15:07.000', '2025-12-26 17:15:07.000', NULL, '香菇鸡肉蔬菜粥', '', '早餐', '简单', 20, 380.00, 25.00, 50.00, 8.00, '[\"大米 50g\", \"鸡胸肉 80g\", \"鲜香菇 30g\", \"青菜 50g\", \"胡萝卜 30g\", \"姜丝 少许\", \"香油 3g\", \"盐 1g\"]', '[\"1. 大米煮成白粥底，鸡胸肉撕成细丝。\", \"2. 香菇和胡萝卜切小丁，青菜切碎。\", \"3. 粥中加入姜丝、香菇丁、胡萝卜丁煮熟。\", \"4. 放入鸡肉丝和青菜碎，煮至断生。\", \"5. 滴入香油，加少许盐调味。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (47, '2025-12-26 17:27:29.000', '2025-12-26 17:27:29.000', NULL, '黑椒芦笋鸡胸杂粮饭', '', '午餐', '简单', 20, 420.00, 35.00, 45.00, 8.00, '[\"鸡胸肉 150g\", \"甜玉米 100g\", \"芦笋 100g\", \"小番茄 50g\", \"橄榄油 5g\", \"黑胡椒碎 适量\", \"大蒜 2瓣\", \"盐 1g\"]', '[\"鸡胸肉切块，加入少许盐、黑胡椒腌制10分钟\", \"芦笋切段，小番茄对半切开\", \"热锅凉油，放入蒜末爆香，加入鸡胸肉煎至变色\", \"加入芦笋和玉米段翻炒，加少许水焖煮3分钟\", \"加入小番茄翻炒均匀，撒上黑胡椒即可出锅\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (48, '2025-12-26 17:27:29.000', '2025-12-26 17:27:29.000', NULL, '清爽虾仁荞麦面', '', '午餐', '简单', 15, 390.00, 28.00, 50.00, 6.00, '[\"荞麦面(干) 50g\", \"鲜虾 120g\", \"黄瓜 100g\", \"胡萝卜 50g\", \"生抽 5g\", \"香醋 3g\", \"香油 2g\"]', '[\"虾仁去虾线洗净，焯水变色后捞出备用\", \"黄瓜切丝，胡萝卜切丝焯水备用\", \"荞麦面煮熟，过凉水沥干\", \"将所有食材放入碗中，加入生抽、香醋、香油拌匀即可\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (49, '2025-12-26 17:27:29.000', '2025-12-26 17:27:29.000', NULL, '红薯炖牛肉配时蔬', '', '午餐', '中等', 45, 450.00, 32.00, 40.00, 12.00, '[\"牛瘦肉 120g\", \"红薯 150g\", \"西兰花 100g\", \"洋葱 30g\", \"姜片 2片\", \"生抽 5g\"]', '[\"牛肉切块，冷水下锅焯水去浮沫\", \"红薯去皮切滚刀块，洋葱切块\", \"锅中放入姜片、牛肉、红薯和适量水，小火炖煮30分钟\", \"加入洋葱和生抽继续炖10分钟\", \"最后加入焯过水的西兰花，煮2分钟即可\"]', '[\"减脂\"]', '[\"牛肉\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (50, '2025-12-26 17:27:29.000', '2025-12-26 17:27:29.000', NULL, '菠菜鸡蛋蒸豆腐配玉米', '', '午餐', '简单', 15, 380.00, 25.00, 35.00, 15.00, '[\"鸡蛋 2个\", \"老豆腐 100g\", \"菠菜 150g\", \"甜玉米 100g\", \"葱花 适量\", \"盐 1g\"]', '[\"菠菜焯水切段，豆腐切块\", \"鸡蛋打散，加入少许温水搅拌均匀\", \"将豆腐放入蒸碗，倒入蛋液，上锅蒸8分钟\", \"放入菠菜段和玉米粒，继续蒸3分钟\", \"出锅撒上葱花，滴入少许生抽即可\"]', '[\"减脂\"]', '[\"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (51, '2025-12-26 17:27:29.000', '2025-12-26 17:27:29.000', NULL, '香煎三文鱼配红薯泥', '', '午餐', '中等', 25, 480.00, 26.00, 30.00, 22.00, '[\"三文鱼 100g\", \"红薯 150g\", \"芦笋 100g\", \"柠檬 1/4个\", \"橄榄油 5g\", \"黑胡椒 适量\", \"海盐 1g\"]', '[\"红薯蒸熟压成泥，芦笋焯水备用\", \"三文鱼用厨房纸吸干水分，抹上海盐和黑胡椒腌制5分钟\", \"平底锅刷橄榄油，放入三文鱼中小火煎至两面金黄\", \"搭配红薯泥和芦笋摆盘\", \"挤上柠檬汁即可食用\"]', '[\"减脂\"]', '[\"海鲜\", \"高嘌呤\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (52, '2025-12-26 17:28:41.000', '2025-12-26 17:28:41.000', NULL, '香煎鸡胸肉配杂蔬玉米', '', '晚餐', '简单', 20, 420.00, 35.00, 38.00, 12.00, '[\"鸡胸肉 150g\", \"甜玉米 1根(约200g)\", \"西蓝花 100g\", \"橄榄油 8g\", \"黑胡椒 少许\", \"盐 1g\"]', '[\"1. 鸡胸肉切片，用少许盐和黑胡椒腌制10分钟\", \"2. 玉米切段煮熟，西蓝花焯水备用\", \"3. 平底锅刷橄榄油，煎熟鸡胸肉\", \"4. 将所有食材摆盘即可\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (53, '2025-12-26 17:28:41.000', '2025-12-26 17:28:41.000', NULL, '清蒸鲈鱼配红薯菠菜', '', '晚餐', '简单', 25, 380.00, 32.00, 35.00, 8.00, '[\"鲈鱼 150g\", \"红薯 150g\", \"菠菜 150g\", \"姜 3片\", \"葱 1根\", \"蒸鱼豉油 5ml\"]', '[\"1. 红薯切片蒸熟，菠菜焯水断生\", \"2. 鲈鱼洗净划刀，放上姜片葱段，水开后蒸8-10分钟\", \"3. 淋上少许蒸鱼豉油，搭配红薯和菠菜食用\"]', '[\"减脂\"]', '[\"海鲜\", \"高嘌呤\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (54, '2025-12-26 17:28:41.000', '2025-12-26 17:28:41.000', NULL, '鲜虾豆腐羹配紫薯', '', '晚餐', '简单', 20, 360.00, 28.00, 42.00, 6.00, '[\"鲜虾 100g\", \"嫩豆腐 100g\", \"紫薯 150g\", \"葱花 少许\", \"盐 1g\", \"淀粉 2g\"]', '[\"1. 紫薯切块蒸熟备用\", \"2. 虾仁去虾线焯水，豆腐切小块\", \"3. 锅中加水烧开，放入豆腐和虾仁煮2分钟\", \"4. 淋入水淀粉勾芡，加盐调味，撒上葱花，搭配紫薯食用\"]', '[\"减脂\"]', '[\"海鲜\", \"高嘌呤\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (55, '2025-12-26 17:28:41.000', '2025-12-26 17:28:41.000', NULL, '芹菜牛肉粒炒荞麦面', '', '晚餐', '中等', 25, 450.00, 30.00, 48.00, 11.00, '[\"瘦牛肉 120g\", \"干荞麦面 50g\", \"芹菜 150g\", \"胡萝卜 50g\", \"植物油 8g\", \"生抽 5ml\", \"大蒜 2瓣\"]', '[\"1. 荞麦面煮熟捞出过凉水\", \"2. 牛肉切粒，芹菜和胡萝卜切丁\", \"3. 热锅凉油，爆香蒜蓉，炒熟牛肉粒\", \"4. 加入芹菜丁和胡萝卜丁翻炒，最后放入荞麦面拌匀调味\"]', '[\"减脂\"]', '[\"牛肉\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (56, '2025-12-26 17:28:41.000', '2025-12-26 17:28:41.000', NULL, '木耳拌蛋配甜玉米', '', '晚餐', '简单', 15, 390.00, 20.00, 45.00, 10.00, '[\"鸡蛋 2个\", \"干木耳(泡发) 100g\", \"甜玉米 1根\", \"黄瓜 50g\", \"香油 2g\", \"醋 3ml\", \"盐 1g\"]', '[\"1. 鸡蛋煮熟切块，木耳和黄瓜切丝\", \"2. 玉米煮熟切段\", \"3. 将木耳、黄瓜、鸡蛋混合，加入少许盐、醋和香油拌匀\", \"4. 搭配玉米段食用\"]', '[\"减脂\"]', '[\"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (57, '2025-12-26 17:30:47.000', '2025-12-26 17:30:47.000', NULL, '清爽玉米鸡胸肉沙拉', '', '早餐', '简单', 15, 380.00, 32.00, 35.00, 9.00, '[\"甜玉米 100g\", \"鸡胸肉 120g\", \"黄瓜 100g\", \"小番茄 50g\", \"橄榄油 5g\", \"黑胡椒 少许\", \"盐 1g\"]', '[\"1. 鸡胸肉冷水下锅煮熟，捞出撕成小块\", \"2. 玉米粒焯水煮熟，黄瓜切块，小番茄对半切开\", \"3. 将所有食材放入碗中，加入橄榄油、黑胡椒和盐拌匀即可\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (58, '2025-12-26 17:30:47.000', '2025-12-26 17:30:47.000', NULL, '低脂荞麦鸡蛋蔬菜饼', '', '早餐', '简单', 20, 350.00, 18.00, 45.00, 8.00, '[\"荞麦面 80g\", \"鸡蛋 1个\", \"菠菜 100g\", \"脱脂牛奶 50ml\", \"盐 1g\", \"食用油 3g\"]', '[\"1. 菠菜焯水切碎，鸡蛋打散\", \"2. 将荞麦面、鸡蛋液、牛奶、菠菜碎和盐混合搅拌成糊状\", \"3. 平底锅刷少许油，倒入面糊摊平，小火两面煎熟即可\"]', '[\"减脂\"]', '[\"麸质\", \"蛋类\", \"乳制品\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (59, '2025-12-26 17:30:47.000', '2025-12-26 17:30:47.000', NULL, '红薯鲜虾藜麦粥', '', '早餐', '简单', 25, 320.00, 22.00, 40.00, 4.00, '[\"红薯 100g\", \"鲜虾 100g\", \"三色藜麦 30g\", \"姜丝 少许\", \"葱花 少许\", \"盐 1g\"]', '[\"1. 红薯去皮切小块，藜麦提前浸泡洗净\", \"2. 锅中加水烧开，放入红薯和藜麦煮20分钟至软烂\", \"3. 加入去壳挑线的鲜虾和姜丝，继续煮5分钟\", \"4. 出锅前加盐调味，撒上葱花\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (60, '2025-12-26 17:30:47.000', '2025-12-26 17:30:47.000', NULL, '彩椒黑椒牛肉荞麦面', '', '早餐', '中等', 20, 480.00, 26.00, 55.00, 10.00, '[\"干荞麦面 80g\", \"瘦牛肉 80g\", \"红黄彩椒 各50g\", \"洋葱 30g\", \"橄榄油 8g\", \"现磨黑胡椒 适量\", \"生抽 5ml\"]', '[\"1. 荞麦面煮熟捞出过凉水备用\", \"2. 牛肉切片，用少许生抽腌制；彩椒和洋葱切丝\", \"3. 热锅倒油，快炒牛肉至变色盛出\", \"4. 放入洋葱丝炒香，加入彩椒和荞麦面翻炒\", \"5. 最后加入牛肉，撒入黑胡椒翻炒均匀即可\"]', '[\"减脂\"]', '[\"牛肉\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (61, '2025-12-26 17:30:47.000', '2025-12-26 17:30:47.000', NULL, '牛奶坚果燕麦红薯碗', '', '早餐', '简单', 10, 350.00, 14.00, 45.00, 12.00, '[\"即食燕麦片 40g\", \"脱脂牛奶 200ml\", \"红薯 100g\", \"核桃仁 10g\", \"奇亚籽 5g\"]', '[\"1. 红薯蒸熟切块\", \"2. 将燕麦片放入碗中，倒入热牛奶搅拌均匀\", \"3. 加入蒸好的红薯块，撒上核桃仁和奇亚籽即可食用\"]', '[\"减脂\"]', '[\"乳制品\", \"坚果\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (62, '2025-12-26 17:32:29.000', '2025-12-26 17:32:29.000', NULL, '香煎深海三文鱼配藜麦', '', '晚餐', '简单', 25, 520.00, 42.00, 35.00, 22.00, '[\"三文鱼 200g\", \"三色藜麦(熟) 150g\", \"芦笋 100g\", \"橄榄油 10g\", \"柠檬汁 5g\", \"黑胡椒 适量\", \"大蒜 2瓣\"]', '[\"1. 藜麦提前煮熟备用，芦笋洗净切段焯水\", \"2. 三文鱼用厨房纸吸干水分，抹上黑胡椒和少许盐腌制5分钟\", \"3. 平底锅烧热橄榄油，放入蒜末爆香，放入三文鱼中小火煎至两面金黄\", \"4. 挤入柠檬汁提味，搭配藜麦和芦笋装盘即可\"]', '[\"增肌\"]', '[\"海鲜\", \"高嘌呤\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (63, '2025-12-26 17:32:29.000', '2025-12-26 17:32:29.000', NULL, '牛油果黑椒牛肉粒饭', '', '晚餐', '中等', 30, 580.00, 38.00, 40.00, 24.00, '[\"牛里脊肉 180g\", \"牛油果 半个\", \"糙米饭 150g\", \"西兰花 100g\", \"洋葱 50g\", \"橄榄油 8g\", \"现磨黑胡椒 适量\", \"生抽 5g\"]', '[\"1. 牛肉切成2cm见方的粒，用黑胡椒、少许生抽腌制\", \"2. 牛油果切块，西兰花焯水，洋葱切丁\", \"3. 热锅凉油，放入牛肉粒大火快炒至变色盛出\", \"4. 锅底留油炒香洋葱，加入牛肉粒和西兰花快速翻炒\", \"5. 碗中盛入糙米饭，铺上牛肉粒和牛油果即可\"]', '[\"增肌\"]', '[\"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (64, '2025-12-26 17:32:29.000', '2025-12-26 17:32:29.000', NULL, '虾仁腰果糙米炒饭', '', '晚餐', '简单', 20, 540.00, 36.00, 45.00, 20.00, '[\"鲜虾仁 200g\", \"熟糙米饭 180g\", \"腰果 20g\", \"胡萝卜 50g\", \"豌豆 30g\", \"鸡蛋 1个\", \"橄榄油 10g\", \"盐 2g\"]', '[\"1. 虾仁去虾线洗净，用少许盐腌制；鸡蛋打散炒熟备用\", \"2. 胡萝卜切丁，和豌豆一起焯水煮至断生\", \"3. 热锅倒入橄榄油，放入虾仁炒至变色卷曲\", \"4. 加入糙米饭、胡萝卜丁、豌豆和鸡蛋大火翻炒均匀\", \"5. 出锅前撒入烘焙腰果，拌匀即可\"]', '[\"增肌\"]', '[\"海鲜\", \"坚果\", \"蛋类\", \"高嘌呤\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (65, '2025-12-26 17:32:29.000', '2025-12-26 17:32:29.000', NULL, '低脂鸡胸肉芝士通心粉', '', '晚餐', '中等', 35, 560.00, 40.00, 55.00, 14.00, '[\"鸡胸肉 150g\", \"全麦通心粉(干) 70g\", \"低脂牛奶 100ml\", \"帕玛森芝士粉 20g\", \"西兰花 100g\", \"洋葱 30g\", \"橄榄油 5g\", \"玉米淀粉 3g\"]', '[\"1. 通心粉按包装说明煮熟，捞出沥干\", \"2. 鸡胸肉切丁，西兰花切小朵焯水\", \"3. 平底锅加橄榄油炒香洋葱，放入鸡胸肉炒至变色\", \"4. 加入牛奶和适量清水，煮开后加入玉米淀粉勾芡至浓稠\", \"5. 加入通心粉、西兰花和芝士粉，搅拌均匀煮至芝士融化\"]', '[\"增肌\"]', '[\"乳制品\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (66, '2025-12-26 17:32:29.000', '2025-12-26 17:32:29.000', NULL, '金枪鱼牛油果全麦卷', '', '晚餐', '简单', 15, 500.00, 35.00, 42.00, 18.00, '[\"水浸金枪鱼罐头 150g\", \"全麦卷饼 1张(大)\", \"牛油果 半个\", \"生菜 50g\", \"小番茄 5个\", \"希腊酸奶 20g\", \"黑胡椒 适量\"]', '[\"1. 金枪鱼沥干水分，加入希腊酸奶和黑胡椒拌匀成馅\", \"2. 牛油果切片，小番茄对半切开，生菜洗净沥干\", \"3. 全麦卷饼铺平，放上生菜叶、金枪鱼馅、牛油果片和小番茄\", \"4. 将卷饼紧密卷起，从中间斜切成两段即可食用\"]', '[\"增肌\"]', '[\"海鲜\", \"麸质\", \"乳制品\", \"高嘌呤\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (67, '2025-12-26 17:32:38.000', '2025-12-26 17:32:38.000', NULL, '牛油果燕麦蛋白碗', '', '早餐', '简单', 10, 520.00, 35.00, 55.00, 18.00, '[\"即食燕麦片 60g\", \"脱脂牛奶 250ml\", \"乳清蛋白粉 1勺 (约25g)\", \"牛油果 半个\", \"鸡蛋 1个\"]', '[\"1. 将牛奶倒入锅中加热，加入燕麦片煮3分钟至粘稠。\", \"2. 关火后加入乳清蛋白粉，快速搅拌均匀。\", \"3. 鸡蛋煮熟切块，牛油果切片。\", \"4. 将燕麦粥倒入碗中，铺上鸡蛋块和牛油果即可。\"]', '[\"增肌\"]', '[\"乳制品\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (68, '2025-12-26 17:32:38.000', '2025-12-26 17:32:38.000', NULL, '香煎三文鱼配藜麦', '', '早餐', '中等', 20, 480.00, 36.00, 30.00, 22.00, '[\"三文鱼 150g\", \"藜麦(熟) 150g\", \"芦笋 100g\", \"橄榄油 10g\", \"柠檬汁 少许\", \"黑胡椒 适量\"]', '[\"1. 藜麦提前蒸熟备用，芦笋洗净切段焯水。\", \"2. 平底锅刷橄榄油，放入三文鱼中小火煎至两面金黄。\", \"3. 撒入黑胡椒和柠檬汁调味。\", \"4. 盘中铺好藜麦和芦笋，放上煎好的三文鱼。\"]', '[\"增肌\"]', '[\"海鲜\"]', 10, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (69, '2025-12-26 17:32:38.000', '2025-12-26 17:32:38.000', NULL, '全麦鸡胸肉芝士三明治', '', '早餐', '简单', 15, 450.00, 38.00, 35.00, 15.00, '[\"全麦面包 2片\", \"鸡胸肉 120g\", \"低脂芝士片 1片\", \"生菜 2片\", \"番茄 3片\", \"橄榄油 5g\"]', '[\"1. 鸡胸肉用少许黑胡椒腌制，平底锅刷橄榄油煎熟切丁。\", \"2. 全麦面包放入烤面包机稍微烘烤。\", \"3. 在面包上依次铺上生菜、番茄、煎好的鸡胸肉和芝士片。\", \"4. 盖上另一片面包，对角切开即可。\"]', '[\"增肌\"]', '[\"麸质\", \"乳制品\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (70, '2025-12-26 17:32:38.000', '2025-12-26 17:32:38.000', NULL, '彩椒牛肉配红薯块', '', '早餐', '中等', 25, 500.00, 32.00, 40.00, 16.00, '[\"瘦牛肉 150g\", \"红薯 200g\", \"红黄彩椒 各50g\", \"核桃仁 10g\", \"洋葱 30g\", \"橄榄油 8g\"]', '[\"1. 红薯去皮切块蒸熟备用，牛肉切片，彩椒切块。\", \"2. 热锅凉油，放入洋葱碎爆香，加入牛肉片快速滑炒。\", \"3. 加入彩椒块翻炒断生，加盐调味。\", \"4. 出锅搭配蒸红薯，撒上核桃仁。\"]', '[\"增肌\"]', '[\"牛肉\", \"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (71, '2025-12-26 17:32:38.000', '2025-12-26 17:32:38.000', NULL, '虾仁滑蛋配全麦卷', '', '早餐', '简单', 15, 420.00, 34.00, 28.00, 14.00, '[\"鲜虾仁 150g\", \"鸡蛋 3个\", \"全麦卷饼皮 1张\", \"黄瓜 半根\", \"低脂沙拉酱 10g\", \"橄榄油 5g\"]', '[\"1. 虾仁去虾线焯水煮熟，鸡蛋打散加入少许盐。\", \"2. 平底锅刷橄榄油，倒入蛋液炒至半凝固，加入虾仁快速滑熟盛出。\", \"3. 全麦卷饼皮铺平，放上黄瓜条、虾仁滑蛋。\", \"4. 挤上少许沙拉酱，卷起切段即可。\"]', '[\"增肌\"]', '[\"海鲜\", \"蛋类\", \"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (72, '2025-12-26 17:33:13.000', '2025-12-26 17:33:13.000', NULL, '燕麦菠菜鸡蛋羹', '', '早餐', '简单', 15, 380.00, 18.00, 42.00, 14.00, '[\"即食燕麦片 30g\", \"鸡蛋 1个\", \"菠菜 100g\", \"橄榄油 5g\", \"盐 少许\"]', '[\"1. 菠菜洗净焯水，捞出切碎备用\", \"2. 锅中加水烧开，放入燕麦片煮成稠粥\", \"3. 打入鸡蛋搅拌，煮至蛋花凝固\", \"4. 加入菠菜碎和橄榄油，搅拌均匀调味即可\"]', '[\"控糖\"]', '[\"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (73, '2025-12-26 17:33:13.000', '2025-12-26 17:33:13.000', NULL, '藜麦鸡胸肉沙拉', '', '早餐', '中等', 25, 420.00, 32.00, 35.00, 12.00, '[\"三色藜麦 40g\", \"鸡胸肉 100g\", \"生菜 150g\", \"小番茄 50g\", \"橄榄油 8g\", \"柠檬汁 少许\"]', '[\"1. 藜麦提前浸泡，蒸熟备用\", \"2. 鸡胸肉煮熟撕成丝，加入少许盐调味\", \"3. 生菜洗净切段，小番茄对半切开\", \"4. 将所有食材放入碗中，淋上橄榄油和柠檬汁拌匀即可\"]', '[\"控糖\"]', '[]', 10, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (74, '2025-12-26 17:33:13.000', '2025-12-26 17:33:13.000', NULL, '荞麦面豆腐蔬菜汤', '', '早餐', '简单', 20, 360.00, 16.00, 48.00, 10.00, '[\"干荞麦面 50g\", \"嫩豆腐 100g\", \"小白菜 150g\", \"姜丝 少许\", \"低钠酱油 5g\"]', '[\"1. 荞麦面煮熟后捞出过凉水，沥干备用\", \"2. 锅中加水烧开，放入姜丝和豆腐块煮2分钟\", \"3. 加入洗净的小白菜，煮至变软\", \"4. 放入荞麦面，加入酱油调味即可出锅\"]', '[\"控糖\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (75, '2025-12-26 17:33:13.000', '2025-12-26 17:33:13.000', NULL, '全麦三文鱼牛油果开放三明治', '', '早餐', '简单', 10, 450.00, 22.00, 38.00, 20.00, '[\"全麦面包 1片\", \"烟熏三文鱼 50g\", \"牛油果 1/4个\", \"芝麻菜 50g\", \"黑胡椒 少许\"]', '[\"1. 全麦面包放入烤面包机烤至酥脆\", \"2. 牛油果捣成泥，均匀涂抹在面包片上\", \"3. 铺上洗净的芝麻菜和烟熏三文鱼\", \"4. 撒上少许黑胡椒即可食用\"]', '[\"控糖\"]', '[\"海鲜\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (76, '2025-12-26 17:33:13.000', '2025-12-26 17:33:13.000', NULL, '虾仁糙米蔬菜粥', '', '早餐', '中等', 40, 390.00, 20.00, 45.00, 8.00, '[\"糙米 40g\", \"鲜虾仁 80g\", \"菠菜 100g\", \"姜丝 少许\", \"香油 2g\"]', '[\"1. 糙米提前浸泡2小时，加水煮成软烂的粥\", \"2. 虾仁洗净去虾线，焯水变色后捞出\", \"3. 菠菜焯水切碎，去除草酸\", \"4. 将虾仁和菠菜碎加入粥中，煮开，加入姜丝和香油调味即可\"]', '[\"控糖\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (77, '2025-12-26 17:35:29.000', '2025-12-26 17:35:29.000', NULL, '金枪鱼牛油果全麦三明治', '', '加餐', '简单', 10, 420.00, 35.00, 38.00, 14.00, '[\"水浸金枪鱼罐头 150g\", \"全麦面包 2片\", \"牛油果 半个\", \"鸡蛋 1个\", \"生菜 适量\", \"黑胡椒 少许\"]', '[\"1. 将金枪鱼沥干水分捣碎，加入切片的牛油果拌匀\", \"2. 鸡蛋煮熟切片，全麦面包烤至微脆\", \"3. 面包铺上生菜，放入金枪鱼牛油果泥和鸡蛋片，撒黑胡椒即可\"]', '[\"增肌\"]', '[\"海鲜\", \"麸质\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (78, '2025-12-26 17:35:29.000', '2025-12-26 17:35:29.000', NULL, '希腊酸奶坚果莓果蛋白碗', '', '加餐', '简单', 5, 380.00, 40.00, 35.00, 10.00, '[\"无糖希腊酸奶 200g\", \"乳清蛋白粉 1勺 (约30g)\", \"香蕉 1根\", \"混合坚果 15g\", \"蓝莓 50g\"]', '[\"1. 将希腊酸奶倒入碗中\", \"2. 加入一勺乳清蛋白粉，搅拌均匀至浓稠\", \"3. 香蕉切片，撒上坚果碎和蓝莓即可食用\"]', '[\"增肌\"]', '[\"乳制品\", \"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (79, '2025-12-26 17:35:29.000', '2025-12-26 17:35:29.000', NULL, '香煎三文鱼配红薯块', '', '加餐', '中等', 20, 450.00, 32.00, 35.00, 18.00, '[\"三文鱼 150g\", \"红薯 150g\", \"橄榄油 5g\", \"柠檬汁 少许\", \"海盐 少许\", \"迷迭香 1支\"]', '[\"1. 红薯去皮切块，蒸熟备用\", \"2. 平底锅刷橄榄油，放入三文鱼和迷迭香，中小火煎至两面金黄\", \"3. 挤上柠檬汁，撒少许海盐，搭配蒸好的红薯块食用\"]', '[\"增肌\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (80, '2025-12-26 17:35:29.000', '2025-12-26 17:35:29.000', NULL, '藜麦牛肉能量沙拉', '', '加餐', '中等', 25, 410.00, 33.00, 32.00, 15.00, '[\"瘦牛肉 150g\", \"煮熟藜麦 150g\", \"杏仁 10g\", \"圣女果 50g\", \"黄瓜 50g\", \"橄榄油 8g\", \"生抽 少许\"]', '[\"1. 牛肉切粒，用少许生抽腌制后煎熟\", \"2. 圣女果对半切，黄瓜切丁，杏仁切碎\", \"3. 将牛肉粒、藜麦、圣女果、黄瓜混合，撒上杏仁碎，淋上橄榄油拌匀即可\"]', '[\"增肌\"]', '[\"牛肉\", \"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (81, '2025-12-26 17:35:29.000', '2025-12-26 17:35:29.000', NULL, '鸡肉黑豆全麦卷饼', '', '加餐', '简单', 15, 430.00, 36.00, 42.00, 12.00, '[\"鸡胸肉 150g\", \"全麦卷饼皮 2张\", \"黑豆 50g\", \"玉米粒 50g\", \"低脂芝士 20g\", \"生菜 适量\"]', '[\"1. 鸡胸肉煮熟撕成丝，黑豆和玉米粒焯水沥干\", \"2. 全麦卷饼皮铺平，放上生菜、鸡肉丝、黑豆、玉米粒和芝士\", \"3. 卷紧呈卷状，可微波炉加热10秒使芝士融化即可\"]', '[\"增肌\"]', '[\"麸质\", \"乳制品\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (82, '2025-12-26 17:35:44.000', '2025-12-26 17:35:44.000', NULL, '藜麦鸡胸肉菠菜沙拉', '', '午餐', '简单', 20, 420.00, 32.00, 35.00, 12.00, '[\"鸡胸肉 150g\", \"三色藜麦 50g\", \"菠菜 200g\", \"圣女果 50g\", \"橄榄油 8g\", \"柠檬汁 5g\", \"黑胡椒 少许\"]', '[\"1. 藜麦洗净煮熟，沥干水分备用\", \"2. 鸡胸肉冷水下锅煮熟，捞出撕成条状\", \"3. 菠菜焯水1分钟去除草酸，捞出挤干\", \"4. 将所有食材放入碗中，加入橄榄油、柠檬汁和黑胡椒拌匀即可\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (83, '2025-12-26 17:35:44.000', '2025-12-26 17:35:44.000', NULL, '清蒸鳕鱼配红豆饭', '', '午餐', '简单', 25, 480.00, 36.00, 45.00, 10.00, '[\"鳕鱼 150g\", \"红豆 30g\", \"大米 50g\", \"小白菜 200g\", \"姜丝 5g\", \"蒸鱼豉油 5g\"]', '[\"1. 红豆提前浸泡，与大米同煮成红豆饭\", \"2. 鳕鱼洗净切片，铺上姜丝，大火蒸8分钟\", \"3. 小白菜洗净切段，焯水烫熟\", \"4. 取出鳕鱼淋上蒸鱼豉油，搭配红豆饭和小白菜食用\"]', '[\"控糖\"]', '[\"海鲜\", \"高嘌呤\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (85, '2025-12-26 17:35:44.000', '2025-12-26 17:35:44.000', NULL, '木耳炒豆腐配玉米碴', '', '午餐', '简单', 20, 400.00, 24.00, 40.00, 14.00, '[\"硬豆腐 150g\", \"干木耳 10g\", \"油菜 200g\", \"玉米碴 50g\", \"葱花 5g\", \"橄榄油 10g\", \"盐 1g\"]', '[\"1. 玉米碴淘洗干净，加水煮成杂粮粥\", \"2. 木耳提前泡发撕小朵，豆腐切块，油菜洗净\", \"3. 锅中少许油，煎至豆腐表面微黄，盛出\", \"4. 锅中加水烧开，放入木耳和油菜焯水\", \"5. 锅中倒油爆香葱花，放入豆腐、木耳、油菜快速翻炒，加盐调味即可\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (86, '2025-12-26 17:35:44.000', '2025-12-26 17:35:44.000', NULL, '芦笋炒虾仁配燕麦饭', '', '午餐', '简单', 25, 460.00, 34.00, 42.00, 11.00, '[\"鲜虾仁 150g\", \"绿芦笋 200g\", \"燕麦米 60g\", \"大蒜 5g\", \"橄榄油 8g\", \"白胡椒粉 少许\"]', '[\"1. 燕麦米洗净，加水煮成燕麦饭\", \"2. 虾仁去虾线洗净，芦笋洗净切段\", \"3. 烧一锅水，水开后放入芦笋焯水30秒捞出\", \"4. 热锅倒油，放入蒜末爆香，加入虾仁快速翻炒至变色\", \"5. 加入芦笋翻炒均匀，撒入少许白胡椒粉，搭配燕麦饭食用\"]', '[\"控糖\"]', '[\"海鲜\", \"高嘌呤\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (87, '2025-12-26 17:36:45.000', '2025-12-26 17:36:45.000', NULL, '藜麦鸡胸肉配时蔬', '', '晚餐', '简单', 25, 420.00, 32.00, 38.00, 12.00, '[\"鸡胸肉 150g\", \"三色藜麦 50g\", \"西蓝花 100g\", \"菠菜 100g\", \"橄榄油 8g\", \"大蒜 5g\", \"生抽 5g\", \"盐 1g\"]', '[\"1. 藜麦洗净，加水煮15分钟至熟，沥干水分\", \"2. 鸡胸肉切丁，用少许生抽腌制5分钟\", \"3. 西蓝花切小朵，菠菜洗净切段\", \"4. 烧一锅水，水开后放入西蓝花和菠菜焯水1分钟，捞出沥干\", \"5. 热锅倒入橄榄油，爆香蒜末，放入鸡胸肉翻炒至变色\", \"6. 加入焯好的蔬菜快速翻炒，加盐调味\", \"7. 将藜麦饭铺底，放上鸡肉蔬菜即可\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (88, '2025-12-26 17:36:45.000', '2025-12-26 17:36:45.000', NULL, '虾仁豆腐煲配糙米饭', '', '晚餐', '中等', 30, 450.00, 28.00, 42.00, 14.00, '[\"鲜虾仁 120g\", \"老豆腐 100g\", \"糙米 50g\", \"油菜 150g\", \"生姜 5g\", \"植物油 8g\", \"盐 1g\"]', '[\"1. 糙米提前浸泡，蒸熟备用\", \"2. 虾仁开背去虾线，豆腐切块\", \"3. 油菜洗净，焯水备用\", \"4. 热锅倒油，放入姜片爆香\", \"5. 放入虾仁翻炒至变色，加入豆腐块轻轻翻动\", \"6. 加入少许清水，小火焖煮3分钟\", \"7. 加盐调味，铺上油菜，搭配糙米饭食用\"]', '[\"控糖\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (89, '2025-12-26 17:36:45.000', '2025-12-26 17:36:45.000', NULL, '芹菜炒牛肉配二米饭', '', '晚餐', '简单', 20, 400.00, 30.00, 35.00, 11.00, '[\"瘦牛肉 120g\", \"西芹 150g\", \"大米 25g\", \"小米 25g\", \"大蒜 5g\", \"植物油 8g\", \"生抽 5g\", \"淀粉 2g\"]', '[\"1. 大米和小米混合，蒸熟做成二米饭\", \"2. 牛肉切丝，用淀粉、生抽腌制10分钟\", \"3. 西芹洗净切段，焯水断生\", \"4. 热锅倒油，爆香蒜末\", \"5. 放入牛肉丝大火快炒至变色\", \"6. 加入西芹段翻炒均匀，加盐调味\", \"7. 出锅搭配二米饭食用\"]', '[\"控糖\"]', '[\"牛肉\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (90, '2025-12-26 17:36:45.000', '2025-12-26 17:36:45.000', NULL, '菠菜蒸蛋配蒸玉米', '', '晚餐', '简单', 20, 380.00, 20.00, 40.00, 14.00, '[\"鸡蛋 2个\", \"菠菜 200g\", \"甜玉米 1根(约200g)\", \"香油 3g\", \"盐 1g\", \"温水 100g\"]', '[\"1. 玉米洗净，蒸熟切段\", \"2. 菠菜洗净焯水，挤干水分切碎\", \"3. 鸡蛋打散，加入少许温水和盐搅拌均匀\", \"4. 蛋液过筛去泡沫，盖上保鲜膜\", \"5. 水开后上锅蒸8-10分钟\", \"6. 取出蒸蛋，铺上菠菜碎\", \"7. 淋上少许香油，搭配玉米食用\"]', '[\"控糖\"]', '[\"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (91, '2025-12-26 17:36:45.000', '2025-12-26 17:36:45.000', NULL, '木耳炒肉片配燕麦饭', '', '晚餐', '简单', 25, 390.00, 22.00, 38.00, 13.00, '[\"瘦里脊肉 100g\", \"干木耳 10g(泡发后约100g)\", \"小白菜 150g\", \"燕麦米 50g\", \"植物油 8g\", \"生抽 5g\", \"大蒜 5g\"]', '[\"1. 燕麦米洗净，蒸熟备用\", \"2. 木耳泡发撕小朵，小白菜洗净切段\", \"3. 猪肉切片，用生抽腌制\", \"4. 热锅倒油，爆香蒜末，放入肉片炒至变色\", \"5. 加入木耳翻炒1分钟\", \"6. 放入小白菜大火翻炒至断生\", \"7. 加盐调味，搭配燕麦饭食用\"]', '[\"控糖\"]', '[\"猪肉\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (92, '2025-12-26 17:37:11.000', '2025-12-26 17:37:11.000', NULL, '藜麦菠菜拌豆腐', '', '加餐', '简单', 15, 220.00, 12.00, 25.00, 8.00, '[\"三色藜麦 30g\", \"嫩豆腐 100g\", \"菠菜 150g\", \"橄榄油 5g\", \"生抽 3g\", \"盐 1g\"]', '[\"1. 藜麦洗净，加水煮约12-15分钟至透明，沥干水分备用\", \"2. 菠菜洗净焯水1分钟，捞出挤干切段\", \"3. 嫩豆腐切块，用开水烫一下去除豆腥味\", \"4. 将藜麦、菠菜、豆腐混合，淋入橄榄油、生抽和少许盐拌匀即可\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (93, '2025-12-26 17:37:11.000', '2025-12-26 17:37:11.000', NULL, '全麦鸡胸蔬菜卷', '', '加餐', '简单', 20, 240.00, 22.00, 20.00, 8.00, '[\"全麦面包片 1片\", \"鸡胸肉 50g\", \"生菜 50g\", \"黄瓜 50g\", \"低脂沙拉酱 5g\"]', '[\"1. 鸡胸肉煮熟撕成丝，加入少许盐和黑胡椒调味\", \"2. 黄瓜切条，生菜洗净沥干水分\", \"3. 全麦面包切去四边，用擀面杖压实\", \"4. 面包上铺生菜、黄瓜丝和鸡丝，挤上少许沙拉酱，卷起切段\"]', '[\"控糖\"]', '[\"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (94, '2025-12-26 17:37:11.000', '2025-12-26 17:37:11.000', NULL, '无糖酸奶坚果燕麦杯', '', '加餐', '简单', 5, 260.00, 15.00, 22.00, 12.00, '[\"无糖希腊酸奶 100g\", \"生核桃仁 10g\", \"传统燕麦片 20g\", \"奇亚籽 5g\", \"黄瓜几片（装饰）\"]', '[\"1. 准备一个透明玻璃杯\", \"2. 杯底铺上一层燕麦片和奇亚籽\", \"3. 倒入一半无糖希腊酸奶\", \"4. 撒上压碎的核桃仁，再倒入剩余酸奶\", \"5. 顶部可放少许黄瓜片装饰，直接食用\"]', '[\"控糖\"]', '[\"乳制品\", \"坚果\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (95, '2025-12-26 17:37:11.000', '2025-12-26 17:37:11.000', NULL, '牛肉菠菜杂豆汤', '', '加餐', '中等', 40, 210.00, 18.00, 15.00, 8.00, '[\"瘦牛肉 50g\", \"红扁豆 20g\", \"菠菜 150g\", \"姜片 3g\", \"盐 1g\"]', '[\"1. 红扁豆提前浸泡2小时，煮至软烂备用\", \"2. 瘦牛肉切丁，冷水下锅焯水去浮沫\", \"3. 锅中加入热水、姜片和牛肉丁，小火炖煮30分钟\", \"4. 加入煮好的扁豆继续煮5分钟\", \"5. 最后放入菠菜，煮软后加盐调味即可\"]', '[\"控糖\"]', '[\"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (96, '2025-12-26 17:37:11.000', '2025-12-26 17:37:11.000', NULL, '清蒸海鱼配玉米时蔬', '', '加餐', '简单', 15, 200.00, 20.00, 18.00, 6.00, '[\"海鲈鱼 80g\", \"甜玉米段 50g\", \"西蓝花 100g\", \"蒸鱼豉油 5g\", \"姜丝 2g\"]', '[\"1. 海鲈鱼洗净切段，铺上姜丝，放入蒸锅\", \"2. 西蓝花洗净切小朵，玉米切段\", \"3. 将西蓝花和玉米段一同放入蒸屉，大火蒸8-10分钟\", \"4. 取出蒸鱼，淋上蒸鱼豉油即可食用\"]', '[\"控糖\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (97, '2025-12-26 17:38:51.000', '2025-12-26 17:38:51.000', NULL, '彩椒鸡胸肉藜麦碗', '', '午餐', '简单', 25, 450.00, 32.00, 45.00, 12.00, '[\"鸡胸肉 150g\", \"三色藜麦 80g\", \"红甜椒 50g\", \"黄甜椒 50g\", \"西蓝花 100g\", \"橄榄油 8g\", \"大蒜 5g\", \"生抽 5g\", \"黑胡椒 少许\"]', '[\"1. 藜麦洗净，加水煮15分钟至透明，沥干备用\", \"2. 鸡胸肉切丁，用少许生抽和黑胡椒腌制\", \"3. 热锅倒橄榄油，炒香蒜末，加入鸡丁炒至变色\", \"4. 加入切块的彩椒和焯水后的西蓝花翻炒\", \"5. 倒入煮好的藜麦，混合均匀即可出锅\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (98, '2025-12-26 17:38:51.000', '2025-12-26 17:38:51.000', NULL, '虾仁豆腐糙米烩饭', '', '午餐', '简单', 20, 480.00, 35.00, 50.00, 13.00, '[\"鲜虾仁 120g\", \"嫩豆腐 100g\", \"糙米饭 150g\", \"冷冻杂蔬粒(玉米/豌豆/胡萝卜) 50g\", \"鸡蛋 1个\", \"小葱 5g\", \"橄榄油 6g\", \"盐 1g\"]', '[\"1. 虾仁去线洗净，豆腐切成小块\", \"2. 平底锅倒橄榄油，倒入虾仁炒至变色盛出\", \"3. 锅中放入杂蔬粒和糙米饭翻炒，加入少许水焖煮2分钟\", \"4. 放入豆腐块，轻轻推开，打入鸡蛋搅散\", \"5. 最后加入虾仁，撒入葱花和少许盐调味即可\"]', '[\"维持健康\"]', '[\"海鲜\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (99, '2025-12-26 17:38:51.000', '2025-12-26 17:38:51.000', NULL, '牛肉西葫芦全麦面', '', '午餐', '中等', 30, 500.00, 32.00, 55.00, 14.00, '[\"瘦牛肉 100g\", \"全麦挂面 80g\", \"西葫芦 150g\", \"樱桃番茄 80g\", \"洋葱 30g\", \"橄榄油 8g\", \"生抽 8g\", \"淀粉 3g\"]', '[\"1. 牛肉切片，用淀粉和少许生抽腌制\", \"2. 西葫芦切半圆片，洋葱切丝，番茄切块\", \"3. 水烧开煮面条，煮熟后捞出过凉水备用\", \"4. 热锅倒橄榄油，炒牛肉至变色，加入洋葱炒香\", \"5. 放入西葫芦和番茄翻炒出汁，倒入面条拌匀即可\"]', '[\"维持健康\"]', '[\"牛肉\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (100, '2025-12-26 17:38:51.000', '2025-12-26 17:38:51.000', NULL, '香煎三文鱼配时蔬土豆', '', '午餐', '简单', 25, 520.00, 28.00, 45.00, 20.00, '[\"三文鱼 120g\", \"小土豆 150g\", \"芦笋 100g\", \"小番茄 50g\", \"柠檬 1片\", \"橄榄油 10g\", \"海盐 少许\", \"黑胡椒 少许\"]', '[\"1. 土豆切块蒸熟，芦笋去老根切段\", \"2. 三文鱼用厨房纸吸干水分，抹上海盐和黑胡椒腌制5分钟\", \"3. 平底锅倒少许橄榄油，放入三文鱼中小火煎至两面金黄\", \"4. 利用锅底余油煎熟芦笋和小番茄\", \"5. 摆盘：放上蒸土豆、煎三文鱼和蔬菜，挤上柠檬汁\"]', '[\"维持健康\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (101, '2025-12-26 17:38:51.000', '2025-12-26 17:38:51.000', NULL, '番茄菠菜滑蛋杂粮饭', '', '午餐', '简单', 15, 460.00, 25.00, 48.00, 15.00, '[\"鸡蛋 2个\", \"大番茄 150g\", \"菠菜 100g\", \"杂粮饭 150g\", \"橄榄油 8g\", \"小葱 5g\", \"盐 1g\"]', '[\"1. 番茄切块，菠菜焯水切段，鸡蛋打散\", \"2. 热锅倒橄榄油，倒入蛋液快速滑炒至半熟盛出\", \"3. 锅中留底油，放入番茄炒出汁水\", \"4. 加入杂粮饭和菠菜翻炒均匀\", \"5. 倒回炒蛋，加盐调味，撒上葱花拌匀即可\"]', '[\"维持健康\"]', '[\"蛋类\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (102, '2025-12-26 18:00:34.000', '2025-12-26 18:00:34.000', NULL, '牛油果藜麦牛肉能量碗', '', '午餐', '简单', 25, 520.00, 36.00, 45.00, 18.00, '[\"瘦牛肉 150g\", \"三色藜麦 150g\", \"牛油果 50g\", \"西兰花 100g\", \"橄榄油 10g\", \"海盐 少许\"]', '[\"藜麦加水煮熟备用\", \"牛肉切粒用海盐腌制，平底锅煎至七成熟\", \"西兰花焯水断生\", \"将所有食材放入碗中，切块牛油果铺顶，淋上橄榄油\"]', '[\"增肌\"]', '[\"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (103, '2025-12-26 18:00:34.000', '2025-12-26 18:00:34.000', NULL, '香煎三文鱼配红薯泥', '', '午餐', '中等', 30, 550.00, 32.00, 40.00, 22.00, '[\"三文鱼 160g\", \"红薯 200g\", \"芦笋 100g\", \"柠檬汁 10g\", \"黑胡椒 少许\"]', '[\"红薯蒸熟压成泥\", \"三文鱼抹黑胡椒腌制，平底锅小火煎熟\", \"芦笋煎熟或焯水\", \"摆盘，三文鱼淋上柠檬汁，搭配红薯泥食用\"]', '[\"增肌\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (104, '2025-12-26 18:00:34.000', '2025-12-26 18:00:34.000', NULL, '坚果碎烤鸡胸肉糙米饭', '', '午餐', '简单', 35, 580.00, 42.00, 55.00, 16.00, '[\"鸡胸肉 180g\", \"糙米饭 150g\", \"混合坚果碎 15g\", \"胡萝卜 80g\", \"低钠酱油 10g\"]', '[\"鸡胸肉切块裹上坚果碎和酱油，烤箱200度烤20分钟\", \"糙米饭提前煮熟\", \"胡萝卜切丁同鸡胸肉一起烤熟\", \"将烤好的鸡肉和蔬菜铺在糙米饭上\"]', '[\"增肌\"]', '[\"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (105, '2025-12-26 18:00:34.000', '2025-12-26 18:00:34.000', NULL, '全麦意面配虾仁鸡蛋芝士', '', '午餐', '中等', 20, 620.00, 38.00, 65.00, 20.00, '[\"全麦意面 80g\", \"鸡蛋 2个\", \"虾仁 100g\", \"帕玛森芝士 20g\", \"西兰花 80g\", \"大蒜 5g\"]', '[\"意面煮至八成熟捞出\", \"虾仁焯水煮熟\", \"鸡蛋打散煎熟切块\", \"锅中炒香蒜末，加入意面、虾仁、鸡蛋和西兰花翻炒\", \"出锅撒上芝士碎\"]', '[\"增肌\"]', '[\"海鲜\", \"蛋类\", \"乳制品\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (106, '2025-12-26 18:00:34.000', '2025-12-26 18:00:34.000', NULL, '彩椒爆炒瘦猪肉荞麦面', '', '午餐', '简单', 15, 480.00, 33.00, 50.00, 12.00, '[\"瘦猪里脊 150g\", \"干荞麦面 60g\", \"红彩椒 50g\", \"绿彩椒 50g\", \"小米辣 5g\", \"生抽 10g\"]', '[\"荞麦面煮熟过凉水备用\", \"猪肉切丝用生抽腌制\", \"热锅少油炒熟肉丝，加入彩椒丝和小米辣翻炒\", \"倒入荞麦面快速翻炒均匀即可\"]', '[\"增肌\"]', '[\"猪肉\", \"辛辣\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (107, '2025-12-26 18:09:14.000', '2025-12-26 18:09:14.000', NULL, '希腊酸奶燕麦坚果杯', '', '加餐', '简单', 5, 380.00, 28.00, 42.00, 14.00, '[\"无糖希腊酸奶 200g\", \"即食燕麦片 40g\", \"混合蓝莓 60g\", \"核桃仁 10g\"]', '[\"将即食燕麦片放入杯底。\", \"倒入无糖希腊酸奶覆盖燕麦。\", \"洗净蓝莓铺在酸奶上。\", \"最后撒上敲碎的核桃仁即可食用。\"]', '[\"维持健康\"]', '[\"乳制品\", \"坚果\", \"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (108, '2025-12-26 18:09:14.000', '2025-12-26 18:09:14.000', NULL, '全麦金枪鱼蔬菜三明治', '', '加餐', '简单', 10, 400.00, 30.00, 40.00, 12.00, '[\"全麦面包片 2片\", \"水浸金枪鱼罐头 80g\", \"生菜叶 2片\", \"番茄片 30g\", \"橄榄油 5g\"]', '[\"将全麦面包片放入烤面包机稍微烤至表面酥脆。\", \"金枪鱼沥干水分，加入少许黑胡椒拌匀。\", \"在面包上依次铺上生菜叶、番茄片和金枪鱼肉。\", \"淋上橄榄油，盖上另一片面包，对角切开即可。\"]', '[\"维持健康\"]', '[\"海鲜\", \"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (109, '2025-12-26 18:09:14.000', '2025-12-26 18:09:14.000', NULL, '鸡胸肉牛油果水果沙拉', '', '加餐', '中等', 15, 390.00, 30.00, 35.00, 13.00, '[\"鸡胸肉 100g\", \"牛油果 50g\", \"苹果 100g\", \"混合生菜 50g\", \"油醋汁 5g\"]', '[\"鸡胸肉冷水下锅煮熟，捞出晾凉后撕成条状。\", \"苹果去皮去核切丁，牛油果去皮切丁。\", \"将混合生菜铺在碗底，放上鸡肉、苹果和牛油果。\", \"淋上油醋汁搅拌均匀即可。\"]', '[\"维持健康\"]', '[]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (110, '2025-12-26 18:21:47.000', '2025-12-26 18:21:47.000', NULL, '清蒸鲈鱼配杂粮饭', '', '晚餐', '简单', 25, 420.00, 32.00, 45.00, 12.00, '[\"鲈鱼 150g\", \"糙米 50g\", \"小米 25g\", \"胡萝卜 50g\", \"西兰花 100g\", \"香菇 30g\", \"生姜 5g\", \"小葱 5g\", \"亚麻籽油 5g\", \"低钠酱油 5ml\"]', '[\"鲈鱼洗净，鱼身划几刀，姜片、葱段塞入鱼肚。\", \"胡萝卜、西兰花、香菇切小块，与杂粮米一同上锅蒸15分钟。\", \"将鱼放入蒸锅，继续蒸8-10分钟至熟。\", \"蔬菜杂粮饭装盘，放上蒸好的鱼，淋少许低钠酱油和热过的亚麻籽油。\"]', '[\"维持健康\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (111, '2025-12-26 18:21:47.000', '2025-12-26 18:21:47.000', NULL, '鸡胸肉炒三色椒藜麦', '', '晚餐', '简单', 20, 390.00, 31.00, 42.00, 9.00, '[\"鸡胸肉 120g\", \"三色甜椒 150g\", \"藜麦 40g\", \"白玉菇 50g\", \"紫皮洋葱 30g\", \"大蒜 5g\", \"橄榄油 5g\", \"盐 1g\"]', '[\"藜麦煮熟备用。鸡胸肉切丁，用少许盐腌制。\", \"锅中放橄榄油，爆香蒜片和洋葱丝，加入鸡丁炒至变色。\", \"放入三色椒块和白玉菇，翻炒至蔬菜断生。\", \"加入煮熟的藜麦，快速翻炒均匀，调味即可。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (112, '2025-12-26 18:21:47.000', '2025-12-26 18:21:47.000', NULL, '豆腐菌菇蔬菜汤面', '', '晚餐', '简单', 15, 380.00, 28.00, 38.00, 8.00, '[\"全麦面条 60g\", \"北豆腐 100g\", \"金针菇 50g\", \"菠菜 80g\", \"海鲜菇 50g\", \"干木耳 5g（泡发后30g）\", \"海带 10g\", \"香油 3g\", \"白胡椒粉 1g\"]', '[\"干木耳、海带泡发，豆腐切块，菌菇洗净。\", \"锅中烧水，放入海带、木耳和菌菇煮出鲜味。\", \"下入全麦面条和豆腐块，煮至面条接近熟透。\", \"放入菠菜烫熟，最后滴入香油，撒少许白胡椒粉调味。\"]', '[\"维持健康\"]', '[\"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (113, '2025-12-26 18:21:47.000', '2025-12-26 18:21:47.000', NULL, '虾仁芦笋炒荞麦面', '', '晚餐', '简单', 15, 410.00, 29.00, 43.00, 11.00, '[\"虾仁 100g\", \"荞麦面 70g\", \"芦笋 100g\", \"鸡蛋 1个\", \"玉米粒 30g\", \"山茶油 5g\", \"生抽 5ml\"]', '[\"荞麦面煮熟过冷水。鸡蛋炒散备用。\", \"芦笋切段焯水。虾仁用少许料酒腌制后焯水。\", \"热锅少油，放入芦笋、玉米粒和虾仁翻炒。\", \"加入荞麦面和炒蛋，淋入生抽，快速翻炒均匀。\"]', '[\"维持健康\"]', '[\"海鲜\", \"蛋类\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (114, '2025-12-26 18:21:47.000', '2025-12-26 18:21:47.000', NULL, '牛肉杂蔬燕麦粥', '', '晚餐', '简单', 25, 400.00, 30.00, 41.00, 10.00, '[\"牛里脊肉 80g\", \"燕麦片 40g\", \"南瓜 80g\", \"芹菜 50g\", \"玉米粒 30g\", \"口蘑 40g\", \"香菜 5g\", \"亚麻籽油 3g\"]', '[\"牛肉切细丝，南瓜去皮切丁，芹菜、口蘑切碎。\", \"燕麦片与南瓜丁、玉米粒加水煮成粥底。\", \"粥底沸腾后，加入牛肉丝和口蘑碎，搅散煮5分钟。\", \"加入芹菜碎再煮2分钟，出锅前淋亚麻籽油，撒香菜。\"]', '[\"维持健康\"]', '[\"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (115, '2025-12-26 18:21:56.000', '2025-12-26 18:21:56.000', NULL, '酸奶水果燕麦杯', '', '加餐', '简单', 5, 350.00, 18.00, 50.00, 8.00, '[\"无糖酸奶 150g\", \"即食燕麦片 40g\", \"蓝莓 50g\", \"奇异果 50g\", \"杏仁片 10g\"]', '[\"在杯底铺一层即食燕麦片。\", \"倒入无糖酸奶，覆盖燕麦片。\", \"将蓝莓和切块的奇异果铺在酸奶上。\", \"最后撒上杏仁片即可。\"]', '[\"维持健康\"]', '[\"坚果\", \"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (116, '2025-12-26 18:21:56.000', '2025-12-26 18:21:56.000', NULL, '全麦鸡蛋蔬菜三明治', '', '加餐', '简单', 15, 380.00, 22.00, 45.00, 12.00, '[\"全麦吐司 2片\", \"鸡蛋 1个\", \"生菜叶 2片\", \"番茄 50g\", \"黄瓜 30g\"]', '[\"鸡蛋煮熟后切片。\", \"番茄、黄瓜洗净切片。\", \"在全麦吐司上依次铺上生菜叶、鸡蛋片、番茄片和黄瓜片。\", \"盖上另一片吐司，对角切开即可。\"]', '[\"维持健康\"]', '[\"麸质\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (117, '2025-12-26 18:21:56.000', '2025-12-26 18:21:56.000', NULL, '毛豆鹰嘴豆泥配蔬菜条', '', '加餐', '简单', 20, 320.00, 20.00, 35.00, 11.00, '[\"熟毛豆 100g\", \"熟鹰嘴豆 50g\", \"胡萝卜 50g\", \"黄瓜 50g\", \"紫甘蓝 30g\", \"柠檬汁 5g\", \"橄榄油 3g\"]', '[\"熟毛豆和熟鹰嘴豆放入料理机，加入柠檬汁和橄榄油，搅打成泥状。\", \"胡萝卜、黄瓜洗净切条，紫甘蓝切丝。\", \"将打好的豆泥盛入碗中，搭配蔬菜条食用。\"]', '[\"维持健康\"]', '[]', 10, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (118, '2025-12-26 18:21:56.000', '2025-12-26 18:21:56.000', NULL, '红薯牛奶饮', '', '加餐', '简单', 15, 300.00, 15.00, 48.00, 6.00, '[\"蒸熟红薯 100g\", \"牛奶 200ml\", \"奇亚籽 5g\"]', '[\"将蒸熟的红薯去皮切块。\", \"将红薯块、牛奶和奇亚籽一同放入料理机。\", \"高速搅打均匀至顺滑即可。\"]', '[\"维持健康\"]', '[\"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (119, '2025-12-26 18:21:56.000', '2025-12-26 18:21:56.000', NULL, '香蕉燕麦能量饼干', '', '加餐', '简单', 20, 400.00, 12.00, 60.00, 12.00, '[\"香蕉 1根（约120g）\", \"即食燕麦片 80g\", \"蔓越莓干 15g\", \"南瓜籽 10g\"]', '[\"香蕉用叉子压成泥。\", \"将燕麦片、蔓越莓干、南瓜籽加入香蕉泥中混合均匀。\", \"取适量混合物捏成饼状，放在铺了烘焙纸的烤盘上。\", \"放入预热好的烤箱，180度烤15分钟至表面金黄即可。\"]', '[\"维持健康\"]', '[\"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (120, '2025-12-26 18:27:21.000', '2025-12-26 18:27:21.000', NULL, '水煮蛋玉米蔬菜沙拉', '', '早餐', '简单', 15, 350.00, 25.00, 35.00, 8.00, '[\"水煮蛋 2个\", \"甜玉米粒 100g\", \"圣女果 100g\", \"黄瓜 100g\", \"生菜 50g\"]', '[\"鸡蛋冷水下锅，水沸后煮8分钟，捞出剥壳备用。\", \"生菜、黄瓜洗净切块，圣女果对半切开。\", \"将所有食材混合，可淋少许生抽或醋调味。\"]', '[\"减脂\"]', '[\"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (121, '2025-12-26 18:27:21.000', '2025-12-26 18:27:21.000', NULL, '鸡胸肉荞麦面', '', '早餐', '简单', 20, 380.00, 35.00, 45.00, 6.00, '[\"鸡胸肉 150g\", \"荞麦面 60g\", \"菠菜 100g\", \"胡萝卜 50g\"]', '[\"鸡胸肉切片，加少许盐和黑胡椒腌制10分钟。\", \"荞麦面煮熟捞出过凉水。\", \"锅中少油煎熟鸡胸肉，加入胡萝卜丝和菠菜翻炒。\", \"将所有食材混合拌匀。\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (122, '2025-12-26 18:27:21.000', '2025-12-26 18:27:21.000', NULL, '蒸红薯配无糖豆浆', '', '早餐', '简单', 25, 320.00, 18.00, 50.00, 5.00, '[\"红薯 200g\", \"无糖豆浆 300ml\"]', '[\"红薯洗净切块，上锅蒸20分钟至软糯。\", \"搭配一杯无糖豆浆饮用。\"]', '[\"减脂\"]', '[\"乳制品\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (123, '2025-12-26 18:27:21.000', '2025-12-26 18:27:21.000', NULL, '虾仁蔬菜燕麦粥', '', '早餐', '简单', 15, 290.00, 28.00, 35.00, 5.00, '[\"虾仁 100g\", \"燕麦片 40g\", \"香菇 50g\", \"青菜 100g\"]', '[\"香菇切片，青菜切碎。\", \"燕麦片加水煮成粥状。\", \"加入虾仁、香菇和青菜煮5分钟，加盐调味。\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (124, '2025-12-26 18:27:21.000', '2025-12-26 18:27:21.000', NULL, '豆腐菌菇蒸蛋', '', '早餐', '简单', 20, 280.00, 26.00, 15.00, 12.00, '[\"鸡蛋 2个\", \"内酯豆腐 150g\", \"金针菇 50g\", \"蟹味菇 50g\"]', '[\"鸡蛋打散，加入等量清水搅匀。\", \"豆腐切块铺在碗底，盖上菌菇。\", \"倒入蛋液，上锅蒸15分钟，出锅淋少许酱油。\"]', '[\"减脂\"]', '[\"蛋类\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (125, '2025-12-26 18:27:28.000', '2025-12-26 18:27:28.000', NULL, '香煎鸡胸肉玉米沙拉', '', '午餐', '简单', 20, 400.00, 35.00, 38.00, 12.00, '[\"鸡胸肉 150g\", \"甜玉米粒（熟） 100g\", \"生菜 100g\", \"小番茄 80g\", \"橄榄油 5g\", \"柠檬汁 10ml\", \"黑胡椒 少许\", \"盐 少许\"]', '[\"鸡胸肉用少许盐和黑胡椒腌制10分钟。\", \"平底锅刷少量橄榄油，将鸡胸肉煎至两面金黄熟透，取出切块。\", \"生菜洗净撕成小片，小番茄对半切开。\", \"将生菜、小番茄、熟玉米粒和鸡胸肉块放入碗中。\", \"用橄榄油、柠檬汁、盐和黑胡椒调成油醋汁，淋在沙拉上拌匀即可。\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (126, '2025-12-26 18:27:28.000', '2025-12-26 18:27:28.000', NULL, '番茄龙利鱼荞麦面', '', '午餐', '简单', 25, 420.00, 32.00, 45.00, 11.00, '[\"龙利鱼柳 150g\", \"荞麦面（干） 60g\", \"番茄 200g\", \"洋葱 50g\", \"蒜末 5g\", \"橄榄油 5g\", \"生抽 5ml\", \"盐 少许\", \"小葱 少许\"]', '[\"龙利鱼柳切块，用少许盐和黑胡椒腌制。番茄去皮切丁，洋葱切丝。\", \"荞麦面按包装说明煮熟，过凉水备用。\", \"锅中放橄榄油，爆香蒜末和洋葱丝。\", \"加入番茄丁翻炒出汁，加少量水煮成浓稠酱汁，用生抽和盐调味。\", \"将龙利鱼块放入番茄酱汁中，小火焖煮5分钟至鱼肉熟透。\", \"将煮好的荞麦面装盘，浇上番茄龙利鱼和酱汁，撒上葱花即可。\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (127, '2025-12-26 18:27:28.000', '2025-12-26 18:27:28.000', NULL, '黑椒牛肉糙米饭', '', '午餐', '简单', 30, 450.00, 33.00, 50.00, 12.00, '[\"瘦牛肉（牛里脊） 120g\", \"糙米（生重） 70g\", \"西兰花 150g\", \"彩椒 80g\", \"橄榄油 5g\", \"黑胡椒酱（低脂） 15g\", \"生抽 5ml\", \"蒜末 5g\"]', '[\"糙米提前浸泡1小时，用电饭煲煮熟。\", \"牛肉逆纹切片，用少许生抽和黑胡椒腌制。西兰花掰小朵，彩椒切条。\", \"西兰花和彩椒焯水断生，捞出沥干。\", \"热锅放橄榄油，爆香蒜末，下牛肉片快速滑炒至变色。\", \"加入黑胡椒酱和少量水，翻炒均匀使牛肉裹上酱汁。\", \"盘中盛入糙米饭，码上焯水的西兰花、彩椒和炒好的黑椒牛肉即可。\"]', '[\"减脂\"]', '[\"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (128, '2025-12-26 18:27:28.000', '2025-12-26 18:27:28.000', NULL, '鲜虾豆腐红薯煲', '', '午餐', '简单', 25, 380.00, 31.00, 42.00, 9.00, '[\"鲜虾仁 100g\", \"北豆腐 150g\", \"红薯 150g\", \"芦笋 100g\", \"姜片 3片\", \"盐 少许\", \"白胡椒粉 少许\", \"香油 3滴\"]', '[\"红薯去皮切滚刀块，上锅蒸10分钟至软熟。豆腐切块，芦笋切段。\", \"虾仁用少许盐和白胡椒粉抓匀。\", \"小锅中加入适量清水和姜片烧开，先放入豆腐块和芦笋段煮2分钟。\", \"加入蒸好的红薯块和虾仁，煮至虾仁变色熟透。\", \"加入少许盐调味，滴入几滴香油即可出锅。\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (129, '2025-12-26 18:27:28.000', '2025-12-26 18:27:28.000', NULL, '香煎三文鱼配藜麦时蔬', '', '午餐', '简单', 20, 480.00, 34.00, 46.00, 15.00, '[\"三文鱼排 120g\", \"藜麦（生重） 50g\", \"口蘑 100g\", \"菠菜 150g\", \"柠檬 1/4个\", \"橄榄油 5g\", \"盐 少许\", \"黑胡椒 少许\"]', '[\"藜麦淘洗干净，加水（藜麦:水=1:2）煮15分钟，关火焖5分钟。\", \"三文鱼排用厨房纸吸干水分，两面撒少许盐和黑胡椒。\", \"平底锅烧热，刷薄薄一层橄榄油，放入三文鱼，每面煎2-3分钟至表面金黄。\", \"口蘑切片，菠菜洗净。用煎鱼的余油翻炒口蘑至变软，再加入菠菜炒软，加盐调味。\", \"盘中盛入煮好的藜麦，放上炒好的时蔬和煎好的三文鱼，旁边放一角柠檬。\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (130, '2025-12-26 18:27:34.000', '2025-12-26 18:27:34.000', NULL, '鸡胸肉藜麦沙拉', '', '午餐', '简单', 25, 380.00, 35.00, 35.00, 8.00, '[\"鸡胸肉 150g\", \"三色藜麦 50g\", \"黄瓜 100g\", \"圣女果 100g\", \"生菜 50g\", \"柠檬汁 10ml\", \"橄榄油 5ml\"]', '[\"藜麦煮熟后放凉\", \"鸡胸肉煮熟或煎熟后切块\", \"蔬菜洗净切好\", \"所有食材混合，加入柠檬汁和橄榄油拌匀\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (131, '2025-12-26 18:27:34.000', '2025-12-26 18:27:34.000', NULL, '清蒸鱼配红薯', '', '午餐', '简单', 30, 420.00, 32.00, 45.00, 9.00, '[\"鲈鱼片 200g\", \"红薯 150g\", \"姜片 10g\", \"葱段 10g\", \"蒸鱼豉油 5ml\"]', '[\"红薯切块蒸熟\", \"鱼片加姜片清蒸10分钟\", \"撒上葱段，淋少许蒸鱼豉油\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (132, '2025-12-26 18:27:34.000', '2025-12-26 18:27:34.000', NULL, '豆腐荞麦面', '', '午餐', '简单', 20, 390.00, 28.00, 42.00, 7.00, '[\"荞麦面 80g\", \"嫩豆腐 150g\", \"香菇 50g\", \"菠菜 100g\", \"低钠酱油 10ml\"]', '[\"荞麦面煮熟过凉水\", \"香菇切片与菠菜焯水\", \"豆腐切块\", \"所有食材混合，加酱油调味\"]', '[\"减脂\"]', '[\"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (133, '2025-12-26 18:27:34.000', '2025-12-26 18:27:34.000', NULL, '虾仁玉米炒蛋', '', '午餐', '简单', 15, 410.00, 34.00, 38.00, 12.00, '[\"虾仁 150g\", \"玉米粒 100g\", \"鸡蛋 2个\", \"青椒 50g\", \"橄榄油 5ml\"]', '[\"鸡蛋打散炒熟备用\", \"虾仁焯水\", \"玉米粒和青椒丁炒熟\", \"所有食材混合轻炒\"]', '[\"减脂\"]', '[\"海鲜\", \"蛋类\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (134, '2025-12-26 18:27:34.000', '2025-12-26 18:27:34.000', NULL, '牛肉西兰花配糙米饭', '', '午餐', '简单', 25, 450.00, 36.00, 48.00, 11.00, '[\"瘦牛肉 150g\", \"西兰花 200g\", \"糙米饭 100g\", \"蒜末 10g\", \"蚝油 5ml\"]', '[\"糙米饭提前煮熟\", \"牛肉切片腌制后快炒\", \"西兰花焯水后与牛肉同炒\", \"加蒜末和蚝油调味\"]', '[\"减脂\"]', '[\"牛肉\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (135, '2025-12-26 18:27:35.000', '2025-12-26 18:27:35.000', NULL, '水煮蛋鸡胸肉荞麦面', '', '早餐', '简单', 15, 380.00, 35.00, 45.00, 6.00, '[\"荞麦面 60g\", \"鸡胸肉 100g\", \"黄瓜 100g\", \"水煮蛋 1个\"]', '[\"鸡胸肉煮熟或蒸熟后撕成丝。\", \"荞麦面煮熟后过凉水。\", \"黄瓜切丝。\", \"将所有食材混合，可淋少量低盐酱油调味。\"]', '[\"减脂\"]', '[\"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (136, '2025-12-26 18:27:35.000', '2025-12-26 18:27:35.000', NULL, '蒸红薯拌无糖酸奶', '', '早餐', '简单', 20, 350.00, 28.00, 50.00, 5.00, '[\"红薯 200g\", \"无糖酸奶 150g\", \"奇亚籽 10g\"]', '[\"红薯去皮切块，蒸熟。\", \"将蒸熟的红薯与无糖酸奶混合。\", \"撒上奇亚籽即可食用。\"]', '[\"减脂\"]', '[\"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (137, '2025-12-26 18:27:35.000', '2025-12-26 18:27:35.000', NULL, '玉米蔬菜蛋白烘蛋', '', '早餐', '简单', 15, 420.00, 32.00, 35.00, 12.00, '[\"玉米粒 100g\", \"鸡蛋 2个\", \"菠菜 50g\", \"圣女果 50g\"]', '[\"鸡蛋打散，加入玉米粒和切碎的菠菜拌匀。\", \"将蛋液倒入不粘锅，小火烘至定型。\", \"表面放上切半的圣女果，加盖焖2分钟即可。\"]', '[\"减脂\"]', '[\"蛋类\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (138, '2025-12-26 18:27:35.000', '2025-12-26 18:27:35.000', NULL, '鸡胸肉燕麦粥', '', '早餐', '简单', 20, 390.00, 33.00, 48.00, 8.00, '[\"燕麦片 40g\", \"鸡胸肉 80g\", \"香菇 50g\", \"青菜 100g\"]', '[\"鸡胸肉切小丁，香菇切片。\", \"锅中加水烧开，加入燕麦片和鸡胸肉丁煮10分钟。\", \"加入香菇和切碎的青菜再煮5分钟，加少许盐调味。\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (139, '2025-12-26 18:27:35.000', '2025-12-26 18:27:35.000', NULL, '凉拌魔芋丝鸡丝', '', '早餐', '简单', 15, 320.00, 30.00, 38.00, 7.00, '[\"魔芋丝 200g\", \"鸡胸肉 100g\", \"胡萝卜 50g\", \"黑木耳 30g\", \"低盐生抽 5ml\"]', '[\"魔芋丝焯水后沥干。\", \"鸡胸肉煮熟撕成丝，胡萝卜和泡发的黑木耳切丝焯水。\", \"所有食材混合，淋入低盐生抽拌匀。\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (140, '2025-12-26 18:27:38.000', '2025-12-26 18:27:38.000', NULL, '清蒸鸡胸配藜麦西兰花', '', '晚餐', '简单', 25, 380.00, 35.00, 35.00, 8.00, '[\"鸡胸肉 150g\", \"三色藜麦 40g\", \"西兰花 200g\", \"蒜末 5g\", \"生抽 5ml\", \"橄榄油 3ml\"]', '[\"藜麦淘洗干净，加水煮熟（约15分钟）。\", \"鸡胸肉切片，用生抽和蒜末腌制10分钟。\", \"西兰花洗净掰成小朵，与鸡胸肉一同上锅蒸10分钟。\", \"将蒸好的食材与煮熟的藜麦混合，淋上橄榄油即可。\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (141, '2025-12-26 18:27:38.000', '2025-12-26 18:27:38.000', NULL, '香煎龙利鱼佐红薯泥', '', '晚餐', '简单', 20, 420.00, 32.00, 45.00, 9.00, '[\"龙利鱼柳 180g\", \"红薯 200g\", \"芦笋 100g\", \"柠檬 1/4个\", \"黑胡椒 2g\", \"橄榄油 5ml\"]', '[\"红薯去皮切块，蒸熟后压成泥。\", \"龙利鱼柳用厨房纸吸干水分，撒上黑胡椒。\", \"平底锅刷少量橄榄油，中小火将鱼柳煎至两面金黄。\", \"芦笋焯水或清炒至熟，与红薯泥、煎鱼一同摆盘，挤上柠檬汁。\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (142, '2025-12-26 18:27:38.000', '2025-12-26 18:27:38.000', NULL, '菌菇豆腐荞麦面', '', '晚餐', '简单', 15, 390.00, 28.00, 42.00, 7.00, '[\"荞麦面 60g\", \"韧豆腐 150g\", \"鲜香菇 80g\", \"金针菇 50g\", \"小白菜 100g\", \"低钠酱油 10ml\", \"姜丝 3g\"]', '[\"荞麦面按包装说明煮熟，过凉水备用。\", \"豆腐切块，菌菇和小白菜洗净切好。\", \"锅中放水烧开，加入姜丝、菌菇和豆腐煮5分钟。\", \"放入小白菜和煮好的荞麦面，加低钠酱油调味，再煮2分钟即可。\"]', '[\"减脂\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (143, '2025-12-26 18:27:38.000', '2025-12-26 18:27:38.000', NULL, '彩椒鸡丁炒糙米饭', '', '晚餐', '简单', 20, 410.00, 31.00, 48.00, 8.50, '[\"熟糙米饭 150g\", \"鸡胸肉 120g\", \"青红黄彩椒 150g\", \"洋葱 50g\", \"生抽 8ml\", \"食用油 5ml\"]', '[\"鸡胸肉切丁，彩椒和洋葱切小块。\", \"锅中放少量油，先将鸡丁炒至变色盛出。\", \"用底油炒香洋葱和彩椒，加入糙米饭翻炒均匀。\", \"倒入鸡丁，淋入生抽，快速翻炒2分钟即可出锅。\"]', '[\"减脂\"]', '[]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (144, '2025-12-26 18:27:38.000', '2025-12-26 18:27:38.000', NULL, '蒜蓉蒸虾配玉米粒', '', '晚餐', '简单', 15, 395.00, 33.00, 38.00, 9.50, '[\"鲜虾仁 200g\", \"甜玉米粒 100g\", \"蒜蓉 10g\", \"葱花 5g\", \"蒸鱼豉油 5ml\", \"香油 2ml\"]', '[\"虾仁洗净，用厨房纸吸干水分。\", \"将虾仁和玉米粒混合，铺上蒜蓉。\", \"放入蒸锅，水开后蒸8分钟至虾仁变红熟透。\", \"取出后淋上蒸鱼豉油和香油，撒上葱花即可。\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (146, '2025-12-26 18:27:45.000', '2025-12-26 18:27:45.000', NULL, '香煎龙利鱼配红薯泥', '', '晚餐', '简单', 20, 350.00, 28.00, 38.00, 9.00, '[\"龙利鱼柳 150g\", \"红薯 200g\", \"芦笋 100g\", \"柠檬 1/4个\", \"黑胡椒 2g\", \"橄榄油 5ml\"]', '[\"红薯去皮切块，蒸熟（约15分钟）后压成泥。\", \"龙利鱼柳用厨房纸吸干水分，撒上黑胡椒。\", \"平底锅刷少量橄榄油，中小火将龙利鱼煎至两面金黄（约6-8分钟）。\", \"芦笋切段，用煎鱼的余油煎熟。\", \"将所有食材装盘，挤上柠檬汁即可。\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (148, '2025-12-26 18:27:45.000', '2025-12-26 18:27:45.000', NULL, '黑椒牛肉杂粮饭', '', '晚餐', '简单', 20, 420.00, 32.00, 50.00, 10.00, '[\"牛里脊肉 120g\", \"糙米 50g\", \"彩椒 100g\", \"洋葱 50g\", \"黑胡椒酱 10g（低脂）\", \"橄榄油 5ml\"]', '[\"糙米提前浸泡1小时后煮熟。\", \"牛里脊切条，彩椒、洋葱切丝。\", \"锅中放橄榄油，爆香洋葱后加入牛肉翻炒至变色。\", \"加入彩椒丝和黑胡椒酱，快速翻炒均匀。\", \"将炒好的牛肉彩椒铺在杂粮饭上即可。\"]', '[\"减脂\"]', '[\"牛肉\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (149, '2025-12-26 18:27:45.000', '2025-12-26 18:27:45.000', NULL, '鲜虾芦笋炒玉米笋', '', '晚餐', '简单', 15, 360.00, 30.00, 40.00, 8.00, '[\"鲜虾仁 150g\", \"玉米笋 100g\", \"芦笋 100g\", \"胡萝卜 50g\", \"蒜末 5g\", \"盐 2g\", \"食用油 5ml\"]', '[\"虾仁洗净，芦笋、玉米笋、胡萝卜切段。\", \"锅中烧水，将玉米笋和胡萝卜焯水1分钟后捞出。\", \"热锅少油，爆香蒜末，加入虾仁翻炒至变色。\", \"加入芦笋、玉米笋、胡萝卜，快速翻炒2-3分钟。\", \"最后加盐调味，炒匀即可出锅。\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (150, '2025-12-26 18:28:17.000', '2025-12-26 18:28:17.000', NULL, '鸡胸肉蔬菜卷', '', '加餐', '简单', 15, 280.00, 35.00, 20.00, 6.00, '[\"鸡胸肉 120g\", \"生菜 100g\", \"黄瓜 80g\", \"胡萝卜 50g\", \"全麦卷饼 1张\"]', '[\"鸡胸肉煮熟后撕成丝\", \"黄瓜、胡萝卜切丝\", \"全麦卷饼铺平，放上生菜、鸡丝、黄瓜丝、胡萝卜丝\", \"卷紧后切段即可\"]', '[\"减脂\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (151, '2025-12-26 18:28:17.000', '2025-12-26 18:28:17.000', NULL, '红薯蛋白奶昔', '', '加餐', '简单', 10, 320.00, 28.00, 45.00, 4.00, '[\"红薯 150g\", \"蛋白粉 30g\", \"温水 200ml\", \"肉桂粉 2g\"]', '[\"红薯蒸熟去皮\", \"将所有材料放入搅拌机\", \"搅拌均匀至顺滑状态\"]', '[\"减脂\"]', '[\"乳制品\", \"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (152, '2025-12-26 18:28:17.000', '2025-12-26 18:28:17.000', NULL, '藜麦鸡蛋白沙拉', '', '加餐', '简单', 20, 350.00, 32.00, 38.00, 8.00, '[\"藜麦 50g\", \"鸡蛋白 4个\", \"西兰花 100g\", \"圣女果 80g\", \"橄榄油 5g\"]', '[\"藜麦煮熟沥干\", \"鸡蛋白煮熟切块\", \"西兰花焯水\", \"所有材料混合，加入少量橄榄油拌匀\"]', '[\"减脂\"]', '[\"蛋类\"]', 10, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (153, '2025-12-26 18:28:17.000', '2025-12-26 18:28:17.000', NULL, '玉米金枪鱼沙拉', '', '加餐', '简单', 15, 380.00, 34.00, 42.00, 9.00, '[\"甜玉米 100g\", \"水浸金枪鱼 100g\", \"青豆 50g\", \"黄瓜 80g\", \"柠檬汁 10ml\"]', '[\"玉米和青豆煮熟\", \"金枪鱼沥干水分\", \"黄瓜切丁\", \"所有材料混合，加入柠檬汁拌匀\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (154, '2025-12-26 18:28:17.000', '2025-12-26 18:28:17.000', NULL, '荞麦鸡丝拌菜', '', '加餐', '简单', 20, 310.00, 29.00, 36.00, 7.00, '[\"荞麦面 60g\", \"鸡胸肉 100g\", \"豆芽 80g\", \"紫甘蓝 50g\", \"低盐酱油 5ml\"]', '[\"荞麦面煮熟过冷水\", \"鸡胸肉煮熟撕成丝\", \"豆芽焯水，紫甘蓝切丝\", \"所有材料混合，加入酱油拌匀\"]', '[\"减脂\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (155, '2025-12-26 18:28:20.000', '2025-12-26 18:28:20.000', NULL, '香烤鸡胸肉配蒸红薯', '', '加餐', '简单', 20, 380.00, 35.00, 45.00, 6.00, '[\"鸡胸肉 150g\", \"红薯 200g\", \"橄榄油 5g\", \"盐 适量\", \"黑胡椒 适量\"]', '[\"鸡胸肉用盐和黑胡椒腌制10分钟。\", \"红薯去皮切块，放入蒸锅蒸15分钟至软。\", \"平底锅加热，刷少量橄榄油，放入鸡胸肉煎至两面金黄熟透。\", \"将蒸好的红薯和煎好的鸡胸肉装盘即可。\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (156, '2025-12-26 18:28:20.000', '2025-12-26 18:28:20.000', NULL, '凉拌魔芋丝配黄瓜', '', '加餐', '简单', 15, 120.00, 2.00, 25.00, 1.00, '[\"魔芋丝 200g\", \"黄瓜 100g\", \"米醋 10ml\", \"生抽 5ml\", \"蒜末 5g\", \"香菜 少许\"]', '[\"魔芋丝用开水焯烫1分钟，捞出过凉水沥干。\", \"黄瓜洗净切丝。\", \"将魔芋丝和黄瓜丝放入碗中，加入米醋、生抽、蒜末拌匀。\", \"撒上香菜点缀即可。\"]', '[\"减脂\"]', '[\"辛辣\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (157, '2025-12-26 18:28:20.000', '2025-12-26 18:28:20.000', NULL, '荞麦面沙拉', '', '加餐', '简单', 15, 320.00, 18.00, 55.00, 5.00, '[\"荞麦面 60g\", \"鸡胸肉 100g\", \"菠菜 50g\", \"小番茄 50g\", \"柠檬汁 10ml\", \"橄榄油 5g\"]', '[\"荞麦面按包装说明煮熟，捞出过凉水沥干。\", \"鸡胸肉煮熟后撕成丝。\", \"菠菜焯水，小番茄对半切开。\", \"将所有食材放入碗中，加入柠檬汁和橄榄油拌匀即可。\"]', '[\"减脂\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (158, '2025-12-26 18:28:20.000', '2025-12-26 18:28:20.000', NULL, '蒸玉米配酸奶', '', '加餐', '简单', 15, 280.00, 12.00, 50.00, 4.00, '[\"玉米 1根（约200g）\", \"无糖酸奶 100g\"]', '[\"玉米洗净，放入蒸锅蒸15分钟。\", \"将蒸好的玉米取出，搭配无糖酸奶食用。\"]', '[\"减脂\"]', '[\"乳制品\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (159, '2025-12-26 18:28:20.000', '2025-12-26 18:28:20.000', NULL, '红薯燕麦蛋白饮', '', '加餐', '简单', 10, 250.00, 25.00, 30.00, 3.00, '[\"蒸熟红薯 100g\", \"燕麦片 20g\", \"乳清蛋白粉 1勺（约30g）\", \"水 200ml\"]', '[\"将蒸熟的红薯、燕麦片、乳清蛋白粉和水放入搅拌机中。\", \"高速搅拌至顺滑均匀。\", \"倒入杯中即可饮用。\"]', '[\"减脂\"]', '[\"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (161, '2025-12-26 18:28:26.000', '2025-12-26 18:28:26.000', NULL, '红薯蛋白酸奶杯', '', '加餐', '简单', 10, 320.00, 28.00, 35.00, 5.00, '[\"红薯 150g\", \"无糖酸奶 150g\", \"蛋白粉 30g\", \"蓝莓 50g\"]', '[\"红薯蒸熟压成泥\", \"蛋白粉与无糖酸奶混合均匀\", \"杯中依次放入红薯泥、蛋白酸奶\", \"顶部撒上蓝莓\"]', '[\"减脂\"]', '[\"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (163, '2025-12-26 18:28:26.000', '2025-12-26 18:28:26.000', NULL, '玉米虾仁蔬菜盅', '', '加餐', '简单', 15, 290.00, 33.00, 25.00, 7.00, '[\"玉米粒 100g\", \"虾仁 150g\", \"青豆 50g\", \"彩椒 80g\", \"豆腐 100g\"]', '[\"虾仁焯熟备用\", \"玉米粒、青豆、彩椒丁焯水\", \"豆腐压碎与所有食材混合\", \"装入碗中蒸5分钟\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (164, '2025-12-26 18:28:26.000', '2025-12-26 18:28:26.000', NULL, '荞麦鸡丝凉面', '', '加餐', '简单', 20, 380.00, 34.00, 42.00, 9.00, '[\"荞麦面 80g\", \"鸡胸肉 120g\", \"黄瓜 100g\", \"豆芽 80g\", \"低盐酱油 10g\"]', '[\"荞麦面煮熟过冷水\", \"鸡胸肉煮熟撕成丝\", \"黄瓜切丝，豆芽焯水\", \"所有食材混合，加入低盐酱油拌匀\"]', '[\"减脂\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (165, '2025-12-26 18:28:36.000', '2025-12-26 18:28:36.000', NULL, '鸡胸肉燕麦能量碗', '', '早餐', '简单', 20, 450.00, 38.00, 45.00, 12.00, '[\"鸡胸肉 150g\", \"鸡蛋 2个\", \"快熟燕麦片 60g\", \"牛油果 半个 (约70g)\", \"菠菜 50g\"]', '[\"鸡胸肉切小块，用少许盐和黑胡椒腌制5分钟。\", \"锅中喷少许橄榄油，将鸡胸肉煎熟。\", \"同时，用沸水冲泡燕麦片。\", \"用同一个锅煎两个荷包蛋或炒蛋。\", \"将燕麦、鸡胸肉、鸡蛋、切片的牛油果和洗净的菠菜依次放入碗中即可。\"]', '[\"增肌\"]', '[\"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (166, '2025-12-26 18:28:36.000', '2025-12-26 18:28:36.000', NULL, '香煎三文鱼全麦三明治', '', '早餐', '简单', 15, 480.00, 35.00, 42.00, 18.00, '[\"三文鱼排 120g\", \"全麦面包 2片\", \"鸡蛋 1个\", \"牛油果 半个 (约70g)\", \"生菜 2片\"]', '[\"三文鱼排用厨房纸吸干水分，撒上盐和黑胡椒。\", \"平底锅加热，放入三文鱼，每面煎2-3分钟至金黄熟透。\", \"用同一个锅煎一个鸡蛋。\", \"全麦面包稍微烘烤。\", \"在一片面包上依次铺上生菜、牛油果片、煎好的三文鱼和鸡蛋，盖上另一片面包，对角切开。\"]', '[\"增肌\"]', '[\"海鲜\", \"麸质\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (167, '2025-12-26 18:28:36.000', '2025-12-26 18:28:36.000', NULL, '牛肉末红薯蔬菜烘蛋', '', '早餐', '简单', 20, 420.00, 32.00, 38.00, 15.00, '[\"瘦牛肉末 100g\", \"鸡蛋 3个\", \"红薯 100g (切丁)\", \"菠菜 50g\", \"橄榄油 5g\"]', '[\"红薯丁用微波炉高火加热3分钟至变软。\", \"平底锅加热橄榄油，放入牛肉末炒散至变色。\", \"加入红薯丁和菠菜翻炒至菠菜变软。\", \"将鸡蛋打散，加少许盐，均匀淋入锅中。\", \"盖上锅盖，小火焖5-8分钟，直至蛋液完全凝固即可。\"]', '[\"增肌\"]', '[\"牛肉\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (168, '2025-12-26 18:28:36.000', '2025-12-26 18:28:36.000', NULL, '高蛋白希腊酸奶燕麦杯', '', '早餐', '简单', 5, 400.00, 36.00, 42.00, 10.00, '[\"无糖希腊酸奶 200g\", \"乳清蛋白粉 (香草味) 1勺 (约30g)\", \"快熟燕麦片 40g\", \"蓝莓 50g\", \"杏仁片 10g\"]', '[\"在一个大碗中，将希腊酸奶和乳清蛋白粉充分搅拌均匀。\", \"加入燕麦片和蓝莓，再次拌匀。\", \"装入杯中，撒上杏仁片。\", \"可立即食用，或密封冷藏隔夜，口感更佳。\"]', '[\"增肌\"]', '[\"乳制品\", \"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (169, '2025-12-26 18:28:36.000', '2025-12-26 18:28:36.000', NULL, '牛油果豆腐全麦卷饼', '', '早餐', '简单', 15, 430.00, 31.00, 44.00, 14.00, '[\"全麦卷饼 1张\", \"牛油果 半个 (约70g)\", \"老豆腐 150g\", \"奇亚籽 10g\", \"番茄 半个 (切片)\"]', '[\"老豆腐用厨房纸吸干水分，用手或叉子捏碎成末状。\", \"平底锅不加油，放入豆腐末，中小火翻炒至水分减少，颜色微黄，加少许盐和胡椒粉调味。\", \"牛油果用叉子压成泥。\", \"将全麦卷饼加热。\", \"在饼皮上均匀涂抹牛油果泥，铺上炒好的豆腐碎和番茄片，撒上奇亚籽，卷紧即可。\"]', '[\"增肌\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (170, '2025-12-26 18:28:50.000', '2025-12-26 18:28:50.000', NULL, '鸡胸肉燕麦粥', '', '早餐', '简单', 20, 450.00, 35.00, 45.00, 12.00, '[\"鸡胸肉 150g\", \"燕麦片 60g\", \"鸡蛋 2个\", \"菠菜 50g\", \"橄榄油 5g\"]', '[\"鸡胸肉切丁，用少许盐和黑胡椒腌制。\", \"锅中加水烧开，放入燕麦片煮5分钟。\", \"加入鸡胸肉丁，煮至熟透。\", \"打入鸡蛋搅散，形成蛋花。\", \"最后加入菠菜烫熟，淋入橄榄油即可。\"]', '[\"增肌\"]', '[\"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (171, '2025-12-26 18:28:50.000', '2025-12-26 18:28:50.000', NULL, '希腊酸奶坚果能量碗', '', '早餐', '简单', 5, 480.00, 32.00, 42.00, 20.00, '[\"希腊酸奶 200g\", \"混合坚果（杏仁、核桃）30g\", \"香蕉 1根\", \"燕麦片 30g\", \"蜂蜜 5g\"]', '[\"希腊酸奶倒入碗中。\", \"香蕉切片，与燕麦片、混合坚果一同铺在酸奶上。\", \"淋上蜂蜜即可食用。\"]', '[\"增肌\"]', '[\"坚果\", \"乳制品\", \"高糖\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (172, '2025-12-26 18:28:50.000', '2025-12-26 18:28:50.000', NULL, '三文鱼牛油果全麦三明治', '', '早餐', '简单', 15, 520.00, 33.00, 38.00, 25.00, '[\"烟熏三文鱼 100g\", \"全麦面包 2片\", \"牛油果 半个\", \"鸡蛋 1个\", \"低脂芝士 1片\"]', '[\"全麦面包片烤至微黄。\", \"牛油果切片，鸡蛋煎熟。\", \"在面包片上依次铺上低脂芝士、煎蛋、三文鱼和牛油果片。\", \"盖上另一片面包，对角切开。\"]', '[\"增肌\"]', '[\"海鲜\", \"乳制品\", \"蛋类\", \"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (173, '2025-12-26 18:28:50.000', '2025-12-26 18:28:50.000', NULL, '牛肉蔬菜烘蛋', '', '早餐', '简单', 20, 460.00, 38.00, 15.00, 28.00, '[\"牛肉末 120g\", \"鸡蛋 3个\", \"彩椒 50g\", \"洋葱 30g\", \"马苏里拉芝士 20g\", \"橄榄油 5g\"]', '[\"洋葱、彩椒切丁。\", \"锅中放橄榄油，炒香洋葱，加入牛肉末炒熟，再加入彩椒翻炒。\", \"鸡蛋打散，加盐和黑胡椒调味，倒入锅中。\", \"撒上芝士，盖上锅盖小火焖至蛋液凝固。\"]', '[\"增肌\"]', '[\"牛肉\", \"蛋类\", \"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (174, '2025-12-26 18:28:50.000', '2025-12-26 18:28:50.000', NULL, '奇亚籽花生酱奶昔', '', '早餐', '简单', 5, 430.00, 31.00, 35.00, 18.00, '[\"牛奶 250ml\", \"蛋白粉（香草味）30g\", \"香蕉 1根\", \"奇亚籽 15g\", \"花生酱 15g\"]', '[\"将所有食材放入搅拌机中。\", \"高速搅拌至顺滑即可倒入杯中饮用。\"]', '[\"增肌\"]', '[\"乳制品\", \"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (175, '2025-12-26 18:28:59.000', '2025-12-26 18:28:59.000', NULL, '鸡胸肉燕麦蛋饼卷', '', '早餐', '简单', 20, 420.00, 35.00, 38.00, 12.00, '[\"鸡胸肉 100g\", \"鸡蛋 2个\", \"快熟燕麦片 40g\", \"菠菜 50g\", \"橄榄油 5ml\"]', '[\"鸡胸肉切薄片，用少许盐和黑胡椒腌制。\", \"鸡蛋打散，加入燕麦片和切碎的菠菜拌匀。\", \"平底锅刷橄榄油，倒入蛋液摊成蛋饼，小火煎至凝固后盛出。\", \"用同一口锅将鸡胸肉煎熟。\", \"将煎好的鸡胸肉铺在蛋饼上，卷起切段即可。\"]', '[\"增肌\"]', '[\"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (178, '2025-12-26 18:28:59.000', '2025-12-26 18:28:59.000', NULL, '藜麦牛肉蔬菜炒蛋', '', '早餐', '中等', 25, 460.00, 38.00, 35.00, 16.00, '[\"瘦牛肉末 80g\", \"熟藜麦 100g\", \"鸡蛋 2个\", \"彩椒（红、黄） 50g\", \"洋葱 30g\", \"橄榄油 8ml\"]', '[\"彩椒、洋葱切丁。鸡蛋打散备用。\", \"锅中放少许橄榄油，将牛肉末炒至变色后盛出。\", \"用锅中余油炒香洋葱和彩椒丁。\", \"倒入熟藜麦和炒好的牛肉末，翻炒均匀。\", \"将食材拨到锅边，在空处倒入蛋液，快速炒散后与所有食材混合翻炒，调味即可。\"]', '[\"增肌\"]', '[\"蛋类\", \"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (179, '2025-12-26 18:28:59.000', '2025-12-26 18:28:59.000', NULL, '高蛋白奇亚籽布丁配浆果', '', '早餐', '非常简单', 5, 390.00, 31.00, 36.00, 14.00, '[\"牛奶/杏仁奶 250ml\", \"奇亚籽 30g\", \"蛋白粉（巧克力味） 1勺（约30g）\", \"蓝莓 50g\", \"亚麻籽粉 10g\"]', '[\"将牛奶、奇亚籽、蛋白粉和亚麻籽粉在一个密封罐或碗中充分搅拌均匀。\", \"放入冰箱冷藏过夜（至少4小时）。\", \"食用前取出，表面放上蓝莓即可。\"]', '[\"增肌\"]', '[\"乳制品\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (180, '2025-12-26 18:29:05.000', '2025-12-26 18:29:05.000', NULL, '清蒸鸡胸配藜麦沙拉', '', '晚餐', '简单', 20, 380.00, 35.00, 35.00, 8.00, '[\"鸡胸肉 150g\", \"三色藜麦 50g\", \"黄瓜 100g\", \"圣女果 100g\", \"柠檬汁 10ml\", \"橄榄油 5g\"]', '[\"藜麦煮熟后放凉。\", \"鸡胸肉用盐和黑胡椒腌制后清蒸10分钟，撕成丝。\", \"黄瓜、圣女果切块，与鸡丝、藜麦混合。\", \"淋入柠檬汁和橄榄油拌匀即可。\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (181, '2025-12-26 18:29:05.000', '2025-12-26 18:29:05.000', NULL, '蒜蓉西兰花炒虾仁配玉米', '', '晚餐', '简单', 15, 320.00, 28.00, 30.00, 9.00, '[\"鲜虾仁 120g\", \"西兰花 200g\", \"甜玉米粒 100g\", \"大蒜 10g\", \"植物油 5g\"]', '[\"西兰花焯水备用。\", \"大蒜切末。\", \"热锅少油爆香蒜末，加入虾仁炒至变色。\", \"加入西兰花和玉米粒翻炒，用盐和少量生抽调味。\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (183, '2025-12-26 18:29:05.000', '2025-12-26 18:29:05.000', NULL, '香煎龙利鱼配烤红薯', '', '晚餐', '简单', 25, 390.00, 30.00, 40.00, 10.00, '[\"龙利鱼柳 150g\", \"红薯 150g\", \"芦笋 100g\", \"柠檬 1/4个\", \"植物油 5g\"]', '[\"红薯切块，烤箱200度烤20分钟。\", \"龙利鱼用厨房纸吸干水分，用盐和黑胡椒腌制。\", \"平底锅少油，将龙利鱼两面煎熟。\", \"芦笋焯水或清炒，与烤红薯、煎鱼一同摆盘，搭配柠檬。\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (184, '2025-12-26 18:29:05.000', '2025-12-26 18:29:05.000', NULL, '凉拌鸡丝魔芋面', '', '晚餐', '简单', 15, 280.00, 25.00, 25.00, 7.00, '[\"魔芋面 200g\", \"鸡胸肉 100g\", \"胡萝卜 50g\", \"黄瓜 50g\", \"米醋 10ml\", \"生抽 5ml\", \"蒜末 5g\"]', '[\"鸡胸肉煮熟后放凉，撕成细丝。\", \"魔芋面用开水焯烫后沥干。\", \"胡萝卜、黄瓜切丝。\", \"将所有食材混合，加入米醋、生抽、蒜末拌匀即可。\"]', '[\"减脂\"]', '[]', 10, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (185, '2025-12-26 18:30:42.000', '2025-12-26 18:30:42.000', NULL, '香煎鸡胸肉配糙米饭', '', '午餐', '简单', 25, 450.00, 35.00, 45.00, 12.00, '[\"鸡胸肉 200g\", \"糙米 100g\", \"橄榄油 10g\", \"西兰花 150g\"]', '[\"糙米提前浸泡1小时，加水煮熟\", \"鸡胸肉切片，用盐和黑胡椒腌制10分钟\", \"平底锅加热橄榄油，煎熟鸡胸肉\", \"西兰花焯水后与鸡胸肉、糙米饭一起摆盘\"]', '[\"增肌\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (186, '2025-12-26 18:30:42.000', '2025-12-26 18:30:42.000', NULL, '三文鱼牛油果沙拉', '', '午餐', '简单', 20, 480.00, 32.00, 35.00, 18.00, '[\"三文鱼 150g\", \"牛油果 1个\", \"藜麦 80g\", \"混合蔬菜 100g\", \"橄榄油 5g\"]', '[\"藜麦煮熟备用\", \"三文鱼用盐和柠檬汁腌制后煎熟\", \"牛油果切块，与混合蔬菜、藜麦拌匀\", \"淋上橄榄油，摆上三文鱼\"]', '[\"增肌\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (187, '2025-12-26 18:30:42.000', '2025-12-26 18:30:42.000', NULL, '牛肉意面配杏仁', '', '午餐', '中等', 30, 520.00, 38.00, 50.00, 15.00, '[\"瘦牛肉 150g\", \"全麦意面 100g\", \"杏仁 20g\", \"番茄 200g\", \"洋葱 50g\"]', '[\"意面按包装说明煮熟\", \"牛肉切末，与洋葱、番茄一起炒制酱汁\", \"酱汁与意面拌匀，撒上杏仁碎\"]', '[\"增肌\"]', '[\"牛肉\", \"坚果\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (188, '2025-12-26 18:30:42.000', '2025-12-26 18:30:42.000', NULL, '豆腐虾仁炒饭', '', '午餐', '简单', 20, 420.00, 31.00, 42.00, 11.00, '[\"虾仁 100g\", \"老豆腐 150g\", \"糙米饭 150g\", \"鸡蛋 1个\", \"豌豆 50g\"]', '[\"豆腐切丁煎至金黄，虾仁焯水\", \"鸡蛋炒熟备用\", \"所有食材与糙米饭一起翻炒，加少量酱油调味\"]', '[\"增肌\"]', '[\"海鲜\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (189, '2025-12-26 18:30:42.000', '2025-12-26 18:30:42.000', NULL, '芝士火鸡胸三明治', '', '午餐', '简单', 15, 460.00, 33.00, 38.00, 16.00, '[\"火鸡胸肉 120g\", \"全麦面包 2片\", \"低脂芝士 1片\", \"牛油果 半个\", \"生菜 2片\"]', '[\"火鸡胸肉切片煎熟\", \"全麦面包烤至微黄\", \"依次铺生菜、火鸡肉、芝士片和牛油果\", \"对角切开即可\"]', '[\"增肌\"]', '[\"乳制品\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (190, '2025-12-26 18:30:48.000', '2025-12-26 18:30:48.000', NULL, '香煎鸡胸肉配糙米饭与西兰花', '', '午餐', '简单', 25, 650.00, 45.00, 55.00, 18.00, '[\"鸡胸肉 200g\", \"糙米（生重） 80g\", \"西兰花 150g\", \"牛油果 50g\", \"橄榄油 10ml\", \"盐 适量\", \"黑胡椒 适量\"]', '[\"糙米提前浸泡1小时后煮熟。\", \"鸡胸肉用盐和黑胡椒腌制10分钟。\", \"平底锅加热橄榄油，将鸡胸肉煎至两面金黄熟透。\", \"西兰花焯水或清炒至断生。\", \"牛油果切片。\", \"将煮好的糙米饭、鸡胸肉、西兰花和牛油果摆盘即可。\"]', '[\"增肌\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (191, '2025-12-26 18:30:48.000', '2025-12-26 18:30:48.000', NULL, '瘦牛肉炒彩椒配藜麦饭', '', '午餐', '简单', 30, 680.00, 42.00, 60.00, 22.00, '[\"瘦牛肉（里脊/黄瓜条） 180g\", \"三色彩椒（红、黄、绿） 共150g\", \"藜麦（生重） 60g\", \"洋葱 50g\", \"大蒜 2瓣\", \"生抽 10ml\", \"橄榄油 10ml\", \"盐 适量\"]', '[\"藜麦洗净，加水（1:1.5比例）煮熟。\", \"牛肉逆纹理切薄片，用少许生抽和盐腌制。\", \"彩椒、洋葱切丝，大蒜切片。\", \"热锅冷油，快速滑炒牛肉至变色后盛出。\", \"用锅中余油爆香蒜片和洋葱，加入彩椒丝翻炒。\", \"彩椒变软后，倒入牛肉快速翻炒均匀，用盐调味。\", \"搭配煮好的藜麦饭食用。\"]', '[\"增肌\"]', '[\"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (192, '2025-12-26 18:30:48.000', '2025-12-26 18:30:48.000', NULL, '烤三文鱼排配红薯泥与芦笋', '', '午餐', '简单', 30, 620.00, 38.00, 50.00, 25.00, '[\"三文鱼排 180g\", \"中等大小红薯 200g\", \"芦笋 100g\", \"柠檬 1/4个\", \"橄榄油 10ml\", \"盐 适量\", \"黑胡椒 适量\", \"莳萝（可选） 少许\"]', '[\"红薯去皮切块，蒸熟或煮熟后压成泥，可加少许盐调味。\", \"三文鱼排用厨房纸吸干水分，两面撒盐和黑胡椒，挤上柠檬汁。\", \"烤箱预热200°C，将三文鱼放入烤15-20分钟至熟。\", \"芦笋切去老根，用橄榄油、盐和黑胡椒拌匀，与三文鱼一同入烤箱最后5-8分钟烤熟。\", \"将红薯泥、烤三文鱼和芦笋摆盘，撒上莳萝装饰。\"]', '[\"增肌\"]', '[\"海鲜\"]', 10, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (193, '2025-12-26 18:30:48.000', '2025-12-26 18:30:48.000', NULL, '鹰嘴豆泥鸡胸肉卷饼', '', '午餐', '简单', 20, 600.00, 35.00, 55.00, 20.00, '[\"全麦卷饼 1张（约60g）\", \"鸡胸肉 150g\", \"即食鹰嘴豆 80g\", \"芝麻酱（Tahini） 15g\", \"柠檬汁 10ml\", \"大蒜 1瓣\", \"生菜 2片\", \"番茄 50g\", \"盐 适量\", \"橄榄油 5ml\"]', '[\"鸡胸肉切条，用盐和橄榄油腌制后煎熟或烤熟。\", \"制作鹰嘴豆泥：将鹰嘴豆、芝麻酱、柠檬汁、大蒜和少许盐放入料理机，加少量水打成顺滑泥状。\", \"全麦卷饼用平底锅或微波炉微微加热。\", \"在饼皮上均匀涂抹一层鹰嘴豆泥。\", \"铺上生菜叶、番茄片和煎好的鸡胸肉条。\", \"将饼卷紧，斜切成两半即可食用。\"]', '[\"增肌\"]', '[\"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (194, '2025-12-26 18:30:48.000', '2025-12-26 18:30:48.000', NULL, '虾仁炒蛋配荞麦面与凉拌菠菜', '', '午餐', '简单', 20, 580.00, 40.00, 48.00, 18.00, '[\"虾仁 150g\", \"鸡蛋 2个\", \"荞麦面（干重） 80g\", \"菠菜 100g\", \"生抽 10ml\", \"香油 5ml\", \"蒜末 5g\", \"盐 适量\", \"食用油 10ml\"]', '[\"荞麦面按包装说明煮熟，捞出过凉水备用。\", \"虾仁用少许盐和料酒（如可用）腌制。鸡蛋打散。\", \"热锅加油，先将虾仁炒至变色后盛出。\", \"同一锅中再加油，倒入蛋液炒散，然后加入虾仁混合翻炒，用盐调味。\", \"菠菜焯水后捞出，挤干水分，用蒜末、生抽和香油拌匀。\", \"将荞麦面、虾仁炒蛋和凉拌菠菜组合装盘。\"]', '[\"增肌\"]', '[\"海鲜\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (195, '2025-12-26 18:31:09.000', '2025-12-26 18:31:09.000', NULL, '香煎鸡胸肉配糙米饭与西兰花', '', '晚餐', '简单', 25, 480.00, 42.00, 45.00, 12.00, '[\"鸡胸肉 200g\", \"糙米 80g（生重）\", \"西兰花 200g\", \"橄榄油 5g\"]', '[\"糙米提前浸泡1小时后，按正常程序煮熟。\", \"鸡胸肉用盐和黑胡椒腌制10分钟。\", \"西兰花洗净切小朵，焯水2分钟捞出。\", \"平底锅刷橄榄油，中火将鸡胸肉煎至两面金黄熟透。\", \"将煮好的糙米饭、鸡胸肉和西兰花摆盘即可。\"]', '[\"增肌\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (196, '2025-12-26 18:31:09.000', '2025-12-26 18:31:09.000', NULL, '烤三文鱼佐红薯与芦笋', '', '晚餐', '简单', 30, 520.00, 35.00, 50.00, 20.00, '[\"三文鱼排 180g\", \"红薯 200g\", \"芦笋 150g\", \"橄榄油 5g\", \"柠檬 1/4个\"]', '[\"红薯去皮切块，蒸熟或烤熟。\", \"芦笋去老根，焯水1分钟后捞出。\", \"三文鱼排用盐和黑胡椒腌制，刷少许橄榄油，放入预热至200度的烤箱烤12-15分钟。\", \"将红薯、芦笋和三文鱼摆盘，食用前挤上柠檬汁。\"]', '[\"增肌\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (197, '2025-12-26 18:31:09.000', '2025-12-26 18:31:09.000', NULL, '牛肉炒彩椒藜麦饭', '', '晚餐', '中等', 30, 550.00, 38.00, 55.00, 18.00, '[\"瘦牛肉 150g\", \"藜麦 60g（生重）\", \"彩椒（红/黄/绿） 200g\", \"大蒜 2瓣\", \"生抽 10ml\", \"食用油 5g\"]', '[\"藜麦淘洗干净，加水煮熟。\", \"牛肉切丝，彩椒切丝，大蒜切片。\", \"热锅少油，爆香蒜片，下牛肉丝滑炒至变色。\", \"加入彩椒丝翻炒至断生，淋入生抽调味。\", \"将炒好的牛肉彩椒与煮熟的藜麦混合均匀即可。\"]', '[\"增肌\"]', '[\"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (198, '2025-12-26 18:31:09.000', '2025-12-26 18:31:09.000', NULL, '豆腐虾仁炒蛋配全麦面包', '', '晚餐', '简单', 20, 460.00, 36.00, 42.00, 15.00, '[\"虾仁 100g\", \"老豆腐 150g\", \"鸡蛋 2个\", \"全麦面包 2片\", \"小葱 适量\", \"食用油 5g\"]', '[\"全麦面包烤箱或平底锅加热至微脆。\", \"豆腐切小块，鸡蛋打散，虾仁洗净。\", \"热锅少油，先下虾仁炒至变色，再加入豆腐轻轻翻炒。\", \"倒入蛋液，快速划炒至凝固，撒入葱花。\", \"将炒好的豆腐虾仁蛋搭配全麦面包食用。\"]', '[\"增肌\"]', '[\"海鲜\", \"蛋类\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (199, '2025-12-26 18:31:09.000', '2025-12-26 18:31:09.000', NULL, '鹰嘴豆蔬菜炖鸡腿', '', '晚餐', '中等', 40, 500.00, 33.00, 48.00, 16.00, '[\"鸡腿 1个（约150g）\", \"熟鹰嘴豆 150g\", \"番茄 1个\", \"洋葱 半个\", \"胡萝卜 半根\", \"橄榄油 5g\"]', '[\"鸡腿去皮，用盐和黑胡椒腌制。\", \"番茄、洋葱、胡萝卜切块。\", \"锅中放油，将鸡腿煎至表面微黄，盛出。\", \"用底油炒香洋葱，加入番茄、胡萝卜和鹰嘴豆翻炒。\", \"加入适量水，放入煎好的鸡腿，炖煮20分钟至鸡肉熟软，汤汁收浓即可。\"]', '[\"增肌\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (200, '2025-12-26 18:31:47.000', '2025-12-26 18:31:47.000', NULL, '香煎鸡胸肉配藜麦与西兰花', '', '晚餐', '简单', 20, 450.00, 38.00, 45.00, 12.00, '[\"鸡胸肉 150g\", \"三色藜麦（干） 50g\", \"西兰花 200g\", \"橄榄油 5g\", \"大蒜 2瓣\", \"盐 适量\", \"黑胡椒 适量\"]', '[\"藜麦淘洗干净，按1:2的比例加水煮熟，沥干备用。\", \"鸡胸肉用盐和黑胡椒腌制10分钟。\", \"西兰花洗净切小朵，大蒜切片。\", \"锅中放橄榄油，中火将鸡胸肉煎至两面金黄熟透，取出切片。\", \"用锅中余油爆香蒜片，加入西兰花翻炒，加少许水焖熟，用盐调味。\", \"将藜麦、西兰花和鸡胸肉摆盘即可。\"]', '[\"增肌\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (202, '2025-12-26 18:31:47.000', '2025-12-26 18:31:47.000', NULL, '牛肉杂蔬糙米饭', '', '晚餐', '简单', 30, 520.00, 36.00, 55.00, 15.00, '[\"瘦牛肉糜 150g\", \"糙米（干） 60g\", \"胡萝卜 50g\", \"青豆 50g\", \"玉米粒 50g\", \"洋葱 1/4个\", \"生抽 10ml\", \"蚝油 5g\", \"食用油 5g\"]', '[\"糙米提前浸泡1小时后煮熟备用。\", \"胡萝卜、洋葱切小丁。\", \"热锅下油，爆香洋葱丁，加入牛肉糜炒散至变色。\", \"加入胡萝卜丁、青豆、玉米粒翻炒均匀。\", \"加入生抽、蚝油调味，翻炒至蔬菜熟透。\", \"加入煮好的糙米饭，翻炒均匀即可出锅。\"]', '[\"增肌\"]', '[\"牛肉\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (203, '2025-12-26 18:31:47.000', '2025-12-26 18:31:47.000', NULL, '豆腐虾仁炒蛋配牛油果', '', '晚餐', '简单', 15, 430.00, 32.00, 20.00, 25.00, '[\"鸡蛋 2个\", \"鲜虾仁 100g\", \"嫩豆腐 150g\", \"牛油果 半个\", \"小葱 1根\", \"盐 适量\", \"食用油 5g\"]', '[\"鸡蛋打散，加少许盐。虾仁用厨房纸吸干水分。豆腐切块，牛油果切片，小葱切花。\", \"热锅少油，将虾仁煎至变色卷曲，盛出。\", \"锅中倒入蛋液，稍凝固时划散，加入豆腐块轻轻翻炒。\", \"放回虾仁，轻轻混合，用盐调味。\", \"出锅装盘，铺上牛油果片，撒上葱花即可。\"]', '[\"增肌\"]', '[\"海鲜\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (204, '2025-12-26 18:31:47.000', '2025-12-26 18:31:47.000', NULL, '土耳其风味烤鸡腿配鹰嘴豆泥', '', '晚餐', '简单', 35, 500.00, 40.00, 38.00, 20.00, '[\"去骨鸡腿肉 200g\", \"熟鹰嘴豆 150g\", \"芝麻酱（Tahini） 15g\", \"大蒜 2瓣\", \"柠檬汁 10ml\", \"橄榄油 10g\", \"盐 适量\", \"红椒粉 少许\", \"孜然粉 少许\"]', '[\"鸡腿肉用盐、红椒粉、孜然粉和部分橄榄油抹匀，腌制15分钟。\", \"将鸡腿肉放入预热200度的烤箱，烤20-25分钟至熟透。\", \"制作鹰嘴豆泥：将熟鹰嘴豆、芝麻酱、大蒜、柠檬汁、剩余橄榄油和少许盐放入料理机，搅打成顺滑泥状。\", \"将烤好的鸡腿肉切块，与鹰嘴豆泥一同装盘。\"]', '[\"增肌\"]', '[\"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (205, '2025-12-26 18:32:44.000', '2025-12-26 18:32:44.000', NULL, '希腊酸奶坚果能量杯', '', '加餐', '简单', 5, 420.00, 35.00, 35.00, 15.00, '[\"希腊酸奶 200g\", \"混合坚果（杏仁/核桃）30g\", \"燕麦片 30g\", \"蜂蜜 10g\"]', '[\"将希腊酸奶倒入碗中。\", \"加入燕麦片和混合坚果。\", \"淋上蜂蜜，搅拌均匀即可。\"]', '[\"增肌\"]', '[\"坚果\", \"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (206, '2025-12-26 18:32:44.000', '2025-12-26 18:32:44.000', NULL, '金枪鱼全麦三明治', '', '加餐', '简单', 10, 450.00, 38.00, 45.00, 12.00, '[\"水浸金枪鱼罐头 150g\", \"全麦面包 2片\", \"鸡蛋 1个\", \"牛油果 50g\"]', '[\"鸡蛋煮熟切片，牛油果捣成泥。\", \"将金枪鱼、牛油果泥铺在全麦面包上。\", \"放上鸡蛋片，盖上另一片面包，对角切开。\"]', '[\"增肌\"]', '[\"海鲜\", \"麸质\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (207, '2025-12-26 18:32:44.000', '2025-12-26 18:32:44.000', NULL, '鸡胸肉蔬菜卷', '', '加餐', '简单', 15, 380.00, 36.00, 32.00, 10.00, '[\"鸡胸肉 150g\", \"全麦卷饼 1张\", \"生菜 50g\", \"彩椒 30g\", \"低脂芝士片 1片\"]', '[\"鸡胸肉煮熟撕成丝，彩椒切条。\", \"全麦卷饼微微加热，铺上生菜、鸡丝、彩椒和芝士。\", \"卷紧后斜切两段。\"]', '[\"增肌\"]', '[\"麸质\", \"乳制品\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (208, '2025-12-26 18:32:44.000', '2025-12-26 18:32:44.000', NULL, '牛肉糙米饭团', '', '加餐', '中等', 20, 470.00, 40.00, 50.00, 12.00, '[\"瘦牛肉末 120g\", \"熟糙米饭 150g\", \"胡萝卜 30g\", \"芝麻 5g\", \"生抽 5ml\"]', '[\"牛肉末炒熟，胡萝卜切碎焯水。\", \"将糙米饭、牛肉末、胡萝卜碎混合，加入生抽调味。\", \"捏成饭团，撒上芝麻。\"]', '[\"增肌\"]', '[\"牛肉\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (209, '2025-12-26 18:32:44.000', '2025-12-26 18:32:44.000', NULL, '蛋白粉燕麦香蕉饮', '', '加餐', '简单', 3, 390.00, 32.00, 42.00, 8.00, '[\"乳清蛋白粉 30g\", \"快熟燕麦 40g\", \"香蕉 1根\", \"杏仁奶 200ml\"]', '[\"香蕉去皮切块，与燕麦、蛋白粉、杏仁奶一同放入搅拌机。\", \"高速搅拌至顺滑。\", \"倒入杯中即可饮用。\"]', '[\"增肌\"]', '[\"乳制品\", \"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (213, '2025-12-26 18:33:45.000', '2025-12-26 18:33:45.000', NULL, '牛肉蔬菜炒藜麦', '', '加餐', '简单', 20, 450.00, 38.00, 45.00, 13.00, '[\"瘦牛肉糜 120g\", \"三色藜麦 50g（干重）\", \"西兰花 100g\", \"胡萝卜 50g\", \"橄榄油 5g\"]', '[\"藜麦煮熟备用\", \"西兰花、胡萝卜切小块焯水\", \"锅中放橄榄油，将牛肉糜炒散至变色\", \"加入焯好的蔬菜翻炒\", \"倒入煮熟的藜麦，加少许盐和黑胡椒调味，翻炒均匀\"]', '[\"增肌\"]', '[\"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (214, '2025-12-26 18:33:45.000', '2025-12-26 18:33:45.000', NULL, '蛋白粉香蕉坚果奶昔', '', '加餐', '简单', 5, 410.00, 34.00, 42.00, 11.00, '[\"乳清蛋白粉 1勺（约30g）\", \"香蕉 1根\", \"杏仁奶 250ml\", \"杏仁 10g\", \"奇亚籽 5g\"]', '[\"香蕉去皮切块\", \"将所有材料放入料理机\", \"高速搅拌至顺滑\", \"倒入杯中即可饮用\"]', '[\"增肌\"]', '[\"乳制品\", \"坚果\", \"高糖\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (215, '2025-12-26 18:33:58.000', '2025-12-26 18:33:58.000', NULL, '杂粮蔬菜燕麦粥', '', '早餐', '简单', 15, 350.00, 18.00, 45.00, 8.00, '[\"纯燕麦片 50g\", \"水 300ml\", \"菠菜 100g\", \"豆腐 100g\", \"香菇 50g\", \"亚麻籽油 5g\"]', '[\"燕麦片与水一同放入锅中，煮沸后转小火煮10分钟。\", \"豆腐切小块，香菇切片，菠菜切段。\", \"将豆腐和香菇加入燕麦粥中，再煮5分钟。\", \"最后加入菠菜煮1分钟，淋入亚麻籽油即可。\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (216, '2025-12-26 18:33:58.000', '2025-12-26 18:33:58.000', NULL, '全麦蔬菜鸡蛋饼', '', '早餐', '简单', 20, 380.00, 25.00, 35.00, 12.00, '[\"全麦粉 40g\", \"鸡蛋 1个\", \"水 50ml\", \"西葫芦 100g\", \"胡萝卜 50g\", \"橄榄油 5g\"]', '[\"西葫芦和胡萝卜擦成细丝。\", \"全麦粉、鸡蛋和水混合成均匀面糊。\", \"将蔬菜丝加入面糊中拌匀。\", \"平底锅刷橄榄油，倒入面糊，小火煎至两面金黄熟透。\"]', '[\"控糖\"]', '[\"蛋类\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (217, '2025-12-26 18:33:58.000', '2025-12-26 18:33:58.000', NULL, '鹰嘴豆泥佐黄瓜条', '', '早餐', '简单', 10, 320.00, 15.00, 38.00, 10.00, '[\"熟鹰嘴豆 150g\", \"芝麻酱 10g\", \"柠檬汁 5g\", \"大蒜 1瓣\", \"黄瓜 200g\", \"全麦面包 1片\"]', '[\"熟鹰嘴豆、芝麻酱、柠檬汁和蒜瓣放入料理机搅打成顺滑泥状。\", \"黄瓜洗净切条。\", \"全麦面包烤至酥脆。\", \"用黄瓜条和全麦面包蘸取鹰嘴豆泥食用。\"]', '[\"控糖\"]', '[\"坚果\", \"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (218, '2025-12-26 18:33:58.000', '2025-12-26 18:33:58.000', NULL, '藜麦鸡胸蔬菜沙拉', '', '早餐', '简单', 25, 390.00, 35.00, 36.00, 9.00, '[\"熟藜麦 100g\", \"鸡胸肉 80g\", \"圣女果 100g\", \"生菜 100g\", \"紫甘蓝 50g\", \"油醋汁（橄榄油5g+黑醋10g）\"]', '[\"鸡胸肉煮熟或蒸熟后撕成丝。\", \"生菜、紫甘蓝洗净切丝，圣女果对半切开。\", \"将所有食材放入大碗中。\", \"淋上油醋汁拌匀即可。\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (219, '2025-12-26 18:33:58.000', '2025-12-26 18:33:58.000', NULL, '菌菇豆腐荞麦面', '', '早餐', '简单', 20, 370.00, 22.00, 42.00, 8.00, '[\"荞麦面 60g\", \"北豆腐 100g\", \"金针菇 50g\", \"白玉菇 50g\", \"小白菜 100g\", \"低钠酱油 5g\", \"姜丝 少许\"]', '[\"荞麦面煮熟后过凉水备用。\", \"豆腐切块，菌菇和小白菜洗净。\", \"锅中加水煮沸，放入姜丝、豆腐和菌菇煮5分钟。\", \"加入小白菜和煮好的荞麦面，再煮2分钟，最后用低钠酱油调味。\"]', '[\"控糖\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (220, '2025-12-26 18:34:16.000', '2025-12-26 18:34:16.000', NULL, '藜麦鸡胸沙拉', '', '午餐', '简单', 20, 400.00, 35.00, 35.00, 12.00, '[\"藜麦（干） 50g\", \"鸡胸肉 120g\", \"混合绿叶蔬菜（菠菜/生菜） 150g\", \"小番茄 100g\", \"橄榄油 5g\", \"柠檬汁 10g\", \"盐 2g\"]', '[\"藜麦淘洗干净，加水煮熟（约15分钟），沥干放凉。\", \"鸡胸肉切块，用少量盐腌制后煮熟或煎熟。\", \"绿叶蔬菜洗净沥干，小番茄对半切开。\", \"将所有食材放入大碗中，用橄榄油和柠檬汁拌匀即可。\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (221, '2025-12-26 18:34:16.000', '2025-12-26 18:34:16.000', NULL, '豆腐杂粮饭', '', '午餐', '简单', 25, 390.00, 28.00, 38.00, 11.00, '[\"杂粮米（黑米/糙米/燕麦米） 60g\", \"老豆腐 150g\", \"西兰花 150g\", \"胡萝卜 50g\", \"香菇 3朵\", \"低钠酱油 5g\", \"亚麻籽油 3g\"]', '[\"杂粮米提前浸泡1小时后煮熟。\", \"豆腐切块，与切好的西兰花、胡萝卜片、香菇一同蒸熟或快炒。\", \"用低钠酱油和亚麻籽油调汁，淋在饭菜上混合均匀。\"]', '[\"控糖\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (222, '2025-12-26 18:34:16.000', '2025-12-26 18:34:16.000', NULL, '鹰嘴豆蔬菜卷', '', '午餐', '简单', 15, 380.00, 26.00, 42.00, 9.00, '[\"全麦卷饼 1张（30g）\", \"熟鹰嘴豆 100g\", \"黄瓜 100g\", \"紫甘蓝 80g\", \"希腊酸奶（无糖） 30g\", \"莳萝碎 2g\"]', '[\"鹰嘴豆压碎，黄瓜切条，紫甘蓝切丝。\", \"全麦卷饼微微加热，铺上蔬菜和鹰嘴豆泥。\", \"用无糖希腊酸奶和莳萝碎调味，卷紧切段即可。\"]', '[\"控糖\"]', '[\"麸质\", \"乳制品\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (223, '2025-12-26 18:34:16.000', '2025-12-26 18:34:16.000', NULL, '虾仁炒魔芋面', '', '午餐', '简单', 15, 350.00, 32.00, 25.00, 8.00, '[\"魔芋面 200g\", \"鲜虾仁 100g\", \"绿豆芽 100g\", \"韭菜 50g\", \"姜末 5g\", \"椰子油 5g\", \"鱼露（无糖） 3g\"]', '[\"魔芋面焯水去碱味，沥干备用。\", \"虾仁用姜末炒熟，加入豆芽、韭菜快炒。\", \"放入魔芋面，用鱼露调味，翻炒均匀即可。\"]', '[\"控糖\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (224, '2025-12-26 18:34:16.000', '2025-12-26 18:34:16.000', NULL, '扁豆汤配全麦面包', '', '午餐', '简单', 30, 420.00, 24.00, 45.00, 10.00, '[\"红扁豆（干） 50g\", \"芹菜 50g\", \"洋葱 50g\", \"番茄 100g\", \"羽衣甘蓝 100g\", \"全麦面包（切片） 30g\", \"橄榄油 5g\"]', '[\"扁豆洗净，与切块的蔬菜一同加水煮至软烂（约25分钟）。\", \"羽衣甘蓝切碎，最后放入汤中烫熟。\", \"用橄榄油调味，搭配烤全麦面包食用。\"]', '[\"控糖\"]', '[\"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (225, '2025-12-26 18:35:15.000', '2025-12-26 18:35:15.000', NULL, '全麦蔬菜鸡蛋卷', '', '早餐', '简单', 15, 350.00, 25.00, 30.00, 12.00, '[\"全麦粉 50g\", \"鸡蛋 1个\", \"菠菜 100g\", \"口蘑 50g\", \"橄榄油 5ml\"]', '[\"全麦粉加水和鸡蛋调成糊状。\", \"菠菜、口蘑切碎，用橄榄油炒熟。\", \"平底锅刷薄油，倒入面糊摊成薄饼。\", \"将炒好的蔬菜铺在饼上，卷起切段即可。\"]', '[\"控糖\"]', '[\"麸质\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (226, '2025-12-26 18:35:15.000', '2025-12-26 18:35:15.000', NULL, '藜麦鸡胸肉蔬菜沙拉', '', '早餐', '简单', 20, 380.00, 32.00, 35.00, 10.00, '[\"藜麦（干） 40g\", \"鸡胸肉 80g\", \"生菜 100g\", \"小番茄 80g\", \"黄瓜 50g\", \"柠檬汁 10ml\", \"橄榄油 5ml\"]', '[\"藜麦煮熟，沥干水分放凉。\", \"鸡胸肉煮熟或蒸熟，撕成丝。\", \"生菜撕小片，小番茄、黄瓜切块。\", \"所有食材混合，淋上柠檬汁和橄榄油拌匀。\"]', '[\"控糖\"]', '[]', 10, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (227, '2025-12-26 18:35:15.000', '2025-12-26 18:35:15.000', NULL, '鹰嘴豆泥配全麦面包及蔬菜条', '', '早餐', '简单', 10, 320.00, 18.00, 42.00, 8.00, '[\"熟鹰嘴豆 150g\", \"大蒜 1瓣\", \"柠檬汁 15ml\", \"橄榄油 5ml\", \"全麦面包 1片\", \"西芹 50g\", \"胡萝卜 50g\"]', '[\"熟鹰嘴豆、大蒜、柠檬汁、橄榄油放入料理机打成泥。\", \"全麦面包烤脆。\", \"西芹、胡萝卜洗净切条。\", \"用面包或蔬菜条蘸取鹰嘴豆泥食用。\"]', '[\"控糖\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (228, '2025-12-26 18:35:15.000', '2025-12-26 18:35:15.000', NULL, '无糖豆浆燕麦粥配焯西兰花', '', '早餐', '简单', 15, 290.00, 20.00, 38.00, 6.00, '[\"无糖豆浆 250ml\", \"传统燕麦片 40g\", \"西兰花 150g\"]', '[\"无糖豆浆煮沸，加入燕麦片，小火煮5-8分钟至粘稠。\", \"西兰花掰成小朵，在沸水中焯烫2分钟捞出。\", \"将燕麦粥和焯好的西兰花一同装盘。\"]', '[\"控糖\"]', '[\"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (229, '2025-12-26 18:35:15.000', '2025-12-26 18:35:15.000', NULL, '豆腐蔬菜杂粮饭团', '', '早餐', '简单', 20, 360.00, 22.00, 45.00, 9.00, '[\"杂粮饭（糙米+小米） 100g\", \"北豆腐 80g\", \"香菇 2朵\", \"油菜 100g\", \"海苔 1小片\"]', '[\"杂粮饭提前煮熟。\", \"豆腐压碎，香菇、油菜切碎，炒熟。\", \"将炒好的蔬菜豆腐碎与杂粮饭混合拌匀。\", \"取适量饭团捏成三角或圆形，用海苔包裹底部。\"]', '[\"控糖\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (230, '2025-12-26 18:35:58.000', '2025-12-26 18:35:58.000', NULL, '藜麦鸡胸肉沙拉', '', '晚餐', '简单', 25, 380.00, 35.00, 35.00, 12.00, '[\"三色藜麦 60g\", \"鸡胸肉 120g\", \"生菜 100g\", \"黄瓜 100g\", \"小番茄 80g\", \"橄榄油 5ml\", \"柠檬汁 10ml\", \"黑胡椒 2g\", \"盐 2g\"]', '[\"藜麦淘洗干净，按1:2比例加水，煮15分钟至熟透，捞出放凉。\", \"鸡胸肉切薄片，用盐和黑胡椒腌制5分钟，用不粘锅无油或喷少量橄榄油煎熟。\", \"生菜洗净撕成片，黄瓜切片，小番茄对半切开。\", \"将所有食材放入大碗中，淋上橄榄油和柠檬汁，撒上剩余黑胡椒和盐，拌匀即可。\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (231, '2025-12-26 18:35:58.000', '2025-12-26 18:35:58.000', NULL, '全麦荞麦面拌时蔬豆腐', '', '晚餐', '简单', 20, 390.00, 28.00, 42.00, 11.00, '[\"全麦荞麦面 70g\", \"老豆腐 150g\", \"西兰花 150g\", \"香菇 50g\", \"胡萝卜 50g\", \"生抽 10ml\", \"香醋 5ml\", \"芝麻油 3ml\", \"蒜末 5g\"]', '[\"全麦荞麦面按包装说明煮熟，过凉水沥干备用。\", \"老豆腐切块，用不粘锅煎至两面微黄。\", \"西兰花、香菇、胡萝卜洗净切好，用沸水焯烫2-3分钟捞出沥干。\", \"将蒜末、生抽、香醋、芝麻油混合成调味汁。\", \"将所有食材放入碗中，淋上调味汁，拌匀即可食用。\"]', '[\"控糖\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (232, '2025-12-26 18:35:58.000', '2025-12-26 18:35:58.000', NULL, '鹰嘴豆泥佐烤蔬菜拼盘', '', '晚餐', '中等', 35, 410.00, 18.00, 45.00, 15.00, '[\"熟鹰嘴豆 150g\", \"茄子 150g\", \"彩椒 150g\", \"西葫芦 100g\", \"芝麻酱 15g\", \"大蒜 10g\", \"柠檬汁 15ml\", \"橄榄油 5ml\", \"孜然粉 2g\", \"盐 2g\"]', '[\"茄子、彩椒、西葫芦洗净切块，刷少量橄榄油，撒上孜然粉和盐，放入预热200度的烤箱烤20-25分钟。\", \"将熟鹰嘴豆、芝麻酱、大蒜、柠檬汁和少量水放入料理机，搅打成顺滑的泥状。\", \"将烤好的蔬菜摆盘，搭配鹰嘴豆泥一起食用。\"]', '[\"控糖\"]', '[\"坚果\"]', 10, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (233, '2025-12-26 18:35:58.000', '2025-12-26 18:35:58.000', NULL, '杂粮饭配清炒芥蓝虾仁', '', '晚餐', '简单', 30, 400.00, 32.00, 38.00, 12.00, '[\"杂粮米（糙米、黑米、燕麦米） 60g\", \"鲜虾仁 100g\", \"芥蓝 200g\", \"姜片 5g\", \"料酒 5ml\", \"盐 2g\", \"植物油 5ml\"]', '[\"杂粮米提前浸泡1小时，按常规米饭程序煮熟。\", \"虾仁用料酒和少许盐腌制10分钟。\", \"芥蓝洗净，将茎部斜切成段，叶子部分切大块。\", \"热锅冷油，下姜片爆香，先下虾仁炒至变色盛出。\", \"用锅中余油，先下芥蓝茎部翻炒1分钟，再下叶子部分翻炒至断生。\", \"将虾仁倒回锅中，加盐快速翻炒均匀，出锅与杂粮饭一同食用。\"]', '[\"控糖\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (234, '2025-12-26 18:35:58.000', '2025-12-26 18:35:58.000', NULL, '菌菇豆腐全麦卷饼', '', '晚餐', '简单', 20, 370.00, 25.00, 40.00, 10.00, '[\"全麦卷饼 1张（约60g）\", \"嫩豆腐 100g\", \"金针菇 50g\", \"杏鲍菇 50g\", \"菠菜 100g\", \"生抽 5ml\", \"蚝油（无糖） 5ml\", \"植物油 5ml\"]', '[\"嫩豆腐用厨房纸巾吸去多余水分，用手或叉子压碎。金针菇、杏鲍菇洗净切丝，菠菜洗净。\", \"热锅放油，先下菌菇丝炒软，出香味。\", \"加入豆腐碎和菠菜，翻炒至菠菜变软。\", \"加入生抽和无糖蚝油调味，翻炒均匀后盛出作为馅料。\", \"将全麦卷饼用平底锅小火两面各加热10秒使其变软。\", \"将炒好的馅料放在饼中央，卷起即可食用。\"]', '[\"控糖\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (235, '2025-12-26 18:36:47.000', '2025-12-26 18:36:47.000', NULL, '鹰嘴豆泥配黄瓜条', '', '加餐', '简单', 15, 180.00, 8.00, 20.00, 7.00, '[\"熟鹰嘴豆 150g\", \"黄瓜 200g\", \"大蒜 1瓣\", \"柠檬汁 10ml\", \"橄榄油 5ml\", \"盐 少许\"]', '[\"熟鹰嘴豆沥干水分，与大蒜、柠檬汁、橄榄油和少许盐一同放入料理机。\", \"搅打成细腻的泥状。\", \"黄瓜洗净切成条状。\", \"用黄瓜条蘸取鹰嘴豆泥食用。\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (236, '2025-12-26 18:36:47.000', '2025-12-26 18:36:47.000', NULL, '全麦蔬菜鸡肉卷', '', '加餐', '简单', 20, 280.00, 25.00, 30.00, 8.00, '[\"全麦卷饼 1张\", \"鸡胸肉 80g\", \"生菜 50g\", \"紫甘蓝 30g\", \"胡萝卜 30g\"]', '[\"鸡胸肉煮熟或煎熟后撕成丝。\", \"生菜、紫甘蓝、胡萝卜洗净切丝。\", \"将全麦卷饼微微加热变软。\", \"所有食材铺在卷饼上，卷紧实后切段即可。\"]', '[\"控糖\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (237, '2025-12-26 18:36:47.000', '2025-12-26 18:36:47.000', NULL, '凉拌魔芋结菠菜', '', '加餐', '简单', 10, 120.00, 5.00, 15.00, 4.00, '[\"魔芋结 150g\", \"菠菜 150g\", \"蒜末 5g\", \"生抽 5ml\", \"醋 5ml\", \"香油 3ml\"]', '[\"魔芋结用开水焯烫一下捞出沥干。\", \"菠菜洗净焯水后挤干水分切段。\", \"将魔芋结、菠菜、蒜末混合。\", \"加入生抽、醋、香油拌匀即可。\"]', '[\"控糖\"]', '[]', 10, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (238, '2025-12-26 18:36:47.000', '2025-12-26 18:36:47.000', NULL, '毛豆番茄蔬菜汤', '', '加餐', '简单', 15, 150.00, 10.00, 18.00, 5.00, '[\"毛豆仁 100g\", \"番茄 1个\", \"西兰花 50g\", \"清水 400ml\", \"盐 少许\", \"胡椒粉 少许\"]', '[\"番茄洗净去皮切块，西兰花洗净掰成小朵。\", \"锅中放水煮沸，加入毛豆仁煮5分钟。\", \"加入番茄块和西兰花再煮5分钟。\", \"用盐和胡椒粉调味即可。\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (239, '2025-12-26 18:36:47.000', '2025-12-26 18:36:47.000', NULL, '杂粮饭团配生菜', '', '加餐', '简单', 15, 200.00, 7.00, 35.00, 4.00, '[\"杂粮饭 100g\", \"生菜叶 4片\", \"胡萝卜丁 20g\", \"香菇丁 20g\"]', '[\"杂粮饭提前煮熟备用。\", \"胡萝卜丁、香菇丁焯熟后与杂粮饭混合。\", \"取适量饭捏成小饭团。\", \"用生菜叶包裹饭团食用。\"]', '[\"控糖\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (240, '2025-12-26 18:36:50.000', '2025-12-26 18:36:50.000', NULL, '杂粮饭配清炒时蔬与香煎鸡胸肉', '', '晚餐', '简单', 30, 420.00, 35.00, 45.00, 12.00, '[\"杂粮米（糙米/藜麦/黑米）80g\", \"鸡胸肉 150g\", \"西兰花 150g\", \"胡萝卜 50g\", \"橄榄油 5g\", \"大蒜 2瓣\", \"低钠酱油 10ml\"]', '[\"杂粮米提前浸泡1小时后，按正常煮饭程序煮熟。\", \"鸡胸肉切片，用少许低钠酱油和黑胡椒腌制10分钟。\", \"西兰花洗净切小朵，胡萝卜切片，大蒜切末。\", \"平底锅刷少量橄榄油，将鸡胸肉煎至两面金黄熟透，盛出。\", \"用锅中余油爆香蒜末，加入西兰花和胡萝卜翻炒，加少许水焖煮2分钟至熟。\", \"将杂粮饭、蔬菜和鸡胸肉装盘即可。\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (241, '2025-12-26 18:36:50.000', '2025-12-26 18:36:50.000', NULL, '茄汁鹰嘴豆炖菜', '', '晚餐', '简单', 25, 380.00, 18.00, 55.00, 8.00, '[\"熟鹰嘴豆 150g\", \"番茄 200g\", \"洋葱 50g\", \"彩椒 50g\", \"菠菜 100g\", \"橄榄油 5g\", \"番茄膏（无糖）15g\", \"大蒜 2瓣\"]', '[\"番茄去皮切块，洋葱、彩椒切丁，大蒜切末，菠菜洗净。\", \"锅中放橄榄油，炒香洋葱和蒜末至透明。\", \"加入番茄块和番茄膏，翻炒至番茄软烂出汁。\", \"加入熟鹰嘴豆和彩椒丁，倒入少量水，煮沸后转小火炖煮10分钟。\", \"放入菠菜，煮至软塌，加少许盐和黑胡椒调味即可。\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (242, '2025-12-26 18:36:50.000', '2025-12-26 18:36:50.000', NULL, '清蒸龙利鱼配芦笋与藜麦', '', '晚餐', '简单', 20, 390.00, 32.00, 42.00, 9.00, '[\"龙利鱼柳 200g\", \"三色藜麦 50g\", \"芦笋 150g\", \"生姜 3片\", \"葱丝 适量\", \"蒸鱼豉油（低钠）10ml\"]', '[\"藜麦淘洗干净，加水（藜麦:水=1:2）煮熟。\", \"龙利鱼柳解冻后用厨房纸吸干水分，姜片放在鱼上。\", \"芦笋切去老根，洗净。\", \"将鱼和芦笋放入蒸锅，水开后大火蒸8-10分钟至熟。\", \"倒掉盘中多余水分，拿掉姜片，淋上蒸鱼豉油，撒上葱丝。\", \"将蒸好的鱼和芦笋与煮熟的藜麦一同装盘。\"]', '[\"控糖\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (243, '2025-12-26 18:36:50.000', '2025-12-26 18:36:50.000', NULL, '菌菇豆腐汤饭', '', '晚餐', '简单', 20, 350.00, 25.00, 38.00, 10.00, '[\"杂粮饭 100g\", \"北豆腐 150g\", \"鲜香菇 50g\", \"金针菇 50g\", \"小白菜 100g\", \"香油 3g\", \"姜末 少许\"]', '[\"杂粮饭提前煮熟。豆腐切小块，香菇切片，金针菇去根，小白菜洗净切段。\", \"锅中放水烧开，加入姜末和豆腐块，煮5分钟。\", \"加入香菇片和金针菇，再煮5分钟。\", \"放入小白菜煮软，加少许盐和香油调味。\", \"将煮好的杂粮饭放入碗中，浇上菌菇豆腐汤即可。\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (244, '2025-12-26 18:36:50.000', '2025-12-26 18:36:50.000', NULL, '黑椒牛肉炒杂蔬（选用瘦肉）', '', '晚餐', '简单', 25, 410.00, 34.00, 43.00, 11.00, '[\"牛里脊肉 150g\", \"全麦意面 60g\", \"青椒 50g\", \"洋葱 50g\", \"口蘑 50g\", \"黑胡椒碎 适量\", \"橄榄油 5g\", \"低钠酱油 10ml\"]', '[\"全麦意面按包装说明煮熟，捞出沥干。\", \"牛里脊逆纹切薄片，用少许低钠酱油和黑胡椒碎腌制10分钟。\", \"青椒、洋葱切丝，口蘑切片。\", \"热锅少油，快速滑炒牛肉片至变色盛出。\", \"用锅中余油炒香洋葱，加入青椒和口蘑翻炒至软。\", \"加入煮熟的意面和牛肉片，调入适量黑胡椒碎和低钠酱油，快速翻炒均匀即可。\"]', '[\"控糖\"]', '[\"牛肉\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (245, '2025-12-26 18:37:18.000', '2025-12-26 18:37:18.000', NULL, '藜麦蔬菜沙拉', '', '加餐', '简单', 15, 180.00, 8.50, 25.00, 5.20, '[\"藜麦 50g\", \"生菜 100g\", \"黄瓜 100g\", \"圣女果 80g\", \"橄榄油 5g\", \"柠檬汁 10ml\"]', '[\"藜麦洗净后加水煮15分钟，沥干冷却\", \"生菜、黄瓜、圣女果洗净切块\", \"所有食材混合，加入橄榄油和柠檬汁拌匀\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (246, '2025-12-26 18:37:18.000', '2025-12-26 18:37:18.000', NULL, '全麦蔬菜卷', '', '加餐', '简单', 10, 160.00, 7.80, 22.00, 4.50, '[\"全麦饼皮 1张\", \"菠菜 80g\", \"胡萝卜 50g\", \"紫甘蓝 50g\", \"豆腐 60g\"]', '[\"菠菜焯水，胡萝卜、紫甘蓝切丝\", \"豆腐切条蒸熟\", \"所有食材放在全麦饼皮上卷起即可\"]', '[\"控糖\"]', '[\"麸质\"]', 9, 100.00);
