INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (249, '2025-12-26 18:37:18.000', '2025-12-26 18:37:18.000', NULL, '蔬菜豆类汤', '', '加餐', '简单', 20, 150.00, 8.00, 20.00, 4.00, '[\"绿豆 50g\", \"菠菜 100g\", \"西红柿 80g\", \"香菇 50g\"]', '[\"绿豆提前浸泡\", \"所有食材加水煮20分钟\", \"调味即可食用\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (250, '2025-12-26 18:37:48.000', '2025-12-26 18:37:48.000', NULL, '杂粮蔬菜豆腐沙拉', '', '加餐', '简单', 15, 180.00, 12.00, 15.00, 8.00, '[\"全麦面包丁 30g\", \"嫩豆腐 100g\", \"黄瓜 50g\", \"生菜 50g\", \"紫甘蓝 30g\", \"橄榄油 5g\", \"柠檬汁 5g\"]', '[\"全麦面包切丁，豆腐切块，蔬菜洗净切丝\", \"将所有食材混合拌匀\", \"加入橄榄油和柠檬汁调味\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (252, '2025-12-26 18:37:48.000', '2025-12-26 18:37:48.000', NULL, '藜麦蔬菜卷', '', '加餐', '中等', 25, 220.00, 10.00, 30.00, 6.00, '[\"熟藜麦 50g\", \"全麦卷饼 1张\", \"菠菜 30g\", \"彩椒 30g\", \"蘑菇 30g\", \"低钠酱油 3g\"]', '[\"蔬菜切丝炒熟，加入低钠酱油调味\", \"全麦卷饼铺平，放上藜麦和炒蔬菜\", \"卷紧切段即可食用\"]', '[\"控糖\"]', '[\"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (253, '2025-12-26 18:37:48.000', '2025-12-26 18:37:48.000', NULL, '蒸杂粮蔬菜丸子', '', '加餐', '中等', 30, 190.00, 9.00, 28.00, 5.00, '[\"燕麦片 30g\", \"绿豆面 20g\", \"西兰花 50g\", \"胡萝卜 30g\", \"香菇 20g\", \"亚麻籽粉 5g\"]', '[\"蔬菜切碎，与燕麦片、绿豆面混合\", \"加入适量水搅拌成团\", \"搓成丸子，上锅蒸15分钟\"]', '[\"控糖\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (254, '2025-12-26 18:37:48.000', '2025-12-26 18:37:48.000', NULL, '黑豆蔬菜汤', '', '加餐', '简单', 20, 170.00, 11.00, 22.00, 4.00, '[\"熟黑豆 50g\", \"番茄 50g\", \"洋葱 30g\", \"芹菜 30g\", \"菠菜 20g\", \"姜片 2g\"]', '[\"所有蔬菜切丁\", \"锅中加水煮沸，放入所有食材\", \"煮15分钟至蔬菜熟软即可\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (255, '2025-12-26 18:38:21.000', '2025-12-26 18:38:21.000', NULL, '燕麦杂蔬鸡蛋杯', '', '早餐', '简单', 15, 380.00, 24.00, 42.00, 12.00, '[\"燕麦片 40g\", \"鸡蛋 1个\", \"脱脂牛奶 100ml\", \"菠菜 30g\", \"口蘑 30g\", \"小番茄 50g\", \"亚麻籽油 3g\"]', '[\"口蘑切片、菠菜切段、小番茄对半切开备用。\", \"燕麦片与脱脂牛奶混合，微波炉高火加热2分钟。\", \"在燕麦上铺入口蘑、菠菜、小番茄，中间打入鸡蛋。\", \"覆盖保鲜膜，微波炉中高火再加热3分钟至鸡蛋凝固。\", \"取出后淋上亚麻籽油即可。\"]', '[\"维持健康\"]', '[\"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (256, '2025-12-26 18:38:21.000', '2025-12-26 18:38:21.000', NULL, '全麦鸡胸三明治', '', '早餐', '简单', 20, 410.00, 32.00, 45.00, 11.00, '[\"全麦面包 2片\", \"鸡胸肉 80g\", \"生菜 30g\", \"黄瓜 50g\", \"牛油果 30g\", \"柠檬汁 5g\"]', '[\"鸡胸肉切片，用少量盐和黑胡椒腌制后煎熟。\", \"黄瓜切片，牛油果压成泥并拌入柠檬汁。\", \"全麦面包片略微烘烤。\", \"在面包上依次铺生菜、黄瓜片、鸡胸肉和牛油果泥。\", \"盖上另一片面包，对角切开即可。\"]', '[\"维持健康\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (257, '2025-12-26 18:38:21.000', '2025-12-26 18:38:21.000', NULL, '藜麦水果坚果粥', '', '早餐', '简单', 15, 395.00, 18.00, 58.00, 10.00, '[\"熟藜麦 100g\", \"无糖豆浆 150ml\", \"蓝莓 30g\", \"草莓 30g\", \"奇亚籽 5g\", \"杏仁片 5g\"]', '[\"熟藜麦与无糖豆浆混合，小火加热5分钟。\", \"草莓切片备用。\", \"将加热好的藜麦粥盛入碗中。\", \"表面铺上蓝莓、草莓片、杏仁片和奇亚籽。\"]', '[\"维持健康\"]', '[\"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (258, '2025-12-26 18:38:21.000', '2025-12-26 18:38:21.000', NULL, '豆腐蔬菜蒸蛋', '', '早餐', '简单', 15, 350.00, 28.00, 25.00, 15.00, '[\"鸡蛋 1个\", \"内酯豆腐 100g\", \"胡萝卜 30g\", \"豌豆 20g\", \"玉米粒 20g\", \"芝麻油 2g\"]', '[\"豆腐压碎，胡萝卜切小丁。\", \"鸡蛋打散，加入等量清水搅拌均匀。\", \"将豆腐碎、胡萝卜丁、豌豆、玉米粒放入碗中，倒入蛋液。\", \"覆盖保鲜膜，水开后蒸10分钟。\", \"出锅后淋入芝麻油。\"]', '[\"维持健康\"]', '[\"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (259, '2025-12-26 18:38:21.000', '2025-12-26 18:38:21.000', NULL, '红薯小米鸡肉粥', '', '早餐', '简单', 25, 420.00, 26.00, 55.00, 12.00, '[\"小米 50g\", \"红薯 80g\", \"鸡胸肉 50g\", \"西兰花 30g\", \"白玉菇 20g\", \"橄榄油 3g\"]', '[\"小米提前浸泡30分钟。红薯切小块，鸡胸肉切丝，西兰花掰小朵。\", \"小米加适量水煮15分钟至开花。\", \"加入红薯块和鸡胸肉丝再煮5分钟。\", \"加入西兰花和白玉菇煮2分钟。\", \"最后淋入橄榄油拌匀。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (260, '2025-12-26 18:38:34.000', '2025-12-26 18:38:34.000', NULL, '全麦燕麦杂粮粥', '', '早餐', '简单', 20, 400.00, 30.00, 40.00, 10.00, '[\"全麦片 40g\", \"燕麦片 20g\", \"小米 15g\", \"红豆 15g\", \"薏米 10g\", \"核桃仁 10g\", \"黑芝麻 5g\", \"奇亚籽 5g\", \"枸杞 5g\", \"红枣 3颗\", \"亚麻籽油 3ml\", \"水 400ml\"]', '[\"将红豆、薏米提前浸泡2小时或隔夜。\", \"将全麦片、燕麦片、小米、泡好的红豆和薏米放入锅中，加水煮沸。\", \"转小火慢煮15分钟至粘稠。\", \"加入红枣（去核切块）、枸杞、核桃仁、黑芝麻、奇亚籽再煮2分钟。\", \"盛入碗中，淋入亚麻籽油即可。\"]', '[\"维持健康\"]', '[\"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (261, '2025-12-26 18:38:34.000', '2025-12-26 18:38:34.000', NULL, '蔬菜鸡蛋全麦卷饼', '', '早餐', '简单', 15, 400.00, 30.00, 40.00, 10.00, '[\"全麦面粉 50g\", \"鸡蛋 2个\", \"牛奶 30ml\", \"菠菜 50g\", \"胡萝卜 30g\", \"香菇 2朵\", \"紫甘蓝 20g\", \"橄榄油 3ml\", \"盐 1g\", \"黑胡椒 少许\"]', '[\"全麦面粉与牛奶、一个鸡蛋混合成均匀面糊。\", \"平底锅刷少量橄榄油，倒入面糊摊成薄饼，小火煎熟备用。\", \"另一个鸡蛋打散炒熟。菠菜、胡萝卜丝、香菇丝焯水后沥干。\", \"将炒蛋和蔬菜铺在饼皮上，撒少许盐和黑胡椒。\", \"卷起饼皮，切段即可食用。\"]', '[\"维持健康\"]', '[\"乳制品\", \"蛋类\", \"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (262, '2025-12-26 18:38:34.000', '2025-12-26 18:38:34.000', NULL, '藜麦鸡胸肉蔬菜沙拉', '', '早餐', '简单', 20, 400.00, 30.00, 40.00, 10.00, '[\"藜麦 40g\", \"鸡胸肉 80g\", \"黄瓜 50g\", \"圣女果 5颗\", \"生菜 30g\", \"玉米粒 30g\", \"牛油果 1/4个\", \"柠檬汁 5ml\", \"橄榄油 3ml\", \"生抽 3ml\", \"黑胡椒 少许\"]', '[\"藜麦淘洗干净，加水煮熟（约15分钟），沥干放凉。\", \"鸡胸肉煮熟或蒸熟，放凉后撕成丝。\", \"黄瓜切片，圣女果对半切，生菜撕小块，牛油果切块。\", \"将所有食材混合，加入橄榄油、柠檬汁、生抽和黑胡椒调味拌匀。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (263, '2025-12-26 18:38:34.000', '2025-12-26 18:38:34.000', NULL, '豆浆杂粮饭团配凉拌时蔬', '', '早餐', '简单', 15, 400.00, 30.00, 40.00, 10.00, '[\"杂粮饭（大米/黑米/糙米） 100g\", \"无糖豆浆 200ml\", \"毛豆仁 30g\", \"海苔 1片\", \"西芹 50g\", \"木耳 3朵\", \"豆干 30g\", \"香油 2ml\", \"盐 1g\"]', '[\"杂粮饭提前煮熟。毛豆仁煮熟。\", \"将杂粮饭与毛豆仁混合，取适量捏成饭团，可裹上一小片海苔。\", \"西芹、木耳、豆干切丝后焯水，沥干后用香油和盐拌匀。\", \"饭团搭配凉拌时蔬，并饮用温热的无糖豆浆。\"]', '[\"维持健康\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (264, '2025-12-26 18:38:34.000', '2025-12-26 18:38:34.000', NULL, '红薯小米粥配蒸时蔬与坚果', '', '早餐', '简单', 20, 400.00, 30.00, 40.00, 10.00, '[\"红薯 100g\", \"小米 30g\", \"山药 50g\", \"西兰花 50g\", \"杏仁 10g\", \"南瓜籽 5g\", \"葡萄干 5g\", \"水 400ml\"]', '[\"红薯、山药去皮切小块，与小米一同放入锅中，加水煮成粥。\", \"西兰花洗净掰成小朵，在粥快好时放入蒸格上蒸熟。\", \"将粥盛出，放上蒸好的西兰花。\", \"撒上杏仁、南瓜籽和葡萄干即可。\"]', '[\"维持健康\"]', '[\"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (265, '2025-12-26 18:38:50.000', '2025-12-26 18:38:50.000', NULL, '杂粮蔬菜鸡蛋饼', '', '早餐', '简单', 15, 380.00, 22.00, 35.00, 15.00, '[\"全麦粉 40g\", \"鸡蛋 1个\", \"菠菜 100g\", \"圣女果 50g\", \"橄榄油 5g\"]', '[\"菠菜焯水切碎，圣女果切丁。\", \"全麦粉与鸡蛋、少量水混合成面糊。\", \"加入菠菜碎和圣女果丁拌匀。\", \"平底锅刷橄榄油，倒入面糊煎至两面金黄。\"]', '[\"控糖\"]', '[\"麸质\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (268, '2025-12-26 18:38:50.000', '2025-12-26 18:38:50.000', NULL, '全麦燕麦蔬菜粥', '', '早餐', '简单', 20, 370.00, 15.00, 60.00, 8.00, '[\"全麦燕麦片 50g\", \"油菜 100g\", \"香菇 50g\", \"饮用水 300ml\"]', '[\"香菇切片，油菜切碎。\", \"锅中加水煮沸，加入燕麦片和香菇片煮10分钟。\", \"加入油菜碎再煮2分钟即可。\"]', '[\"控糖\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (269, '2025-12-26 18:38:50.000', '2025-12-26 18:38:50.000', NULL, '豆腐蔬菜烘蛋', '', '早餐', '简单', 20, 320.00, 25.00, 20.00, 16.00, '[\"北豆腐 150g\", \"鸡蛋 1个\", \"西兰花 100g\", \"胡萝卜 50g\", \"橄榄油 5g\"]', '[\"北豆腐压碎，西兰花和胡萝卜切碎焯水。\", \"鸡蛋打散，与豆腐碎、蔬菜碎混合均匀。\", \"模具刷油，倒入混合物，烤箱180度烤15分钟。\"]', '[\"控糖\"]', '[\"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (270, '2025-12-26 18:39:23.000', '2025-12-26 18:39:23.000', NULL, '杂粮鸡胸肉蔬菜沙拉', '', '午餐', '简单', 20, 410.00, 31.00, 42.00, 11.00, '[\"杂粮饭（大米30g，糙米30g，藜麦20g）\", \"鸡胸肉 120g\", \"圣女果 100g\", \"黄瓜 100g\", \"紫甘蓝 50g\", \"胡萝卜 30g\", \"生菜 50g\", \"橄榄油 5g\", \"柠檬汁 10g\", \"生抽 3g\", \"黑胡椒 1g\"]', '[\"鸡胸肉煮熟或煎熟后切丁。\", \"所有蔬菜洗净，圣女果对半切，黄瓜、胡萝卜切丁，紫甘蓝、生菜切丝。\", \"将杂粮饭与所有食材混合。\", \"用橄榄油、柠檬汁、生抽和黑胡椒调成油醋汁，淋在沙拉上拌匀即可。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (271, '2025-12-26 18:39:23.000', '2025-12-26 18:39:23.000', NULL, '番茄豆腐龙利鱼煲', '', '午餐', '简单', 25, 395.00, 32.00, 38.00, 12.00, '[\"龙利鱼 150g\", \"老豆腐 150g\", \"番茄 200g\", \"金针菇 50g\", \"白玉菇 50g\", \"洋葱 30g\", \"蒜 10g\", \"香菜 10g\", \"亚麻籽油 5g\", \"盐 2g\"]', '[\"龙利鱼、豆腐切块，番茄去皮切块，洋葱、蒜切末。\", \"锅中放少许油炒香洋葱和蒜末，加入番茄炒出汤汁。\", \"加入适量水烧开，放入豆腐块、金针菇、白玉菇煮5分钟。\", \"放入龙利鱼块，煮3-5分钟至鱼肉变白熟透。\", \"最后加盐调味，淋入亚麻籽油，撒上香菜即可。\"]', '[\"维持健康\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (272, '2025-12-26 18:39:23.000', '2025-12-26 18:39:23.000', NULL, '菌菇蒸鸡胸配糙米饭', '', '午餐', '简单', 30, 405.00, 33.00, 41.00, 10.00, '[\"鸡胸肉 150g\", \"香菇 50g\", \"蟹味菇 50g\", \"杏鲍菇 50g\", \"糙米 80g\", \"青豆 30g\", \"玉米粒 30g\", \"姜 10g\", \"葱 10g\", \"生抽 5g\", \"料酒 5g\", \"芝麻油 3g\"]', '[\"糙米提前浸泡1小时后煮熟。\", \"鸡胸肉切厚片，用生抽、料酒、姜片腌制10分钟。\", \"各种菌菇洗净切好，与青豆、玉米粒铺在盘底，上面放上腌好的鸡胸肉。\", \"放入蒸锅，水开后蒸15分钟左右至鸡肉熟透。\", \"出锅后淋少许芝麻油，撒上葱花即可搭配糙米饭食用。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (273, '2025-12-26 18:39:23.000', '2025-12-26 18:39:23.000', NULL, '鹰嘴豆时蔬炒饭', '', '午餐', '简单', 20, 400.00, 29.00, 43.00, 9.00, '[\"熟鹰嘴豆 100g\", \"杂粮饭（大米40g，小米40g）\", \"鸡蛋 1个\", \"西兰花 80g\", \"彩椒 50g\", \"玉米粒 30g\", \"毛豆 30g\", \"洋葱 20g\", \"山茶油 8g\", \"盐 2g\", \"黑胡椒 1g\"]', '[\"鸡蛋打散炒熟盛出。西兰花、彩椒、洋葱切丁。\", \"锅中放油，先炒香洋葱丁，再加入除鸡蛋外的所有蔬菜丁和鹰嘴豆翻炒。\", \"加入杂粮饭翻炒均匀。\", \"加入炒熟的鸡蛋，用盐和黑胡椒调味，翻炒均匀即可。\"]', '[\"维持健康\"]', '[\"蛋类\", \"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (274, '2025-12-26 18:39:23.000', '2025-12-26 18:39:23.000', NULL, '冬瓜虾仁荞麦面', '', '午餐', '简单', 20, 390.00, 28.00, 39.00, 11.00, '[\"荞麦面 80g\", \"鲜虾仁 100g\", \"冬瓜 150g\", \"干木耳 5g（泡发后约50g）\", \"小白菜 100g\", \"姜 10g\", \"葱 10g\", \"亚麻籽油 5g\", \"盐 2g\", \"白胡椒粉 1g\"]', '[\"荞麦面煮熟过凉水备用。冬瓜去皮切片，木耳泡发撕小朵，小白菜洗净。\", \"锅中放少许油，爆香姜丝，加入虾仁炒至变色。\", \"加入冬瓜片和木耳翻炒片刻，加入适量水煮开。\", \"煮至冬瓜变软，加入小白菜烫熟。\", \"用盐和白胡椒粉调味，将汤料浇在煮好的荞麦面上，淋亚麻籽油，撒上葱花即可。\"]', '[\"维持健康\"]', '[\"海鲜\", \"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (275, '2025-12-26 18:40:03.000', '2025-12-26 18:40:03.000', NULL, '藜麦鸡胸肉沙拉', '', '午餐', '简单', 20, 400.00, 30.00, 40.00, 10.00, '[\"藜麦 80g\", \"鸡胸肉 120g\", \"圣女果 100g\", \"黄瓜 100g\", \"生菜 50g\", \"紫甘蓝 50g\", \"橄榄油 5g\", \"柠檬汁 10g\", \"盐 1g\", \"黑胡椒 1g\"]', '[\"藜麦淘洗干净，加水煮熟，沥干放凉。\", \"鸡胸肉煮熟或蒸熟，放凉后撕成丝。\", \"圣女果、黄瓜、紫甘蓝切块，生菜撕成小片。\", \"将所有食材放入大碗中，加入橄榄油、柠檬汁、盐和黑胡椒，轻轻拌匀即可。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (276, '2025-12-26 18:40:03.000', '2025-12-26 18:40:03.000', NULL, '豆腐鲜蔬荞麦面', '', '午餐', '简单', 15, 390.00, 28.00, 42.00, 9.00, '[\"荞麦面 80g\", \"北豆腐 150g\", \"香菇 50g\", \"菠菜 100g\", \"胡萝卜 50g\", \"金针菇 50g\", \"生抽 5g\", \"芝麻油 3g\", \"姜末 5g\"]', '[\"荞麦面按包装说明煮熟，过凉水沥干。\", \"北豆腐切块，香菇、胡萝卜切片，菠菜、金针菇洗净。\", \"锅中放少量水，加入姜末、香菇、胡萝卜、金针菇煮熟。\", \"加入豆腐块和菠菜略煮，用生抽调味。\", \"将汤汁和蔬菜豆腐浇在荞麦面上，滴入芝麻油即可。\"]', '[\"维持健康\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (277, '2025-12-26 18:40:03.000', '2025-12-26 18:40:03.000', NULL, '鹰嘴豆蔬菜饭', '', '午餐', '简单', 25, 410.00, 29.00, 45.00, 11.00, '[\"糙米 80g\", \"鹰嘴豆（熟）100g\", \"西兰花 150g\", \"甜椒 50g\", \"玉米粒 50g\", \"洋葱 30g\", \"橄榄油 5g\", \"盐 1g\", \"罗勒碎 1g\"]', '[\"糙米和鹰嘴豆一同放入电饭煲，加适量水煮熟。\", \"西兰花掰成小朵，甜椒、洋葱切丁。\", \"锅中放橄榄油，炒香洋葱，加入甜椒、玉米粒、西兰花翻炒至熟。\", \"将炒好的蔬菜与煮好的糙米鹰嘴豆饭混合，加入盐和罗勒碎拌匀。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (278, '2025-12-26 18:40:03.000', '2025-12-26 18:40:03.000', NULL, '菌菇蒸鸡套餐', '', '午餐', '简单', 30, 395.00, 32.00, 38.00, 10.00, '[\"去骨鸡腿肉 150g\", \"白玉菇 50g\", \"蟹味菇 50g\", \"黑木耳（干）5g\", \"小米 70g\", \"芦笋 100g\", \"姜片 5g\", \"葱段 5g\", \"生抽 3g\", \"淀粉 5g\"]', '[\"小米淘洗干净，加水蒸熟成小米饭。\", \"鸡腿肉切块，用生抽、淀粉抓匀腌制。\", \"黑木耳泡发洗净，与白玉菇、蟹味菇、姜片、葱段铺在盘底，放上腌好的鸡块。\", \"放入蒸锅，上汽后蒸15分钟至鸡肉熟透。\", \"芦笋焯水断生，作为配菜。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (279, '2025-12-26 18:40:03.000', '2025-12-26 18:40:03.000', NULL, '番茄龙利鱼汤米粉', '', '午餐', '简单', 20, 405.00, 31.00, 41.00, 10.00, '[\"龙利鱼柳 150g\", \"米粉 80g\", \"番茄 200g\", \"小白菜 100g\", \"海鲜菇 50g\", \"蒜末 5g\", \"橄榄油 5g\", \"盐 1g\"]', '[\"米粉用温水泡软。龙利鱼柳切块，番茄去皮切块。\", \"锅中放橄榄油，炒香蒜末，加入番茄块炒出汤汁。\", \"加入适量水烧开，放入海鲜菇煮3分钟。\", \"放入龙利鱼块和泡软的米粉，煮至鱼肉变白熟透。\", \"最后加入小白菜烫熟，用盐调味即可。\"]', '[\"维持健康\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (280, '2025-12-26 18:40:57.000', '2025-12-26 18:40:57.000', NULL, '燕麦杂粮粥', '', '早餐', '简单', 20, 400.00, 30.00, 40.00, 10.00, '[\"燕麦片 40g\", \"藜麦 20g\", \"红豆 15g\", \"薏米 15g\", \"干香菇 2朵\", \"鸡胸肉 50g\", \"胡萝卜 30g\", \"菠菜 50g\", \"亚麻籽油 5g\", \"核桃仁 10g\", \"小葱 5g\", \"生姜 2片\"]', '[\"红豆、薏米提前浸泡4小时以上。\", \"干香菇泡发切丁，鸡胸肉、胡萝卜切丁，菠菜切段。\", \"将燕麦片、藜麦、红豆、薏米、香菇丁、鸡胸肉丁、胡萝卜丁、姜片一同放入锅中，加适量水煮沸后转小火煮15分钟。\", \"加入菠菜段再煮2分钟。\", \"关火后淋入亚麻籽油，撒上核桃仁和葱花即可。\"]', '[\"维持健康\"]', '[\"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (281, '2025-12-26 18:40:57.000', '2025-12-26 18:40:57.000', NULL, '全麦蔬菜鸡蛋饼', '', '早餐', '简单', 15, 400.00, 30.00, 40.00, 10.00, '[\"全麦面粉 50g\", \"鸡蛋 2个\", \"牛奶 50ml\", \"西葫芦 50g\", \"彩椒 30g\", \"口蘑 30g\", \"洋葱 20g\", \"橄榄油 5g\", \"黑芝麻 5g\", \"小番茄 5个\", \"生菜叶 3片\", \"新鲜罗勒叶 少许\"]', '[\"西葫芦、彩椒、口蘑、洋葱切碎。\", \"将全麦面粉、鸡蛋、牛奶混合搅拌均匀成面糊。\", \"将切好的蔬菜碎加入面糊中，搅拌均匀。\", \"平底锅刷少量橄榄油，倒入面糊，撒上黑芝麻，小火煎至两面金黄。\", \"搭配小番茄、生菜叶和罗勒叶一同食用。\"]', '[\"维持健康\"]', '[\"乳制品\", \"麸质\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (282, '2025-12-26 18:40:57.000', '2025-12-26 18:40:57.000', NULL, '藜麦鸡丝蔬菜沙拉', '', '早餐', '简单', 20, 400.00, 30.00, 40.00, 10.00, '[\"熟藜麦 100g\", \"鸡胸肉 80g\", \"黄瓜 50g\", \"紫甘蓝 30g\", \"樱桃萝卜 3个\", \"牛油果 半个\", \"毛豆仁 20g\", \"杏仁片 10g\", \"柠檬汁 10ml\", \"初榨橄榄油 8g\", \"蜂蜜 3g\", \"黑胡椒 少许\"]', '[\"鸡胸肉煮熟后撕成丝。\", \"黄瓜、紫甘蓝切丝，樱桃萝卜切片，牛油果切块。\", \"将熟藜麦、鸡丝、所有蔬菜、毛豆仁、牛油果混合。\", \"用柠檬汁、橄榄油、蜂蜜和黑胡椒调成油醋汁。\", \"将油醋汁淋在沙拉上，撒上杏仁片即可。\"]', '[\"维持健康\"]', '[\"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (283, '2025-12-26 18:40:57.000', '2025-12-26 18:40:57.000', NULL, '小米南瓜红枣羹', '', '早餐', '简单', 20, 400.00, 30.00, 40.00, 10.00, '[\"小米 50g\", \"南瓜 100g\", \"红枣 5颗\", \"山药 50g\", \"莲子 10g\", \"鹰嘴豆 20g\", \"枸杞 5g\", \"奇亚籽 5g\", \"亚麻籽粉 5g\", \"核桃油 5g\"]', '[\"南瓜、山药去皮切块，红枣去核，莲子、鹰嘴豆提前浸泡。\", \"将所有食材（除枸杞、奇亚籽、亚麻籽粉、核桃油外）放入锅中，加适量水煮成稠粥。\", \"出锅前加入枸杞再煮2分钟。\", \"盛入碗中，撒上奇亚籽、亚麻籽粉，淋入核桃油即可。\"]', '[\"维持健康\"]', '[\"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (284, '2025-12-26 18:40:57.000', '2025-12-26 18:40:57.000', NULL, '豆腐蔬菜荞麦面', '', '早餐', '简单', 15, 400.00, 30.00, 40.00, 10.00, '[\"荞麦面 80g\", \"北豆腐 100g\", \"豆芽 50g\", \"西兰花 50g\", \"玉米粒 30g\", \"海带 10g\", \"干木耳 5g\", \"白玉菇 30g\", \"生抽 5ml\", \"香油 3g\", \"白芝麻 3g\", \"香芹 少许\"]', '[\"干木耳、海带泡发，豆腐切块，西兰花掰小朵，白玉菇切段。\", \"荞麦面煮熟捞出过凉水备用。\", \"将豆腐、豆芽、西兰花、玉米粒、海带、木耳、白玉菇在沸水中焯熟。\", \"将面条和焯好的蔬菜放入碗中，加入生抽、香油拌匀。\", \"撒上白芝麻和香芹末即可。\"]', '[\"维持健康\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (285, '2025-12-26 18:41:01.000', '2025-12-26 18:41:01.000', NULL, '鸡胸肉藜麦沙拉', '', '午餐', '简单', 20, 420.00, 32.00, 42.00, 11.00, '[\"鸡胸肉 120g\", \"三色藜麦 60g\", \"紫甘蓝 50g\", \"樱桃番茄 80g\", \"黄瓜 50g\", \"生菜 30g\", \"橄榄油 5g\", \"柠檬汁 5g\", \"盐 1g\", \"黑胡椒 0.5g\"]', '[\"鸡胸肉用盐、黑胡椒腌制10分钟，用少量橄榄油煎熟后切块。\", \"藜麦按包装说明煮熟，放凉。\", \"紫甘蓝、黄瓜切丝，樱桃番茄对半切，生菜撕成小片。\", \"将所有处理好的食材放入大碗中混合。\", \"用橄榄油、柠檬汁、剩余盐和黑胡椒调成油醋汁，淋在沙拉上拌匀即可。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (286, '2025-12-26 18:41:01.000', '2025-12-26 18:41:01.000', NULL, '清蒸鲈鱼配杂粮饭与蒜蓉西兰花', '', '午餐', '简单', 25, 410.00, 31.00, 41.00, 10.00, '[\"鲈鱼片 150g\", \"糙米 40g\", \"小米 20g\", \"西兰花 150g\", \"大蒜 5g\", \"生姜 5g\", \"葱 5g\", \"蒸鱼豉油 10g\", \"植物油 5g\"]', '[\"糙米和小米混合，提前浸泡1小时后，按正常煮饭程序煮熟。\", \"鲈鱼片洗净，放上姜丝，水沸后上锅蒸8-10分钟至熟透。\", \"蒸好后倒掉盘中多余水分，放上葱丝，淋上蒸鱼豉油。\", \"将5g植物油烧热，淋在葱丝上激出香味。\", \"西兰花掰成小朵焯水2分钟捞出。大蒜切末，用少量油炒香，淋在西兰花上拌匀。\"]', '[\"维持健康\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (288, '2025-12-26 18:41:01.000', '2025-12-26 18:41:01.000', NULL, '彩椒鸡丁炒藜麦饭', '', '午餐', '简单', 20, 430.00, 30.00, 45.00, 12.00, '[\"鸡腿肉丁 120g\", \"熟藜麦饭 150g\", \"红黄彩椒 各50g\", \"洋葱 30g\", \"玉米粒 30g\", \"豌豆 20g\", \"大蒜 3g\", \"生抽 5g\", \"蚝油 5g\", \"植物油 8g\"]', '[\"鸡腿肉丁用少许生抽和蚝油腌制10分钟。彩椒、洋葱切丁。\", \"锅中放一半油，将鸡丁炒至变色后盛出备用。\", \"用剩余油爆香蒜末，下洋葱、彩椒、玉米粒、豌豆翻炒至断生。\", \"加入熟藜麦饭和炒好的鸡丁，快速翻炒均匀。\", \"淋入剩余生抽和蚝油调味，翻炒均匀即可出锅。\"]', '[\"维持健康\"]', '[]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (289, '2025-12-26 18:41:01.000', '2025-12-26 18:41:01.000', NULL, '菌菇虾仁荞麦面', '', '午餐', '简单', 15, 400.00, 29.00, 39.00, 8.00, '[\"荞麦面 80g\", \"鲜虾仁 100g\", \"香菇 50g\", \"白玉菇 30g\", \"菠菜 50g\", \"生姜 2g\", \"小葱 3g\", \"生抽 5g\", \"香油 3g\", \"盐 1g\"]', '[\"荞麦面按包装说明煮熟，捞出过凉水备用。\", \"虾仁洗净，用姜丝和少许盐腌制。香菇切片，白玉菇去根。\", \"锅中放少量油，将虾仁炒至变色后盛出。\", \"用锅中余油炒香菌菇，待变软后加入适量开水煮开。\", \"汤中放入煮好的荞麦面和菠菜，煮1分钟。\", \"放回虾仁，加生抽和盐调味，淋上香油，撒上葱花即可。\"]', '[\"维持健康\"]', '[\"海鲜\", \"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (290, '2025-12-26 18:41:09.000', '2025-12-26 18:41:09.000', NULL, '藜麦鸡胸肉沙拉', '', '晚餐', '简单', 20, 390.00, 31.00, 42.00, 9.50, '[\"藜麦 60g\", \"鸡胸肉 100g\", \"樱桃番茄 80g\", \"黄瓜 80g\", \"紫甘蓝 50g\", \"胡萝卜 30g\", \"生菜 50g\", \"牛油果 30g\", \"柠檬汁 10ml\", \"橄榄油 5ml\", \"盐 2g\", \"黑胡椒 1g\"]', '[\"藜麦淘洗干净，加水煮熟，沥干备用。\", \"鸡胸肉煮熟或煎熟，放凉后撕成丝。\", \"所有蔬菜洗净，樱桃番茄对半切，黄瓜、胡萝卜切丁，紫甘蓝、生菜切丝。\", \"将藜麦、鸡胸肉丝和所有蔬菜混合。\", \"加入柠檬汁、橄榄油、盐和黑胡椒调味，拌匀即可。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (291, '2025-12-26 18:41:09.000', '2025-12-26 18:41:09.000', NULL, '香菇豆腐蒸鱼片', '', '晚餐', '简单', 25, 410.00, 32.00, 41.00, 11.00, '[\"龙利鱼柳 120g\", \"嫩豆腐 150g\", \"鲜香菇 50g\", \"金针菇 30g\", \"毛豆仁 30g\", \"生姜 10g\", \"小葱 10g\", \"生抽 5ml\", \"香油 3ml\", \"糙米饭 150g\", \"西兰花 100g\", \"盐 1g\"]', '[\"龙利鱼柳切片，豆腐切块，香菇切片，生姜切丝，小葱切花。\", \"盘中铺上豆腐块、香菇片、金针菇和毛豆仁，上面放上鱼片和姜丝。\", \"放入蒸锅，水开后蒸8-10分钟至鱼肉熟透。\", \"取出后淋上生抽和香油，撒上葱花。\", \"搭配蒸好的糙米饭和焯水的西兰花食用。\"]', '[\"维持健康\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (292, '2025-12-26 18:41:09.000', '2025-12-26 18:41:09.000', NULL, '杂蔬牛肉糙米卷', '', '晚餐', '简单', 20, 405.00, 29.00, 43.00, 10.50, '[\"瘦牛肉糜 80g\", \"全麦卷饼 1张\", \"糙米 50g\", \"彩椒 50g\", \"洋葱 30g\", \"菠菜 50g\", \"玉米粒 30g\", \"蘑菇 40g\", \"低脂芝士片 1片\", \"番茄酱 5g\", \"橄榄油 5ml\", \"盐 1g\"]', '[\"糙米提前煮熟。彩椒、洋葱、蘑菇切碎。\", \"锅中放少量橄榄油，炒香洋葱，加入牛肉糜炒散，再加入彩椒、蘑菇、玉米粒炒熟，用盐调味。\", \"全麦卷饼微微加热。\", \"在卷饼上铺上煮好的糙米、炒好的牛肉杂蔬和菠菜叶，放上低脂芝士片，淋少许番茄酱。\", \"将卷饼卷紧，即可食用。\"]', '[\"维持健康\"]', '[\"牛肉\", \"乳制品\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (293, '2025-12-26 18:41:09.000', '2025-12-26 18:41:09.000', NULL, '番茄鸡蛋鹰嘴豆汤', '', '晚餐', '简单', 15, 395.00, 28.50, 39.00, 10.00, '[\"鸡蛋 1个\", \"番茄 150g\", \"鹰嘴豆 50g\", \"虾仁 50g\", \"小油菜 100g\", \"白玉菇 30g\", \"内酯豆腐 100g\", \"生姜 5g\", \"小葱 5g\", \"全麦面包 1片\", \"香油 3ml\", \"盐 2g\"]', '[\"番茄洗净切块，鹰嘴豆提前煮熟或使用罐头，小油菜洗净，白玉菇去根，豆腐切块，生姜切末。\", \"锅中放水烧开，加入姜末、番茄块、白玉菇和鹰嘴豆煮5分钟。\", \"加入虾仁和豆腐块煮2分钟。\", \"鸡蛋打散淋入锅中形成蛋花，再加入小油菜烫熟。\", \"最后加盐和香油调味，撒上葱花。搭配烤全麦面包食用。\"]', '[\"维持健康\"]', '[\"海鲜\", \"蛋类\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (294, '2025-12-26 18:41:09.000', '2025-12-26 18:41:09.000', NULL, '菌菇时蔬炒鸡丁', '', '晚餐', '简单', 20, 400.00, 30.50, 41.50, 9.00, '[\"鸡腿肉 100g\", \"杏鲍菇 50g\", \"蟹味菇 30g\", \"芦笋 50g\", \"甜豆 30g\", \"胡萝卜 30g\", \"玉米笋 30g\", \"大蒜 10g\", \"小米饭 150g\", \"生抽 5ml\", \"蚝油 5g\", \"植物油 5ml\"]', '[\"鸡腿肉切丁，杏鲍菇、胡萝卜切丁，芦笋切段，大蒜切片。\", \"鸡丁用少许生抽腌制。\", \"锅中放植物油，爆香蒜片，下鸡丁炒至变色。\", \"加入所有菌菇和蔬菜丁，翻炒均匀。\", \"加入蚝油和少量水，翻炒至熟。\", \"搭配小米饭一起食用。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (296, '2025-12-26 18:41:55.000', '2025-12-26 18:41:55.000', NULL, '鸡胸肉炒三色椒藜麦饭', '', '晚餐', '简单', 20, 390.00, 31.00, 42.00, 9.00, '[\"鸡胸肉 120g\", \"藜麦 40g\", \"青椒 50g\", \"红椒 50g\", \"黄椒 50g\", \"玉米粒 30g\", \"毛豆 30g\", \"大蒜 5g\", \"山茶油 5g\", \"盐 1g\"]', '[\"藜麦煮熟备用。鸡胸肉切丁，用少许盐腌制。\", \"三色椒洗净切丁，大蒜切片。\", \"热锅少油，爆香蒜片，下鸡丁炒至变色。\", \"加入三色椒丁、玉米粒、毛豆翻炒至断生。\", \"倒入煮熟的藜麦，加盐快速翻炒均匀即可出锅。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (297, '2025-12-26 18:41:55.000', '2025-12-26 18:41:55.000', NULL, '豆腐虾仁蔬菜汤面', '', '晚餐', '简单', 15, 380.00, 28.00, 38.00, 8.00, '[\"全麦面条 60g\", \"鲜虾仁 80g\", \"嫩豆腐 100g\", \"菠菜 80g\", \"白玉菇 50g\", \"海带 20g\", \"生姜 3g\", \"香油 3g\", \"盐 1g\"]', '[\"锅中烧水，水开后下全麦面条煮熟，捞出过凉。\", \"同一锅水，加入海带、姜片煮出鲜味，捞出海带姜片。\", \"放入白玉菇、豆腐块煮2分钟。\", \"加入虾仁、菠菜烫熟。\", \"最后将汤浇在面上，滴入香油，加盐调味即可。\"]', '[\"维持健康\"]', '[\"海鲜\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (298, '2025-12-26 18:41:55.000', '2025-12-26 18:41:55.000', NULL, '菌菇蒸鸡配紫薯', '', '晚餐', '简单', 30, 410.00, 33.00, 43.00, 11.00, '[\"去骨鸡腿肉 150g\", \"紫薯 150g\", \"金针菇 50g\", \"蟹味菇 50g\", \"黑木耳 10g\", \"红枣 3颗\", \"枸杞 5g\", \"生姜 5g\", \"料酒 5ml\", \"生抽 3ml\"]', '[\"紫薯切块，上锅蒸熟。鸡腿肉切块，用料酒、生抽、姜丝腌制。\", \"黑木耳泡发洗净，金针菇、蟹味菇去根洗净。\", \"将菌菇铺在盘底，上面码上腌好的鸡块，放上红枣、枸杞。\", \"放入蒸锅，上汽后蒸15-20分钟至鸡肉熟透。\", \"搭配蒸好的紫薯一同食用。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (299, '2025-12-26 18:41:55.000', '2025-12-26 18:41:55.000', NULL, '番茄牛肉末炖鹰嘴豆', '', '晚餐', '简单', 25, 400.00, 30.00, 41.00, 10.00, '[\"牛里脊肉末 100g\", \"熟鹰嘴豆 80g\", \"番茄 200g\", \"洋葱 50g\", \"芹菜 30g\", \"蒜末 5g\", \"橄榄油 5g\", \"番茄酱 10g\", \"盐 1g\", \"黑胡椒 1g\"]', '[\"番茄去皮切丁，洋葱、芹菜切碎。\", \"热锅少油，爆香蒜末和洋葱碎。\", \"加入牛肉末炒散至变色。\", \"放入番茄丁和番茄酱，炒出汤汁。\", \"加入熟鹰嘴豆和芹菜碎，加水小火炖煮10分钟。\", \"最后加盐和黑胡椒调味，收汁即可。\"]', '[\"维持健康\"]', '[\"牛肉\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (301, '2025-12-26 18:42:05.000', '2025-12-26 18:42:05.000', NULL, '鹰嘴豆泥配黄瓜条', '', '加餐', '简单', 15, 280.00, 15.00, 35.00, 8.00, '[\"熟鹰嘴豆 150g\", \"黄瓜 100g\", \"芝麻酱 10g\", \"柠檬汁 5ml\", \"大蒜 1瓣\", \"橄榄油 3ml\"]', '[\"熟鹰嘴豆沥干水分，与芝麻酱、柠檬汁、大蒜和橄榄油一同放入料理机。\", \"搅打至顺滑泥状，可根据喜好加入少量水调整稠度。\", \"黄瓜洗净切条。\", \"用黄瓜条蘸取鹰嘴豆泥食用。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (302, '2025-12-26 18:42:05.000', '2025-12-26 18:42:05.000', NULL, '全麦吐司配牛油果与鸡胸肉', '', '加餐', '简单', 10, 380.00, 28.00, 35.00, 14.00, '[\"全麦吐司 2片\", \"鸡胸肉（水煮） 50g\", \"牛油果 半个（约70g）\", \"圣女果 50g\", \"黑胡椒 少许\"]', '[\"全麦吐司放入面包机或烤箱轻微烘烤。\", \"鸡胸肉撕成细丝。\", \"牛油果切片，圣女果对半切开。\", \"将牛油果片和鸡胸肉丝铺在吐司上，撒上黑胡椒，搭配圣女果食用。\"]', '[\"维持健康\"]', '[\"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (303, '2025-12-26 18:42:05.000', '2025-12-26 18:42:05.000', NULL, '毛豆与水果拼盘', '', '加餐', '简单', 15, 320.00, 22.00, 38.00, 9.00, '[\"带壳毛豆 200g\", \"苹果 100g\", \"橙子 100g\"]', '[\"毛豆洗净，剪去两头，放入沸水中，加少许盐煮10分钟，捞出沥干。\", \"苹果和橙子洗净，苹果切块，橙子剥皮分瓣。\", \"将煮好的毛豆与水果拼盘即可。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (304, '2025-12-26 18:42:05.000', '2025-12-26 18:42:05.000', NULL, '紫薯杏仁奶昔', '', '加餐', '简单', 10, 360.00, 16.00, 55.00, 9.00, '[\"蒸熟紫薯 100g\", \"无糖杏仁奶 200ml\", \"香蕉 半根（约50g）\"]', '[\"紫薯提前蒸熟放凉。\", \"将紫薯、香蕉和杏仁奶一同放入料理机。\", \"高速搅打至顺滑奶昔状。\", \"倒入杯中即可饮用。\"]', '[\"维持健康\"]', '[\"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (305, '2025-12-26 18:42:31.000', '2025-12-26 18:42:31.000', NULL, '三色鸡丁炒藜麦饭', '', '晚餐', '简单', 25, 395.00, 31.00, 42.00, 9.50, '[\"鸡胸肉 120g\", \"三色藜麦 50g\", \"胡萝卜 50g\", \"黄瓜 50g\", \"玉米粒 30g\", \"香菇 2朵\", \"大蒜 2瓣\", \"橄榄油 5g\", \"低钠酱油 5ml\"]', '[\"藜麦洗净，加水（1：1.5）煮熟，备用。\", \"鸡胸肉、胡萝卜、黄瓜切丁，香菇切片，大蒜切末。\", \"锅中放橄榄油，爆香蒜末，下鸡丁炒至变色。\", \"加入胡萝卜、香菇、玉米粒翻炒2分钟。\", \"加入黄瓜丁和熟藜麦，淋入低钠酱油，快速翻炒均匀即可。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (306, '2025-12-26 18:42:31.000', '2025-12-26 18:42:31.000', NULL, '清蒸海鲈鱼配杂蔬', '', '晚餐', '简单', 20, 385.00, 32.00, 38.00, 11.00, '[\"海鲈鱼片 150g\", \"糙米饭 100g\", \"西兰花 100g\", \"金针菇 50g\", \"红甜椒 30g\", \"生姜 3片\", \"葱段 10g\", \"蒸鱼豉油 5ml\", \"芝麻油 2g\"]', '[\"鱼片洗净，姜片、葱段铺于鱼上。\", \"西兰花、金针菇、红甜椒切好，与鱼一同放入蒸盘。\", \"蒸锅水沸后，放入蒸盘，大火蒸8-10分钟。\", \"取出后淋上蒸鱼豉油和芝麻油。\", \"搭配蒸好的糙米饭食用。\"]', '[\"维持健康\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (307, '2025-12-26 18:42:31.000', '2025-12-26 18:42:31.000', NULL, '豆腐时蔬烩荞麦面', '', '晚餐', '简单', 20, 410.00, 28.00, 45.00, 12.00, '[\"荞麦面 80g\", \"老豆腐 150g\", \"小白菜 100g\", \"黑木耳 3朵\", \"蟹味菇 50g\", \"番茄 1个\", \"香菜 少许\", \"低盐 vegetable broth 200ml\"]', '[\"荞麦面煮熟，过冷水沥干。\", \"豆腐切块，番茄切块，黑木耳泡发切丝。\", \"锅中加入蔬菜高汤，煮沸后放入豆腐、番茄、黑木耳、蟹味菇煮5分钟。\", \"加入小白菜煮2分钟，调味。\", \"将汤汁和蔬菜浇在荞麦面上，撒上香菜即可。\"]', '[\"维持健康\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (308, '2025-12-26 18:42:31.000', '2025-12-26 18:42:31.000', NULL, '鹰嘴豆蔬菜烘蛋', '', '晚餐', '简单', 25, 400.00, 29.00, 39.00, 10.50, '[\"鸡蛋 2个\", \"熟鹰嘴豆 80g\", \"菠菜 50g\", \"口蘑 4个\", \"洋葱 30g\", \"小番茄 5个\", \"全麦面包 1片\", \"橄榄油 5g\"]', '[\"烤箱预热180°C。洋葱、口蘑切丁，菠菜切段，小番茄对半切。\", \"鸡蛋打散，加入鹰嘴豆、蔬菜和少许盐搅匀。\", \"烤碗刷橄榄油，倒入蛋液混合物。\", \"放入烤箱烘烤15分钟至凝固。\", \"搭配烤全麦面包片食用。\"]', '[\"维持健康\"]', '[\"蛋类\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (309, '2025-12-26 18:42:31.000', '2025-12-26 18:42:31.000', NULL, '菌菇炒牛肉粒配小米饭', '', '晚餐', '简单', 30, 405.00, 30.00, 41.00, 11.50, '[\"牛里脊 120g\", \"小米 50g\", \"杏鲍菇 50g\", \"海鲜菇 50g\", \"芦笋 4根\", \"蒜末 5g\", \"姜末 3g\", \"蚝油 5g\", \"花生油 5g\"]', '[\"小米煮熟成饭。牛里脊切粒，用少许蚝油腌制。\", \"杏鲍菇、海鲜菇、芦笋切段。\", \"热锅少油，爆香蒜姜末，下牛肉粒快速滑炒至变色盛出。\", \"用余油翻炒菌菇和芦笋至软。\", \"牛肉粒回锅，与菌菇芦笋翻炒均匀，搭配小米饭食用。\"]', '[\"维持健康\"]', '[\"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (311, '2025-12-26 18:42:53.000', '2025-12-26 18:42:53.000', NULL, '全麦鸡胸肉三明治', '', '加餐', '简单', 15, 380.00, 30.00, 45.00, 9.00, '[\"全麦面包 2片\", \"鸡胸肉 80g\", \"生菜 2片\", \"番茄 50g\", \"黄瓜 50g\", \"低脂奶酪 1片\"]', '[\"鸡胸肉煮熟或煎熟后切片。\", \"番茄、黄瓜洗净切片。\", \"在全麦面包上依次铺上生菜、番茄片、鸡胸肉、黄瓜片和低脂奶酪。\", \"盖上另一片面包，对角切开即可。\"]', '[\"维持健康\"]', '[\"麸质\", \"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (313, '2025-12-26 18:42:53.000', '2025-12-26 18:42:53.000', NULL, '红薯杏仁能量棒', '', '加餐', '中等', 40, 390.00, 12.00, 55.00, 14.00, '[\"红薯 200g\", \"即食燕麦片 50g\", \"杏仁 20g\", \"奇亚籽 10g\", \"椰枣 2颗\"]', '[\"红薯蒸熟，压成泥。\", \"杏仁、椰枣切碎。\", \"将红薯泥、燕麦片、杏仁碎、椰枣碎、奇亚籽混合均匀。\", \"放入铺好烘焙纸的模具中压实，烤箱180度烤20分钟。\", \"取出放凉后切块。\"]', '[\"维持健康\"]', '[\"坚果\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (314, '2025-12-26 18:42:53.000', '2025-12-26 18:42:53.000', NULL, '豆腐蔬菜沙拉', '', '加餐', '简单', 10, 280.00, 18.00, 25.00, 12.00, '[\"内酯豆腐 150g\", \"玉米粒 50g\", \"豌豆 50g\", \"彩椒 50g\", \"紫洋葱 20g\", \"香醋 5g\", \"亚麻籽油 3g\"]', '[\"内酯豆腐用开水烫一下，切块。\", \"玉米粒、豌豆焯熟，彩椒、紫洋葱切丁。\", \"将所有食材混合，淋入香醋和亚麻籽油拌匀即可。\"]', '[\"维持健康\"]', '[]', 10, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (317, '2025-12-26 18:42:54.000', '2025-12-26 18:42:54.000', NULL, '全麦鸡肉蔬菜卷', '', '加餐', '简单', 10, 320.00, 25.00, 30.00, 12.00, '[\"全麦卷饼 1张\", \"鸡胸肉 50g\", \"生菜 2片\", \"紫甘蓝 30g\", \"胡萝卜 30g\", \"低脂沙拉酱 5g\"]', '[\"鸡胸肉煮熟或煎熟后撕成丝。\", \"生菜、紫甘蓝、胡萝卜洗净切丝。\", \"全麦卷饼微微加热变软。\", \"将蔬菜和鸡丝铺在卷饼上，挤上少许低脂沙拉酱，卷紧切段。\"]', '[\"维持健康\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (318, '2025-12-26 18:42:54.000', '2025-12-26 18:42:54.000', NULL, '毛豆圣女果拼盘', '', '加餐', '简单', 10, 250.00, 18.00, 25.00, 8.00, '[\"毛豆 100g\", \"圣女果 100g\", \"玉米粒 50g\"]', '[\"毛豆洗净，加水煮熟，可加少许盐调味。\", \"圣女果洗净对半切开。\", \"玉米粒焯水煮熟。\", \"将所有食材混合放入碗中即可。\"]', '[\"维持健康\"]', '[]', 10, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (319, '2025-12-26 18:42:54.000', '2025-12-26 18:42:54.000', NULL, '香蕉燕麦能量棒', '', '加餐', '简单', 30, 380.00, 10.00, 60.00, 12.00, '[\"香蕉 1根\", \"即食燕麦片 80g\", \"蔓越莓干 15g\", \"奇亚籽 5g\"]', '[\"香蕉去皮捣成泥。\", \"将香蕉泥、燕麦片、蔓越莓干、奇亚籽混合均匀。\", \"混合物放入铺了烘焙纸的模具中压平实。\", \"放入预热180度的烤箱烤20分钟，取出放凉后切块。\"]', '[\"维持健康\"]', '[\"麸质\", \"高糖\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (320, '2025-12-26 19:06:05.000', '2025-12-26 19:06:05.000', NULL, '藜麦鸡胸肉沙拉', '', '午餐', '简单', 25, 420.00, 35.00, 45.00, 12.00, '[\"三色藜麦 80g\", \"鸡胸肉 150g\", \"罗马生菜 100g\", \"樱桃番茄 100g\", \"黄瓜 100g\", \"橄榄油 5ml\", \"柠檬汁 10ml\", \"盐 2g\", \"黑胡椒 1g\"]', '[\"藜麦淘洗干净，加水煮熟（约15分钟），沥干水分备用。\", \"鸡胸肉切块，用盐和黑胡椒腌制后，用少量橄榄油煎熟。\", \"罗马生菜洗净撕成小块，樱桃番茄和黄瓜切片。\", \"将所有食材混合，淋上橄榄油和柠檬汁，拌匀即可。\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (321, '2025-12-26 19:06:05.000', '2025-12-26 19:06:05.000', NULL, '豆腐杂粮饭便当', '', '午餐', '简单', 30, 390.00, 28.00, 42.00, 9.00, '[\"糙米 70g\", \"老豆腐 200g\", \"西兰花 150g\", \"胡萝卜 50g\", \"香菇 50g\", \"生抽 10ml\", \"蚝油 5ml\", \"蒜末 5g\"]', '[\"糙米提前浸泡1小时后煮熟。\", \"老豆腐切厚片，用厨房纸巾吸干水分。\", \"不粘锅刷薄油，将豆腐煎至两面金黄，加入生抽、蚝油和少量水焖煮入味。\", \"西兰花、胡萝卜、香菇洗净切块，焯水或清炒熟。\", \"将所有食材搭配杂粮饭装盘。\"]', '[\"控糖\"]', '[\"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (322, '2025-12-26 19:06:05.000', '2025-12-26 19:06:05.000', NULL, '鹰嘴豆泥蔬菜卷', '', '午餐', '简单', 20, 380.00, 18.00, 50.00, 11.00, '[\"全麦卷饼 1张（60g）\", \"熟鹰嘴豆 150g\", \"希腊酸奶 30g\", \"芝麻酱 10g\", \"菠菜 100g\", \"彩椒 50g\", \"柠檬汁 5ml\"]', '[\"熟鹰嘴豆、希腊酸奶、芝麻酱、柠檬汁放入料理机打成泥状。\", \"菠菜洗净，彩椒切丝。\", \"全麦卷饼微微加热变软。\", \"将鹰嘴豆泥铺在卷饼上，放上菠菜和彩椒丝，卷紧切段。\"]', '[\"控糖\"]', '[\"乳制品\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (323, '2025-12-26 19:06:05.000', '2025-12-26 19:06:05.000', NULL, '清蒸鲈鱼配荞麦面', '', '午餐', '中等', 25, 410.00, 32.00, 48.00, 8.00, '[\"鲈鱼 1条（约300g）\", \"荞麦面 80g\", \"生姜 10g\", \"葱 10g\", \"蒸鱼豉油 15ml\", \"芝麻油 3ml\", \"小油菜 150g\"]', '[\"鲈鱼处理干净，鱼身划几刀，姜切片、葱切丝铺在鱼上。\", \"水开后上锅蒸8-10分钟至熟。\", \"荞麦面煮熟过凉水，小油菜焯水。\", \"蒸好的鱼淋上蒸鱼豉油和芝麻油。\", \"将鱼、荞麦面和小油菜摆盘。\"]', '[\"控糖\"]', '[\"海鲜\", \"麸质\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (324, '2025-12-26 19:06:05.000', '2025-12-26 19:06:05.000', NULL, '菌菇烩杂粮饭', '', '午餐', '简单', 20, 370.00, 15.00, 55.00, 10.00, '[\"糙米+燕麦米 80g\", \"口蘑 100g\", \"杏鲍菇 100g\", \"白玉菇 50g\", \"洋葱 50g\", \"蒜片 5g\", \"低钠酱油 10ml\", \"橄榄油 5ml\"]', '[\"杂粮米提前煮熟。\", \"各种菌菇和洋葱洗净切片。\", \"锅中放橄榄油，爆香蒜片和洋葱，加入菌菇翻炒至软。\", \"加入少量水和低钠酱油，烩煮片刻至汤汁稍收。\", \"将菌菇浇在杂粮饭上即可。\"]', '[\"控糖\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (327, '2025-12-26 19:07:05.000', '2025-12-26 19:07:05.000', NULL, '牛肉藜麦碗', '', '午餐', '中等', 25, 520.00, 38.00, 50.00, 18.00, '[\"瘦牛肉 150g\", \"藜麦 100g\", \"菠菜 100g\", \"蘑菇 80g\", \"核桃 15g\", \"橄榄油 5g\"]', '[\"藜麦煮熟备用\", \"牛肉切条炒熟\", \"蘑菇和菠菜炒软\", \"所有食材装碗，撒上核桃碎\"]', '[\"增肌\"]', '[\"牛肉\", \"坚果\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (328, '2025-12-26 19:07:05.000', '2025-12-26 19:07:05.000', NULL, '豆腐蔬菜炒饭', '', '午餐', '简单', 15, 420.00, 31.00, 42.00, 14.00, '[\"老豆腐 200g\", \"糙米饭 150g\", \"鸡蛋 1个\", \"青豆 50g\", \"玉米 50g\", \"芝麻油 5g\"]', '[\"豆腐压碎炒干\", \"鸡蛋炒散备用\", \"所有食材一起翻炒，加入适量酱油调味\"]', '[\"增肌\"]', '[\"蛋类\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (329, '2025-12-26 19:07:05.000', '2025-12-26 19:07:05.000', NULL, '土耳其烤肉配全麦皮塔饼', '', '午餐', '中等', 30, 490.00, 36.00, 48.00, 16.00, '[\"火鸡肉 150g\", \"全麦皮塔饼 2个\", \"希腊酸奶 50g\", \"黄瓜 100g\", \"番茄 80g\", \"橄榄油 5g\"]', '[\"火鸡肉切条腌制后煎熟\", \"皮塔饼加热\", \"黄瓜番茄切丁与希腊酸奶混合\", \"所有食材卷入皮塔饼中\"]', '[\"增肌\"]', '[\"乳制品\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (330, '2025-12-26 19:13:46.000', '2025-12-26 19:13:46.000', NULL, '毛豆蛋白蔬菜杯', '', '加餐', '简单', 12, 320.00, 25.00, 28.00, 12.00, '[\"毛豆仁 100g\", \"彩椒 80g\", \"鸡胸肉糜 50g\", \"香菜 10g\", \"米醋 5ml\", \"生抽 3ml\"]', '[\"毛豆仁煮熟沥干，彩椒切小丁\", \"鸡胸肉糜用少许生抽腌制后快速炒熟\", \"所有食材混合，加入米醋拌匀\", \"装入小杯或碗中即可食用\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (331, '2025-12-26 19:13:46.000', '2025-12-26 19:13:46.000', NULL, '燕麦麸皮蛋白松饼', '', '加餐', '简单', 18, 350.00, 28.00, 42.00, 9.50, '[\"燕麦麸皮 40g\", \"鸡蛋清 3个\", \"香蕉 半根\", \"泡打粉 3g\", \"肉桂粉 2g\"]', '[\"香蕉捣成泥，与燕麦麸皮、蛋清、泡打粉、肉桂粉混合成面糊\", \"平底锅小火加热，倒入适量面糊\", \"煎至两面金黄即可\", \"可搭配少量新鲜莓果食用\"]', '[\"减脂\"]', '[\"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (332, '2025-12-26 19:13:46.000', '2025-12-26 19:13:46.000', NULL, '魔芋豆腐蔬菜拌', '', '加餐', '简单', 10, 190.00, 15.00, 20.00, 6.00, '[\"魔芋豆腐 150g\", \"黄瓜 100g\", \"胡萝卜 50g\", \"白醋 8ml\", \"芝麻油 3ml\", \"白芝麻 2g\"]', '[\"魔芋豆腐切条焯水，黄瓜、胡萝卜切丝\", \"所有食材放入碗中，加入白醋、芝麻油拌匀\", \"撒上白芝麻即可食用\"]', '[\"减脂\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (333, '2025-12-26 19:13:46.000', '2025-12-26 19:13:46.000', NULL, '奇亚籽布丁配火龙果', '', '加餐', '简单', 5, 310.00, 22.00, 35.00, 11.00, '[\"奇亚籽 30g\", \"无糖杏仁奶 200ml\", \"火龙果 100g\", \"蛋白粉 15g\", \"香草精 2滴\"]', '[\"奇亚籽、蛋白粉与杏仁奶混合搅拌均匀\", \"加入香草精，冷藏2小时以上形成布丁状\", \"火龙果切丁\", \"食用时将火龙果丁铺在布丁上即可\"]', '[\"减脂\"]', '[\"乳制品\", \"坚果\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (334, '2025-12-26 19:13:48.000', '2025-12-26 19:13:48.000', NULL, '泰式青木瓜蟹肉沙拉', '', '晚餐', '简单', 15, 380.00, 32.00, 35.00, 8.00, '[\"青木瓜 200g\", \"蟹肉棒 100g\", \"樱桃番茄 80g\", \"青柠汁 15ml\", \"鱼露 5ml\", \"小米辣 2g\"]', '[\"青木瓜切丝冰镇10分钟\", \"蟹肉棒撕成细条，番茄对半切\", \"混合青柠汁、鱼露、小米辣调汁\", \"所有食材拌匀装盘\"]', '[\"减脂\"]', '[\"海鲜\", \"辛辣\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (335, '2025-12-26 19:13:48.000', '2025-12-26 19:13:48.000', NULL, '羽衣甘蓝鹰嘴豆泥卷', '', '晚餐', '中等', 25, 420.00, 28.00, 45.00, 12.00, '[\"羽衣甘蓝叶 4片\", \"熟鹰嘴豆 150g\", \"芝麻酱 10g\", \"柠檬汁 10ml\", \"彩椒条 50g\"]', '[\"鹰嘴豆+芝麻酱+柠檬汁打成泥\", \"羽衣甘蓝叶焯水10秒后冰镇\", \"叶片平铺抹豆泥，放彩椒条\", \"卷紧后斜切装盘\"]', '[\"减脂\"]', '[\"坚果\", \"乳制品\"]', 8, 100.00);
