INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (373, '2025-12-26 19:15:18.000', '2025-12-26 19:15:18.000', NULL, '芦笋腰果酱荞麦卷', '', '加餐', '中等', 25, 410.00, 22.00, 38.00, 15.00, '[\"荞麦饼皮 2张\", \"芦笋 80g\", \"生腰果 30g\", \"柠檬汁 5ml\", \"莳萝 2g\"]', '[\"腰果浸泡后与柠檬汁打成酱\", \"芦笋快速焯水保持脆度\", \"用饼皮包裹所有食材卷切\"]', '[\"控糖\"]', '[\"坚果\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (374, '2025-12-26 19:15:23.000', '2025-12-26 19:15:23.000', NULL, '南瓜鹰嘴豆泥配全麦皮塔饼与黄瓜番茄沙拉', '', '午餐', '简单', 20, 420.00, 18.00, 65.00, 12.00, '[\"熟南瓜 150g\", \"熟鹰嘴豆 80g\", \"芝麻酱 15g\", \"柠檬汁 10ml\", \"全麦皮塔饼 1个\", \"黄瓜 100g\", \"小番茄 80g\", \"红洋葱 20g\", \"橄榄油 5ml\", \"盐 1g\", \"黑胡椒 少许\"]', '[\"南瓜蒸熟压成泥，鹰嘴豆沥干水分。\", \"将南瓜泥、鹰嘴豆、芝麻酱、柠檬汁、少许盐和黑胡椒放入料理机搅打顺滑，制成蘸酱。\", \"黄瓜、小番茄、红洋葱切丁混合，用橄榄油和少许黑胡椒调味制成沙拉。\", \"全麦皮塔饼稍微加热后切块，与蘸酱和沙拉一同摆盘。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (375, '2025-12-26 19:15:23.000', '2025-12-26 19:15:23.000', NULL, '火鸡胸肉牛油果卷佐芒果莎莎', '', '午餐', '简单', 15, 380.00, 35.00, 25.00, 16.00, '[\"火鸡胸肉片 120g\", \"牛油果 半个\", \"全麦卷饼 1张\", \"芒果 50g\", \"红甜椒 30g\", \"青柠汁 5ml\", \"香菜 少许\", \"希腊酸奶 20g\", \"第戎芥末酱 5g\"]', '[\"火鸡胸肉片用平底锅无油煎熟或烤箱烤熟。\", \"牛油果切片。芒果、红甜椒切小丁，与香菜、青柠汁混合制成芒果莎莎。\", \"将希腊酸奶与第戎芥末酱混合制成抹酱，涂在全麦卷饼上。\", \"依次铺上火鸡肉片、牛油果片，卷起定型，对半切开，旁边搭配芒果莎莎。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (376, '2025-12-26 19:15:23.000', '2025-12-26 19:15:23.000', NULL, '姜黄风味椰浆鸡配野米饭与芦笋', '', '午餐', '中等', 30, 450.00, 32.00, 45.00, 15.00, '[\"鸡腿肉（去皮） 150g\", \"野米与糙米混合饭 150g\", \"芦笋 100g\", \" light椰浆 50ml\", \"姜黄粉 3g\", \"姜末 5g\", \"蒜末 5g\", \"洋葱 30g\", \"鱼露 3ml\", \"椰子油 5g\"]', '[\"野米与糙米提前浸泡后煮熟。鸡腿肉切块。\", \"锅中放椰子油，炒香姜末、蒜末、洋葱丝，加入鸡块炒至变色。\", \"加入姜黄粉翻炒均匀，倒入 light椰浆和少量水，小火炖煮10分钟，最后用鱼露调味。\", \"芦笋焯水或快速煎熟。将米饭、咖喱鸡和芦笋摆盘。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (377, '2025-12-26 19:15:23.000', '2025-12-26 19:15:23.000', NULL, '地中海风味烤章鱼配藜麦塔布勒沙拉', '', '午餐', '中等', 25, 390.00, 33.00, 38.00, 11.00, '[\"熟章鱼足 100g\", \"三色藜麦 50g\", \"欧芹 20g\", \"薄荷叶 10g\", \"番茄 50g\", \"黄瓜 50g\", \"红洋葱 15g\", \"柠檬汁 10ml\", \"橄榄油 5ml\", \"甜椒粉 2g\", \"大蒜粉 2g\"]', '[\"藜麦煮熟后放凉。章鱼足用甜椒粉、大蒜粉和少量橄榄油腌制10分钟。\", \"将欧芹、薄荷切碎，番茄、黄瓜、红洋葱切小丁。\", \"将冷却的藜麦与切好的蔬菜混合，加入柠檬汁、橄榄油、盐和黑胡椒调味，制成塔布勒沙拉。\", \"腌制好的章鱼足放入预热200度的烤箱烤8-10分钟，或煎至表面微焦。与沙拉一同摆盘。\"]', '[\"维持健康\"]', '[\"海鲜\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (378, '2025-12-26 19:15:23.000', '2025-12-26 19:15:23.000', NULL, '泰式香草豆腐碎生菜包', '', '午餐', '简单', 20, 350.00, 22.00, 30.00, 15.00, '[\"老豆腐 150g\", \"罗马生菜 数片\", \"香菇 30g\", \"胡萝卜 30g\", \"香菜 10g\", \"薄荷 5g\", \"青柠汁 10ml\", \"鱼露 3ml\", \"生姜 5g\", \"大蒜 5g\", \"椰子油 5g\"]', '[\"老豆腐捏碎，香菇、胡萝卜切小粒，生姜、大蒜切末，香菜薄荷切碎。\", \"锅中放椰子油，炒香姜蒜末，加入豆腐碎炒干水分。\", \"加入香菇粒和胡萝卜粒翻炒至熟，用鱼露和青柠汁调味。\", \"离火后拌入香菜和薄荷碎。用罗马生菜叶包裹豆腐馅料食用。\"]', '[\"维持健康\"]', '[]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (379, '2025-12-26 19:15:48.000', '2025-12-26 19:15:48.000', NULL, '南瓜鹰嘴豆咖喱配糙米', '', '晚餐', '简单', 25, 380.00, 18.00, 60.00, 8.00, '[\"南瓜 200g\", \"鹰嘴豆（熟） 100g\", \"椰奶 50ml\", \"咖喱粉 5g\", \"糙米 80g\", \"洋葱 50g\", \"橄榄油 5ml\"]', '[\"糙米提前浸泡30分钟，煮熟备用\", \"南瓜去皮切块，洋葱切丝\", \"橄榄油炒香洋葱，加入南瓜和咖喱粉翻炒\", \"倒入椰奶和少量水，炖煮至南瓜软烂\", \"加入熟鹰嘴豆煮5分钟，搭配糙米食用\"]', '[\"维持健康\"]', '[\"坚果\", \"乳制品\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (380, '2025-12-26 19:15:48.000', '2025-12-26 19:15:48.000', NULL, '泰式青木瓜虾仁沙拉配小米', '', '晚餐', '中等', 20, 350.00, 25.00, 45.00, 7.00, '[\"青木瓜 150g\", \"虾仁 80g\", \"樱桃番茄 50g\", \"青柠汁 15ml\", \"鱼露 3ml\", \"小米 60g\", \"薄荷叶 5g\"]', '[\"小米煮熟备用\", \"青木瓜切丝，虾仁焯熟\", \"混合青柠汁、鱼露制成酱汁\", \"所有食材拌匀，撒薄荷叶\", \"搭配小米食用\"]', '[\"维持健康\"]', '[\"海鲜\", \"坚果\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (381, '2025-12-26 19:15:48.000', '2025-12-26 19:15:48.000', NULL, '羽衣甘蓝豆腐芝麻卷', '', '晚餐', '中等', 15, 320.00, 22.00, 30.00, 12.00, '[\"羽衣甘蓝叶 4片\", \"嫩豆腐 100g\", \"胡萝卜 50g\", \"芝麻酱 10g\", \"全麦卷饼 1张\", \"柠檬汁 5ml\"]', '[\"羽衣甘蓝焯水软化\", \"豆腐压碎拌入芝麻酱和柠檬汁\", \"胡萝卜切丝\", \"用羽衣甘蓝叶包裹豆腐馅和胡萝卜丝\", \"外层用全麦卷饼固定\"]', '[\"维持健康\"]', '[\"乳制品\", \"蛋类\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (382, '2025-12-26 19:15:48.000', '2025-12-26 19:15:48.000', NULL, '彩椒酿藜麦鸡蓉', '', '晚餐', '中等', 30, 400.00, 28.00, 35.00, 15.00, '[\"三色彩椒 2个\", \"鸡胸肉糜 120g\", \"藜麦 50g\", \"洋葱 30g\", \"橄榄油 5ml\", \"迷迭香 2g\"]', '[\"藜麦煮熟备用\", \"彩椒去顶挖空\", \"炒香洋葱，与鸡蓉、藜麦混合\", \"填入彩椒，撒迷迭香\", \"180℃烤20分钟\"]', '[\"维持健康\"]', '[\"乳制品\", \"坚果\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (383, '2025-12-26 19:15:48.000', '2025-12-26 19:15:48.000', NULL, '韩式辣酱魔芋丝拌时蔬', '', '晚餐', '简单', 15, 280.00, 15.00, 40.00, 5.00, '[\"魔芋丝 100g\", \"菠菜 50g\", \"豆芽 50g\", \"韩式辣酱 5g\", \"芝麻 2g\", \"苹果醋 5ml\"]', '[\"魔芋丝焯水去腥\", \"蔬菜焯水断生\", \"混合韩式辣酱和苹果醋\", \"所有食材拌匀\", \"撒芝麻\"]', '[\"维持健康\"]', '[\"辛辣\", \"海鲜\"]', 7, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (384, '2025-12-26 19:17:59.000', '2025-12-26 19:17:59.000', NULL, '奇亚籽椰香芒果布丁', '', '加餐', '简单', 10, 350.00, 8.00, 45.00, 12.00, '[\"奇亚籽 30g\", \"椰子水 200ml\", \"芒果肉 100g\", \"杏仁片 5g\"]', '[\"奇亚籽与椰子水混合搅拌，冷藏4小时至凝固\", \"芒果切丁铺在布丁表面\", \"撒烤杏仁片增加口感\"]', '[\"维持健康\"]', '[\"坚果过敏\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (385, '2025-12-26 19:17:59.000', '2025-12-26 19:17:59.000', NULL, '藜麦羽衣甘蓝脆片沙拉', '', '加餐', '中等', 15, 380.00, 18.00, 50.00, 12.00, '[\"熟藜麦 80g\", \"羽衣甘蓝叶 50g\", \"樱桃萝卜 3个\", \"烤南瓜籽 10g\", \"柠檬汁 5ml\"]', '[\"羽衣甘蓝去茎撕碎，用橄榄油按摩至软化\", \"混合藜麦、薄片樱桃萝卜\", \"撒南瓜籽，淋柠檬汁调味\"]', '[\"维持健康\"]', '[\"麸质过敏\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (386, '2025-12-26 19:17:59.000', '2025-12-26 19:17:59.000', NULL, '魔芋丝凉拌秋葵虾仁', '', '加餐', '简单', 12, 320.00, 25.00, 35.00, 8.00, '[\"魔芋丝 100g\", \"秋葵 5根\", \"虾仁 50g\", \"紫苏叶 3片\", \"柚子醋 5ml\"]', '[\"魔芋丝焯水30秒，秋葵切星形段\", \"虾仁用姜水煮熟\", \"所有食材拌柚子醋，紫苏叶切丝装饰\"]', '[\"维持健康\"]', '[\"海鲜过敏\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (387, '2025-12-26 19:17:59.000', '2025-12-26 19:17:59.000', NULL, '烤苹果核桃肉桂盅', '', '加餐', '中等', 20, 280.00, 6.00, 40.00, 10.00, '[\"富士苹果 1个\", \"核桃碎 15g\", \"肉桂粉 2g\", \"椰子酸奶 30g\"]', '[\"苹果去芯，填入核桃碎和肉桂粉\", \"180℃烤15分钟至软化\", \"顶部点缀椰子酸奶\"]', '[\"维持健康\"]', '[\"坚果过敏\", \"乳糖不耐\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (388, '2025-12-26 19:17:59.000', '2025-12-26 19:17:59.000', NULL, '紫甘蓝梨子亚麻籽卷', '', '加餐', '简单', 10, 310.00, 12.00, 38.00, 9.00, '[\"紫甘蓝叶 2片\", \"鸡胸肉丝 50g\", \"雪梨条 30g\", \"亚麻籽粉 5g\", \"芥末籽酱 3g\"]', '[\"紫甘蓝叶焯水软化\", \"铺鸡胸肉丝、梨子条\", \"撒亚麻籽粉，芥末籽酱调味卷起\"]', '[\"维持健康\"]', '[\"辛辣敏感\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (389, '2025-12-26 19:21:38.000', '2025-12-26 19:21:38.000', NULL, '奇亚籽鸡胸肉紫菜卷', '', '早餐', '简单', 15, 380.00, 35.00, 25.00, 8.00, '[\"鸡胸肉 120g\", \"奇亚籽 10g\", \"紫菜片 2张\", \"黄瓜 50g\", \"胡萝卜 30g\"]', '[\"鸡胸肉用少量盐和黑胡椒腌制10分钟，蒸熟后撕成细丝\", \"奇亚籽用温水泡发至粘稠状\", \"紫菜片平铺，涂抹奇亚籽胶，铺鸡丝和切丝的黄瓜胡萝卜\", \"卷紧后切段食用\"]', '[\"减脂\"]', '[\"海鲜\"]', 9, 100.00);
