INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (443, '2025-12-26 19:23:43.000', '2025-12-26 19:23:43.000', NULL, '韩式辣酱牛肉豆腐煲配紫米饭', '', '晚餐', '中等', 35, 480.00, 38.00, 45.00, 12.00, '[\"牛里脊肉 150g\", \"嫩豆腐 200g\", \"金针菇 100g\", \"韩式辣酱 15g\", \"紫米 80g\", \"鸡蛋 1个\", \"青葱 适量\"]', '[\"紫米提前浸泡30分钟，煮熟备用\", \"牛里脊切薄片，用少量酱油和料酒腌制\", \"砂锅中加水烧开，放入韩式辣酱调匀\", \"加入金针菇和牛肉片煮3分钟\", \"放入嫩豆腐块，小火炖煮10分钟\", \"打入鸡蛋，撒上青葱，搭配紫米饭食用\"]', '[\"增肌\"]', '[\"辛辣\", \"牛肉\"]', 9, 100.00);
