INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (445, '2025-12-26 19:23:43.000', '2025-12-26 19:23:43.000', NULL, '秘制鸭胸配焦糖苹果藜麦饭', '', '晚餐', '中等', 30, 460.00, 32.00, 42.00, 14.00, '[\"鸭胸肉 180g\", \"三色藜麦 60g\", \"苹果 1个\", \"蜂蜜 5g\", \"迷迭香 适量\", \"菠菜 100g\"]', '[\"藜麦煮熟备用，鸭胸肉表面划十字花刀\", \"平底锅不放油，鸭皮朝下煎至金黄出油\", \"翻面继续煎3分钟，放入烤箱180度烤8分钟\", \"苹果切块，用鸭油煎至焦糖化，加入蜂蜜\", \"菠菜快速翻炒作为配菜\", \"鸭胸切片，搭配藜麦饭和焦糖苹果\"]', '[\"增肌\"]', '[\"猪肉\", \"牛肉\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (446, '2025-12-26 19:23:43.000', '2025-12-26 19:23:43.000', NULL, '墨鱼汁意面配扇贝芦笋', '', '晚餐', '中等', 20, 440.00, 36.00, 48.00, 9.00, '[\"墨鱼汁意面 80g\", \"新鲜扇贝 6个\", \"芦笋 150g\", \"大蒜 2瓣\", \"白葡萄酒 20ml\", \"橄榄油 5g\"]', '[\"意面按包装说明煮熟，保留少许煮面水\", \"扇贝用厨房纸吸干水分，两面撒盐和黑胡椒\", \"芦笋切段焯水1分钟\", \"热锅少油，将扇贝每面煎1分钟至金黄\", \"加入大蒜和芦笋翻炒，淋入白葡萄酒\", \"加入煮好的意面拌匀，用煮面水调整浓稠度\"]', '[\"增肌\"]', '[\"海鲜\", \"麸质\"]', 8, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (447, '2025-12-26 19:23:43.000', '2025-12-26 19:23:43.000', NULL, '藏式牦牛肉青稞炖菜', '', '晚餐', '简单', 40, 500.00, 42.00, 52.00, 13.00, '[\"牦牛肉 200g\", \"青稞米 70g\", \"土豆 150g\", \"胡萝卜 100g\", \"藏红花 少许\", \"香菜 适量\"]', '[\"青稞米提前浸泡2小时，牦牛肉切块焯水\", \"高压锅中放入所有食材，加水没过食材\", \"加入藏红花和适量盐调味\", \"高压炖煮25分钟至肉质软烂\", \"自然泄压后开盖，撒香菜装饰\", \"可根据个人口味加入少量辣椒粉\"]', '[\"增肌\"]', '[\"牛肉\", \"辛辣\"]', 9, 100.00);
INSERT INTO `recipes` (`id`, `created_at`, `updated_at`, `deleted_at`, `name`, `image_url`, `meal_type`, `difficulty`, `cooking_time`, `energy`, `protein`, `carbohydrate`, `fat`, `ingredients`, `cooking_steps`, `target_users`, `forbidden_users`, `health_score`, `portion_weight_g`) VALUES (448, '2025-12-26 19:23:44.000', '2025-12-26 19:23:44.000', NULL, '韩式泡菜牛肉豆腐锅配糙米', '', '晚餐', '中等', 30, 450.00, 35.00, 45.00, 12.00, '[\"瘦牛肉片 150g\", \"老豆腐 200g\", \"韩式泡菜 100g\", \"金针菇 80g\", \"豆芽 50g\", \"糙米饭 150g\", \"葱段 20g\", \"低钠酱油 10ml\"]', '[\"糙米提前浸泡1小时后煮熟备用\", \"锅中加水煮沸，放入泡菜煮出味道\", \"加入牛肉片、豆腐块、金针菇、豆芽同煮\", \"调入低钠酱油调味\", \"最后撒入葱段，配糙米饭食用\"]', '[\"增肌\"]', '[\"辛辣\", \"牛肉\"]', 8, 100.00);
